export function computeCinematicOverviewDistance(
  bounds: SolarSystemSnapshot["bounds"],
  aspect: number
): number {
  const width = bounds.maxX - bounds.minX;
  const height = bounds.maxY - bounds.minY;
  const aspectSafeWidth = width / Math.max(0.2, aspect);
  return clamp(
    Math.max(aspectSafeWidth, height) * strategicOverviewDistanceMultiplier,
    minDistance,
    maxDistance
  );
}

export function computeReceiverEclipseDiskRadius(
  options: Readonly<{
    edgeFeather: number;
    minDiskRadius: number;
    receiverRadius: number;
    shadowAxisOffset: number;
    shadowRadius: number;
  }>
): number {
  const receiverRadius = Math.max(0.001, options.receiverRadius);
  const shadowRadius = Math.max(0, options.shadowRadius);
  const shadowAxisOffset = Math.max(0, options.shadowAxisOffset);
  const fullDayHemisphereDiskRadius = Math.SQRT2 + Math.max(0.001, options.edgeFeather) * 2;

  if (shadowRadius >= shadowAxisOffset + receiverRadius * 0.995) {
    return fullDayHemisphereDiskRadius;
  }

  if (shadowRadius <= 0 || shadowAxisOffset >= shadowRadius + receiverRadius) {
    return options.minDiskRadius;
  }

  let capCosine: number;

  if (shadowAxisOffset <= receiverRadius * 0.001) {
    const centeredFootprintRatio = clamp(shadowRadius / receiverRadius, 0, 1);
    capCosine = Math.sqrt(Math.max(0, 1 - centeredFootprintRatio * centeredFootprintRatio));
  } else {
    capCosine = clamp(
      (shadowAxisOffset * shadowAxisOffset +
        receiverRadius * receiverRadius -
        shadowRadius * shadowRadius) /
        (2 * shadowAxisOffset * receiverRadius),
      -1,
      1
    );
  }

  const chordRadius = Math.sqrt(Math.max(0, 2 - 2 * capCosine));
  return clamp(chordRadius, options.minDiskRadius, fullDayHemisphereDiskRadius);
}

type MutableCinematicPerformanceSectionStats = {
  lastMs: number;
  averageMs: number;
  maxMs: number;
};

function createPerformanceSectionStats(): Record<
  CinematicPerformanceSectionKey,
  MutableCinematicPerformanceSectionStats
> {
  const sections = {} as Record<
    CinematicPerformanceSectionKey,
    MutableCinematicPerformanceSectionStats
  >;

  for (const key of performanceSectionKeys) {
    sections[key] = {
      lastMs: 0,
      averageMs: 0,
      maxMs: 0
    };
  }

  return sections;
}

type GpuTimerQueryExtension = Readonly<{
  TIME_ELAPSED_EXT: number;
  GPU_DISJOINT_EXT: number;
}>;

type GpuFrameTimer = {
  readonly context: WebGL2RenderingContext;
  readonly extension: GpuTimerQueryExtension;
  activeQuery: WebGLQuery | null;
  pendingQueries: WebGLQuery[];
  lastMs: number | null;
  averageMs: number | null;
  maxMs: number | null;
};

function createGpuFrameTimer(
  context: WebGLRenderingContext | WebGL2RenderingContext
): GpuFrameTimer | null {
  if (
    typeof WebGL2RenderingContext === "undefined" ||
    !(context instanceof WebGL2RenderingContext)
  ) {
    return null;
  }

  const extension = context.getExtension(
    "EXT_disjoint_timer_query_webgl2"
  ) as GpuTimerQueryExtension | null;

  if (extension === null) {
    return null;
  }

  return {
    context,
    extension,
    activeQuery: null,
    pendingQueries: [],
    lastMs: null,
    averageMs: null,
    maxMs: null
  };
}

type CinematicDecorativePointLightCandidate = {
  light: THREE.PointLight;
  readonly position: THREE.Vector3;
  score: number;
};

function createCinematicDecorativePointLightPool(
  namePrefix: string,
  layer: number
): THREE.PointLight[] {
  return Array.from({ length: cinematicDecorativePointLightPoolSize }, (_, index) => {
    const light = new THREE.PointLight(0xffffff, 0, 1, 2);
    light.name = `${namePrefix}-${index}`;
    light.layers.set(layer);
    light.userData["cinematicDecorativePointLightPool"] = true;
    return light;
  });
}

