function createTritiumCanister(index: number): TritiumCanister {
  const group = new THREE.Group();
  group.name = `viewer-tritium-orbital-canister-${index}`;
  group.visible = false;

  const model = new THREE.Group();
  model.name = "viewer-tritium-canister-model";
  group.add(model);

  const bodyMaterial = new THREE.MeshStandardMaterial({
    color: 0xc3d7d8,
    emissive: 0x22535a,
    emissiveIntensity: 0.28,
    roughness: 0.31,
    metalness: 0.78,
    transparent: true,
    opacity: 1
  });
  const capMaterial = new THREE.MeshStandardMaterial({
    color: 0xf1f6ee,
    emissive: 0x24494c,
    emissiveIntensity: 0.22,
    roughness: 0.24,
    metalness: 0.86,
    flatShading: true,
    transparent: true,
    opacity: 1
  });
  const bandMaterial = new THREE.MeshStandardMaterial({
    color: 0x35474e,
    emissive: 0x10262a,
    emissiveIntensity: 0.14,
    roughness: 0.36,
    metalness: 0.88,
    flatShading: true,
    transparent: true,
    opacity: 1
  });
  const glowMaterial = new THREE.MeshBasicMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 0.72,
    depthWrite: false,
    depthTest: true,
    blending: THREE.AdditiveBlending
  });

  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.044, 0.044, 0.132, 16), bodyMaterial);
  body.name = "viewer-tritium-canister-body";
  body.rotation.z = Math.PI / 2;
  body.renderOrder = tritiumOrbitalCanisterOverlayRenderOrder;
  model.add(body);

  for (const side of [-1, 1]) {
    const cap = new THREE.Mesh(
      new THREE.CylinderGeometry(0.05, 0.044, 0.022, 8),
      capMaterial.clone()
    );
    cap.name =
      side < 0 ? "viewer-tritium-canister-aft-hex-cap" : "viewer-tritium-canister-fore-hex-cap";
    cap.rotation.z = Math.PI / 2;
    cap.position.x = side * 0.077;
    cap.renderOrder = tritiumOrbitalCanisterOverlayRenderOrder;
    model.add(cap);

    const band = new THREE.Mesh(
      new THREE.CylinderGeometry(0.047, 0.047, 0.011, 16),
      bandMaterial.clone()
    );
    band.name =
      side < 0
        ? "viewer-tritium-canister-aft-retaining-band"
        : "viewer-tritium-canister-forward-retaining-band";
    band.rotation.z = Math.PI / 2;
    band.position.x = side * 0.043;
    band.renderOrder = tritiumOrbitalCanisterOverlayRenderOrder + 0.01;
    model.add(band);
  }

  const strip = new THREE.Mesh(new THREE.BoxGeometry(0.096, 0.0075, 0.012), glowMaterial.clone());
  strip.name = "viewer-tritium-canister-cyan-core-strip";
  strip.position.set(0, 0.047, -0.001);
  strip.renderOrder = tritiumOrbitalCanisterOverlayRenderOrder + 0.05;
  model.add(strip);

  const beaconPost = new THREE.Mesh(
    new THREE.BoxGeometry(0.014, 0.032, 0.014),
    bandMaterial.clone()
  );
  beaconPost.name = "viewer-tritium-canister-blinker-post";
  beaconPost.position.set(0.014, 0.061, 0);
  beaconPost.renderOrder = tritiumOrbitalCanisterOverlayRenderOrder + 0.08;
  model.add(beaconPost);

  const beaconLight = markCinematicDecorativePointLightSource(
    new THREE.PointLight(0xffffff, 0, tritiumCanisterBeaconLightDistance, 2.4),
    cinematicUiBloomRenderLayer
  );
  beaconLight.name = "viewer-tritium-canister-blinker-light";
  beaconLight.position.copy(tritiumCanisterBeaconLightLocalPosition);
  group.add(beaconLight);

  const closeBeacon = createTritiumCanisterCloseBeacon();
  closeBeacon.position.copy(tritiumCanisterBeaconLightLocalPosition);
  group.add(closeBeacon);

  const bokehBeacon = createTritiumCanisterBokehPoint();
  group.add(bokehBeacon);

  makeTritiumCanisterDepthReadable(group);
  setExclusiveObjectRenderLayer(group, cinematicUiBloomRenderLayer);

  return {
    group,
    model,
    glowStrip: strip,
    closeBeacon,
    bokehBeacon,
    beaconLight,
    startTime: Number.POSITIVE_INFINITY,
    ascentDuration: 2.2,
    lifetime: 18,
    startLongitude: 0,
    startLatitude: 0,
    startY: 0,
    orbitEntryLongitude: 0,
    orbitSpeed: tritiumOrbitalCanisterOrbitAngularSpeed,
    captureStartTime: Number.POSITIVE_INFINITY,
    captureDuration: 0.36,
    captureStartPosition: new THREE.Vector3(),
    previousPosition: new THREE.Vector3(),
    active: false,
    capturing: false,
    hasPreviousPosition: false
  };
}

function createTritiumCanisterCloseBeacon(): THREE.Points<
  THREE.BufferGeometry,
  THREE.PointsMaterial
> {
  const material = new THREE.PointsMaterial({
    color: 0xffffff,
    map: getSharpPointTexture("tritium-canister-close-beacon", 0xffffff),
    size: tritiumCanisterCloseBeaconPixels,
    sizeAttenuation: false,
    transparent: true,
    opacity: 0,
    alphaTest: 0.08,
    depthWrite: false,
    depthTest: true,
    blending: THREE.AdditiveBlending
  });
  material.toneMapped = false;

  const beacon = new THREE.Points(getRetinalPointGeometry(), material);
  beacon.name = "tritium-canister-close-beacon";
  beacon.renderOrder = tritiumOrbitalCanisterOverlayRenderOrder + 0.2;
  beacon.visible = false;
  beacon.userData["usesSharedGeometry"] = true;
  return beacon;
}

function createTritiumCanisterBokehPoint(): THREE.Sprite {
  const material = new THREE.SpriteMaterial({
    map: getBokehPointTexture("tritium-canister-bokeh-point", 0xffffff),
    color: 0xffffff,
    opacity: 0,
    transparent: true,
    depthWrite: false,
    depthTest: true,
    blending: THREE.NormalBlending
  });
  material.toneMapped = false;
  material.sizeAttenuation = false;

  const sprite = new THREE.Sprite(material);
  sprite.name = "tritium-canister-bokeh-point";
  sprite.renderOrder = tritiumOrbitalCanisterOverlayRenderOrder + 0.14;
  sprite.visible = false;
  sprite.scale.setScalar(0.03);
  return sprite;
}

function makeTritiumCanisterDepthReadable(root: THREE.Object3D): void {
  root.traverse((child) => {
    if (!isDisposableRenderable(child)) {
      return;
    }

    child.renderOrder = Math.max(child.renderOrder, tritiumOrbitalCanisterOverlayRenderOrder);
    const materials = Array.isArray(child.material) ? child.material : [child.material];

    for (const material of materials) {
      material.depthWrite = false;
      material.transparent = true;
    }
  });
}

function updateTritiumWorkEffect(
  effect: TritiumWorkEffect,
  frame: TritiumWorkFrame,
  elapsed: number,
  camera: THREE.PerspectiveCamera,
  detailProgress: number,
  allowLaunches: boolean,
  beatPulse: CinematicVisualPulse | null
): void {
  const retireOpacityMultiplier = getTritiumWorkEffectRetireOpacity(effect, elapsed);

  if (allowLaunches && effect.nextLaunchTime <= 0 && beatPulse !== null) {
    effect.nextLaunchTime =
      elapsed +
      getMillisecondsUntilNextBeatGrid(beatPulse, presentationCycleBeatGridSubdivisions, 1000) /
        1000;
  }

  if (allowLaunches && elapsed >= effect.nextLaunchTime) {
    emitTritiumCanister(effect, frame, elapsed, beatPulse);
  }

  for (const flash of effect.flashes) {
    updateTritiumFlash(flash, frame, elapsed, retireOpacityMultiplier, detailProgress);
  }

  for (const canister of effect.canisters) {
    updateTritiumCanister(
      effect,
      canister,
      frame,
      elapsed,
      camera,
      retireOpacityMultiplier,
      allowLaunches,
      beatPulse
    );
  }

  for (const flash of effect.scoopFlashes) {
    updateTritiumScoopFlash(flash, frame, elapsed, retireOpacityMultiplier);
  }

  effect.receiverHalo.visible = false;
  effect.receiverCore.visible = false;
  effect.receiverLight.visible = false;
  effect.receiverLight.intensity = 0;
  updateTritiumReceiverScoopGlow(effect, frame, elapsed, retireOpacityMultiplier);
}

function getTritiumWorkEffectRetireOpacity(effect: TritiumWorkEffect, elapsed: number): number {
  if (!Number.isFinite(effect.retiringStartedAt)) {
    return 1;
  }

  const retireAge = Math.max(0, elapsed - effect.retiringStartedAt);
  return (
    1 -
    smootherStep(
      tritiumCanisterRetireFadeDelaySeconds,
      tritiumCanisterRetireFadeDelaySeconds + tritiumCanisterRetireFadeDurationSeconds,
      retireAge
    )
  );
}

function isTritiumWorkEffectRetired(effect: TritiumWorkEffect, elapsed: number): boolean {
  return (
    Number.isFinite(effect.retiringStartedAt) &&
    getTritiumWorkEffectRetireOpacity(effect, elapsed) <= 0.01
  );
}

function emitTritiumCanister(
  effect: TritiumWorkEffect,
  frame: TritiumWorkFrame,
  elapsed: number,
  beatPulse: CinematicVisualPulse | null
): void {
  const launchIndex = effect.launchIndex;
  const startDelay = 0.3;
  const ascentDuration =
    tritiumOrbitalCanisterAscentMinSeconds +
    seededUnit(launchIndex, 80) * tritiumOrbitalCanisterAscentJitterSeconds;
  const orbitSpeed = tritiumOrbitalCanisterOrbitAngularSpeed;
  const surfaceDrift = frame.planetSpin * 0.18 + (seededUnit(launchIndex, 87) - 0.5) * 0.18;
  const launchTime = elapsed + startDelay;
  const insertionTime = launchTime + ascentDuration;
  let startLongitude = 0;
  let startLatitude = 0;
  let orbitEntryLongitude = 0;
  let bestClearance = Number.NEGATIVE_INFINITY;

  for (let attempt = 0; attempt < tritiumCanisterLaunchCandidateCount; attempt += 1) {
    const candidateSeed = launchIndex * 37 + attempt * 19;
    const candidateStartLongitude =
      seededUnit(candidateSeed, 84) * Math.PI * 2 +
      surfaceDrift +
      (seededUnit(candidateSeed, 88) - 0.5) * 0.08;
    const candidateStartLatitude = (seededUnit(candidateSeed, 91) - 0.5) * 0.18;
    const candidateOrbitEntryLongitude =
      candidateStartLongitude +
      Math.sign(orbitSpeed) * (0.42 + seededUnit(candidateSeed, 93) * 0.38);
    const preOrbitShipClearance = getTritiumCanisterPreOrbitShipClearance(
      frame,
      candidateStartLongitude,
      candidateStartLatitude,
      candidateOrbitEntryLongitude,
      orbitSpeed,
      ascentDuration,
      startDelay
    );

    if (preOrbitShipClearance < 0) {
      continue;
    }

    const canisterClearance = getTritiumCanisterSpacingClearance(
      effect,
      candidateStartLongitude,
      candidateOrbitEntryLongitude,
      launchTime,
      insertionTime
    );

    if (canisterClearance < 0) {
      continue;
    }

    const clearance = Math.min(
      preOrbitShipClearance / Math.max(0.001, frame.sceneUnitScale),
      canisterClearance
    );

    if (clearance > bestClearance) {
      startLongitude = candidateStartLongitude;
      startLatitude = candidateStartLatitude;
      orbitEntryLongitude = candidateOrbitEntryLongitude;
      bestClearance = clearance;
    }
  }

  if (bestClearance === Number.NEGATIVE_INFINITY) {
    effect.nextLaunchTime =
      elapsed +
      getBeatSynchronizedCycle(elapsed, tritiumCanisterLaunchCollisionRetrySeconds, beatPulse)
        .cycleSeconds;
    return;
  }

  const canister = effect.canisters.find((candidate) => !candidate.active) ?? effect.canisters[0];

  if (canister === undefined) {
    return;
  }

  canister.active = true;
  canister.capturing = false;
  canister.startTime = elapsed + startDelay;
  canister.ascentDuration = ascentDuration;
  canister.lifetime =
    tritiumOrbitalCanisterLifetimeMinSeconds +
    seededUnit(launchIndex, 81) * tritiumOrbitalCanisterLifetimeJitterSeconds;
  canister.startLongitude = startLongitude;
  canister.startLatitude = startLatitude;
  canister.startY = Math.sin(startLatitude) * frame.planetRadius;
  canister.orbitEntryLongitude = orbitEntryLongitude;
  canister.orbitSpeed = orbitSpeed;
  canister.captureStartTime = Number.POSITIVE_INFINITY;
  canister.captureStartPosition.set(0, 0, 0);
  canister.previousPosition.set(0, 0, 0);
  canister.hasPreviousPosition = false;
  canister.group.visible = false;
  canister.group.scale.setScalar(0.052 * frame.sceneUnitScale);
  setObjectOpacity(canister.group, 1);

  emitTritiumLaunchFlash(effect, elapsed, startLongitude, startLatitude);

  effect.launchIndex += 1;
  const launchSpacingSeconds =
    tritiumOrbitalCanisterLaunchSpacingSeconds +
    seededUnit(launchIndex, 103) * tritiumOrbitalCanisterLaunchJitterSeconds;
  effect.nextLaunchTime =
    elapsed + getBeatSynchronizedCycle(elapsed, launchSpacingSeconds, beatPulse).cycleSeconds;
}

function emitTritiumLaunchFlash(
  effect: TritiumWorkEffect,
  elapsed: number,
  startLongitude: number,
  startLatitude: number
): void {
  const flash = effect.flashes.find((candidate) => !candidate.active) ?? effect.flashes[0];

  if (flash === undefined) {
    return;
  }

  flash.active = true;
  flash.startTime = elapsed;
  flash.longitude = startLongitude;
  flash.latitude = startLatitude;
  flash.group.visible = true;
}

function emitTritiumScoopFlash(
  effect: TritiumWorkEffect,
  elapsed: number,
  receiverWorldPosition: THREE.Vector3
): void {
  const flash =
    effect.scoopFlashes.find((candidate) => !candidate.active) ?? effect.scoopFlashes[0];

  if (flash === undefined) {
    return;
  }

  flash.active = true;
  flash.startTime = elapsed;
  flash.group.position.copy(receiverWorldPosition);
  flash.group.visible = true;
  effect.lastScoopAt = elapsed;
}

function syncTritiumCanisterNodeColor(canister: TritiumCanister, color: THREE.Color): void {
  canister.glowStrip.material.color.copy(color);
  canister.closeBeacon.material.color.copy(color);
  syncSpriteMaterialColor(canister.bokehBeacon, color);
  canister.beaconLight.color.copy(color);
}

function syncSpriteMaterialColor(sprite: THREE.Sprite, color: THREE.Color): void {
  if (sprite.material instanceof THREE.SpriteMaterial) {
    sprite.material.color.copy(color);
  }
}

function updateTritiumFlash(
  flash: TritiumFlash,
  frame: TritiumWorkFrame,
  elapsed: number,
  opacityMultiplier: number,
  detailProgress: number
): void {
  if (!flash.active) {
    return;
  }

  const age = elapsed - flash.startTime;
  const duration = tritiumCanisterLaunchFlashDurationSeconds;

  if (age < 0 || age > duration) {
    flash.active = false;
    flash.group.visible = false;
    flash.light.intensity = 0;
    return;
  }

  const progress = age / duration;
  const burst = getNuclearStyleLaunchFlashBurst(progress);
  const zoomIntensity = getOrbitalCargoLaunchZoomIntensity(detailProgress);
  const surfacePoint = getTritiumFramePoint(
    frame,
    frame.planetRadius * tritiumCanisterLaunchFlashSurfaceScale,
    flash.latitude,
    flash.longitude
  );
  const normal = surfacePoint.clone().sub(frame.bodyPosition).normalize();
  const solarPointVisibility = frame.solarPointVisibilityForWorldPosition(surfacePoint);
  const localVisibility = THREE.MathUtils.lerp(
    orbitalCargoLaunchNightVisibilityFloor,
    1,
    solarPointVisibility
  );
  flash.group.position.copy(surfacePoint);
  flash.group.quaternion.setFromUnitVectors(mapPlaneUp, normal);
  syncOrbitalCargoLaunchFlashPoints(
    flash.core,
    flash.halo,
    burst,
    detailProgress,
    opacityMultiplier * localVisibility
  );
  flash.light.distance = frame.planetRadius * orbitalCargoLaunchPointLightRadiusMultiplier;
  flash.light.intensity =
    burst *
    tritiumCanisterLaunchFlashLightIntensity *
    orbitalCargoLaunchPointLightIntensityMultiplier *
    zoomIntensity *
    opacityMultiplier *
    localVisibility;
}

function getTritiumCanisterPreOrbitShipClearance(
  frame: TritiumWorkFrame,
  startLongitude: number,
  startLatitude: number,
  orbitEntryLongitude: number,
  orbitSpeed: number,
  ascentDuration: number,
  startDelay: number
): number {
  const shipOrbitRadius = getTritiumShipOrbitRadius(frame);
  const scoopPlaneLatitude = getTritiumCanisterScoopPlaneLatitude(frame, shipOrbitRadius);
  const orbitDirection = Math.sign(orbitSpeed) || 1;
  const orbitTangent = getTritiumOrbitTangent(
    frame.radialAxis,
    frame.tangentAxis,
    orbitEntryLongitude,
    orbitDirection
  );
  const insertionPoint = getTritiumFramePoint(
    frame,
    shipOrbitRadius,
    scoopPlaneLatitude,
    orbitEntryLongitude
  );
  const orbitMatchedHandleLength = clamp(
    (shipOrbitRadius * Math.abs(orbitSpeed) * ascentDuration) / 3,
    frame.planetRadius * 0.42,
    frame.planetRadius * 0.68
  );
  const launchPoint = getTritiumFramePoint(
    frame,
    frame.planetRadius * 1.035,
    startLatitude,
    startLongitude
  );
  const launchNormal = launchPoint.clone().sub(frame.bodyPosition).normalize();
  const arcControlPoint = launchPoint
    .clone()
    .addScaledVector(launchNormal, orbitMatchedHandleLength);
  const arcExitControlPoint = insertionPoint
    .clone()
    .addScaledVector(orbitTangent, -orbitMatchedHandleLength);
  let minimumDistance = Number.POSITIVE_INFINITY;

  for (let sample = 1; sample <= 8; sample += 1) {
    const ascent = sample / 9;
    const bezierA = launchPoint.clone().lerp(arcControlPoint, ascent);
    const bezierB = arcControlPoint.clone().lerp(arcExitControlPoint, ascent);
    const bezierC = arcExitControlPoint.clone().lerp(insertionPoint, ascent);

    bezierA.lerp(bezierB, ascent);
    bezierB.lerp(bezierC, ascent);
    const canisterPosition = bezierA.lerp(bezierB, ascent);
    const shipAngleAtSample =
      frame.shipAngle + frame.shipAngularSpeed * (startDelay + ascentDuration * ascent);
    const shipPosition = getTritiumFramePoint(
      frame,
      shipOrbitRadius,
      scoopPlaneLatitude,
      shipAngleAtSample
    );
    minimumDistance = Math.min(minimumDistance, canisterPosition.distanceTo(shipPosition));
  }

  return minimumDistance - tritiumCanisterPreOrbitShipClearance * frame.sceneUnitScale;
}

function updateTritiumCanister(
  effect: TritiumWorkEffect,
  canister: TritiumCanister,
  frame: TritiumWorkFrame,
  elapsed: number,
  camera: THREE.PerspectiveCamera,
  opacityMultiplier: number,
  renderZoomOutElements: boolean,
  beatPulse: CinematicVisualPulse | null
): void {
  if (!canister.active) {
    return;
  }

  const age = elapsed - canister.startTime;

  if (age < 0) {
    canister.group.visible = false;
    canister.closeBeacon.visible = false;
    canister.bokehBeacon.visible = false;
    canister.beaconLight.visible = false;
    canister.hasPreviousPosition = false;
    return;
  }

  if (canister.capturing && !frame.canCapture) {
    canister.capturing = false;
    canister.hasPreviousPosition = false;
  }

  if (canister.capturing) {
    const captureAge = elapsed - canister.captureStartTime;
    const captureProgress = clamp(captureAge / canister.captureDuration, 0, 1);

    if (captureProgress >= 1) {
      canister.active = false;
      canister.capturing = false;
      canister.group.visible = false;
      canister.closeBeacon.visible = false;
      canister.bokehBeacon.visible = false;
      canister.beaconLight.visible = false;
      canister.beaconLight.intensity = 0;
      canister.hasPreviousPosition = false;
      setObjectOpacity(canister.group, 0);
      return;
    }

    const dissolve = smootherStep(0, 1, captureProgress);
    canister.group.position
      .copy(canister.captureStartPosition)
      .lerp(frame.receiverWorldPosition, dissolve);
    const solarPointVisibility = frame.solarPointVisibilityForWorldPosition(
      canister.group.position
    );
    const planetScreenRadius = getScreenPixelsForWorldRadius(
      camera,
      frame.bodyPosition,
      frame.viewportHeight,
      frame.planetRadius
    );
    canister.group.quaternion.setFromUnitVectors(positiveXAxis, frame.shipTangent);
    canister.model.position.set(0, 0, 0);
    canister.model.scale.setScalar(1);
    canister.bokehBeacon.position.set(0, 0, 0);
    canister.closeBeacon.position.copy(tritiumCanisterBeaconLightLocalPosition);
    canister.beaconLight.position.copy(tritiumCanisterBeaconLightLocalPosition);
    canister.group.scale.setScalar(
      getTritiumCanisterScreenScale(
        canister.group.position,
        camera,
        frame,
        tritiumCanisterCloseScreenPixels * (1 - dissolve * 0.38)
      )
    );
    const scoopDistanceBoost =
      1 -
      smoothStep(
        tritiumCanisterRoundBeaconPlanetFadeStartPixels,
        tritiumCanisterRoundBeaconPlanetFadeEndPixels,
        planetScreenRadius
      );
    const scoopZoomVisibility =
      1 -
      smoothStep(
        tritiumCanisterScoopZoomOutFadeStart,
        tritiumCanisterScoopZoomOutFadeEnd,
        scoopDistanceBoost
      );
    const scoopModelVisibility = scoopZoomVisibility;
    canister.group.visible =
      Math.max(scoopZoomVisibility * solarPointVisibility, scoopModelVisibility) > 0.01;
    canister.model.visible = scoopModelVisibility > 0.01;
    canister.bokehBeacon.visible = false;
    const captureOpacity =
      (1 - smoothStep(0.08, 1, captureProgress)) * opacityMultiplier * scoopModelVisibility;
    setObjectOpacity(
      canister.group,
      (1 - smoothStep(0.08, 1, captureProgress)) *
        opacityMultiplier *
        scoopZoomVisibility *
        solarPointVisibility
    );
    setObjectOpacity(canister.model, captureOpacity);
    const captureBlinkPulse = getTritiumCanisterCloseBeaconPulse(canister, elapsed, beatPulse);
    const captureBeaconOpacity = captureOpacity * captureBlinkPulse;
    canister.closeBeacon.visible = captureBeaconOpacity > 0.04;
    canister.closeBeacon.material.size = tritiumCanisterCloseBeaconPixels + captureBlinkPulse * 0.8;
    setBasicOpacity(canister.closeBeacon.material, captureBeaconOpacity);
    canister.beaconLight.visible = captureBeaconOpacity > 0.04;
    canister.beaconLight.distance = tritiumCanisterBeaconLightDistance * frame.sceneUnitScale;
    canister.beaconLight.intensity =
      (tritiumCanisterBeaconLightIntensityBase +
        captureBlinkPulse * tritiumCanisterBeaconLightBlinkIntensity) *
      captureBeaconOpacity;
    return;
  }

  const ascentProgress = clamp(age / canister.ascentDuration, 0, 1);
  const orbitAge = Math.max(0, age - canister.ascentDuration);
  const shipOrbitRadius = getTritiumShipOrbitRadius(frame);
  const scoopPlaneLatitude = getTritiumCanisterScoopPlaneLatitude(frame, shipOrbitRadius);
  const orbitalLongitude = canister.orbitEntryLongitude + canister.orbitSpeed * orbitAge;
  const insertionPoint = getTritiumFramePoint(
    frame,
    shipOrbitRadius,
    scoopPlaneLatitude,
    canister.orbitEntryLongitude
  );
  const orbitDirection = Math.sign(canister.orbitSpeed) || 1;
  const orbitTangent = getTritiumOrbitTangent(
    frame.radialAxis,
    frame.tangentAxis,
    orbitalLongitude,
    orbitDirection
  );
  const canisterPosition = new THREE.Vector3();
  const canisterTangent = orbitTangent.clone();

  if (ascentProgress < 1) {
    const orbitMatchedHandleLength = clamp(
      (shipOrbitRadius * Math.abs(canister.orbitSpeed) * canister.ascentDuration) / 3,
      frame.planetRadius * 0.42,
      frame.planetRadius * 0.68
    );
    const launchPoint = getTritiumFramePoint(
      frame,
      frame.planetRadius * 1.035,
      canister.startLatitude,
      canister.startLongitude
    );
    const launchNormal = launchPoint.clone().sub(frame.bodyPosition).normalize();
    const arcControlPoint = launchPoint
      .clone()
      .addScaledVector(launchNormal, orbitMatchedHandleLength);
    const arcExitControlPoint = insertionPoint
      .clone()
      .addScaledVector(orbitTangent, -orbitMatchedHandleLength);
    const ascent = ascentProgress;
    const bezierA = launchPoint.clone().lerp(arcControlPoint, ascent);
    const bezierB = arcControlPoint.clone().lerp(arcExitControlPoint, ascent);
    const bezierC = arcExitControlPoint.clone().lerp(insertionPoint, ascent);

    bezierA.lerp(bezierB, ascent);
    bezierB.lerp(bezierC, ascent);
    canisterPosition.copy(bezierA).lerp(bezierB, ascent);
    canisterTangent.copy(bezierB).sub(bezierA).normalize();
    canisterTangent.lerp(orbitTangent, smoothStep(0.76, 1, ascentProgress)).normalize();
  } else {
    canisterPosition.copy(
      getTritiumFramePoint(frame, shipOrbitRadius, scoopPlaneLatitude, orbitalLongitude)
    );
    canisterTangent.copy(orbitTangent);
  }

  canister.group.position.copy(canisterPosition);
  canister.group.quaternion.setFromUnitVectors(positiveXAxis, canisterTangent);
  const solarPointVisibility = frame.solarPointVisibilityForWorldPosition(canisterPosition);
  const scale = getTritiumCanisterScreenScale(
    canisterPosition,
    camera,
    frame,
    THREE.MathUtils.lerp(
      tritiumCanisterLaunchScreenPixels,
      tritiumCanisterCloseScreenPixels,
      smootherStep(0, 1, ascentProgress)
    )
  );
  canister.group.scale.setScalar(scale);

  const receiverDistance = canisterPosition.distanceTo(frame.receiverWorldPosition);
  const sweptReceiverDistance = canister.hasPreviousPosition
    ? getPointToSegmentDistance(
        frame.receiverWorldPosition,
        canister.previousPosition,
        canisterPosition
      )
    : receiverDistance;
  const nearestReceiverDistance = Math.min(receiverDistance, sweptReceiverDistance);
  const captureRadius = 0.2 * frame.sceneUnitScale;

  if (frame.canCapture && ascentProgress >= 1 && nearestReceiverDistance < captureRadius) {
    canister.capturing = true;
    canister.captureStartTime = elapsed;
    canister.captureStartPosition.copy(canisterPosition);
    canister.hasPreviousPosition = false;
    emitTritiumScoopFlash(effect, elapsed, frame.receiverWorldPosition);
  } else {
    canister.previousPosition.copy(canisterPosition);
    canister.hasPreviousPosition = true;
  }

  const blinkWave =
    0.5 +
    0.5 *
      Math.sin(
        getBeatSynchronizedCycleAngle(elapsed, 18.5, beatPulse) + canister.startLongitude * 1.7
      );
  const blink = 0.18 + Math.pow(blinkWave, 4.2) * 0.82;
  const planetScreenRadius = getScreenPixelsForWorldRadius(
    camera,
    frame.bodyPosition,
    frame.viewportHeight,
    frame.planetRadius
  );
  const closeBlinkBoost = smoothStep(
    tritiumCanisterRoundBeaconPlanetFadeStartPixels,
    tritiumCanisterRoundBeaconPlanetFadeEndPixels,
    planetScreenRadius
  );
  const distanceBoost = 1 - closeBlinkBoost;
  const beaconSolarVisibility = solarPointVisibility;
  const modelDetail =
    1 -
    smoothStep(
      tritiumCanisterModelDetailLodFadeStart,
      tritiumCanisterModelDetailLodFadeEnd,
      distanceBoost
    );
  const bodyReveal = smoothStep(
    tritiumCanisterBodyRevealStart,
    tritiumCanisterBodyRevealEnd,
    distanceBoost
  );
  const bokehCollapse = smootherStep(
    tritiumCanisterBokehCollapseStart,
    tritiumCanisterBokehCollapseEnd,
    distanceBoost
  );
  const modelSilhouette = bodyReveal * tritiumCanisterBodyRevealSilhouetteOpacity;
  const modelVisibility = Math.max(modelDetail, modelSilhouette * (1 - bokehCollapse));
  canister.model.position.set(0, 0, 0);
  canister.model.scale.setScalar(1);
  canister.bokehBeacon.position.set(0, 0, 0);
  canister.closeBeacon.position.copy(tritiumCanisterBeaconLightLocalPosition);
  canister.beaconLight.position.copy(tritiumCanisterBeaconLightLocalPosition);
  syncTritiumCanisterNodeColor(canister, frame.nodeColor);
  canister.model.visible = modelVisibility > 0.025;
  setObjectOpacity(canister.model, opacityMultiplier * modelVisibility);
  const zoomOutMarkerVisibility = 1 - closeBlinkBoost;
  const zoomOutElementVisibility = renderZoomOutElements ? 1 : 0;
  const zoomOutBeaconSolarVisibility = THREE.MathUtils.lerp(
    beaconSolarVisibility,
    Math.max(beaconSolarVisibility, tritiumCanisterZoomOutUiSolarVisibilityFloor),
    bokehCollapse * zoomOutElementVisibility
  );
  const bokehBeaconVisibility =
    bokehCollapse *
    zoomOutElementVisibility *
    zoomOutMarkerVisibility *
    zoomOutBeaconSolarVisibility;
  canister.group.visible = Math.max(modelVisibility, bokehBeaconVisibility) > 0.01;
  const localScaleDivisor = Math.max(0.001, scale);
  setBasicOpacity(
    canister.glowStrip.material,
    opacityMultiplier *
      modelDetail *
      (0.72 +
        closeBlinkBoost *
          (tritiumCanisterGlowStripCloseOpacityBoost +
            blink * tritiumCanisterGlowStripCloseBlinkOpacityBoost))
  );
  const bokehOpacity =
    bokehBeaconVisibility *
    (tritiumCanisterBokehBeaconOpacity + blink * tritiumCanisterBokehBeaconBlinkOpacity) *
    opacityMultiplier;
  const bokehScaleProgress = smootherStep(0, 1, bokehCollapse);
  const bokehOrbitScale = getTritiumCanisterBokehOrbitScale(frame);
  const bokehScale =
    ((THREE.MathUtils.lerp(
      tritiumCanisterBokehBeaconMinScreenScale,
      tritiumCanisterBokehBeaconScreenScale,
      bokehScaleProgress
    ) +
      blink * tritiumCanisterBokehBeaconBlinkScreenScale * bokehScaleProgress) /
      localScaleDivisor) *
    bokehOrbitScale;
  canister.bokehBeacon.visible = bokehOpacity > 0.015;
  canister.bokehBeacon.scale.setScalar(bokehScale);
  setBasicOpacity(canister.bokehBeacon.material, bokehOpacity);
  const closeBeaconPulse = getTritiumCanisterCloseBeaconPulse(canister, elapsed, beatPulse);
  const closeBeaconOpacity =
    modelVisibility * closeBlinkBoost * closeBeaconPulse * opacityMultiplier;
  canister.closeBeacon.visible = closeBeaconOpacity > 0.04;
  canister.closeBeacon.material.size = tritiumCanisterCloseBeaconPixels + closeBeaconPulse * 0.8;
  setBasicOpacity(canister.closeBeacon.material, closeBeaconOpacity);
  const pointLightVisibility = closeBeaconOpacity;
  canister.beaconLight.visible = pointLightVisibility > 0.04;
  canister.beaconLight.distance = tritiumCanisterBeaconLightDistance * frame.sceneUnitScale;
  canister.beaconLight.intensity =
    (tritiumCanisterBeaconLightIntensityBase + blink * tritiumCanisterBeaconLightBlinkIntensity) *
    pointLightVisibility;
}

function getTritiumCanisterCloseBeaconPulse(
  canister: TritiumCanister,
  elapsed: number,
  beatPulse: CinematicVisualPulse | null
): number {
  const wave =
    0.5 +
    0.5 *
      Math.sin(
        getBeatSynchronizedCycleAngle(elapsed, tritiumCanisterCloseBeaconBlinkSpeed, beatPulse) +
          canister.startLongitude * 1.7
      );
  return smoothStep(
    tritiumCanisterCloseBeaconBlinkOnStart,
    tritiumCanisterCloseBeaconBlinkOnEnd,
    wave
  );
}

function updateTritiumScoopFlash(
  flash: TritiumScoopFlash,
  frame: TritiumWorkFrame,
  elapsed: number,
  opacityMultiplier: number
): void {
  if (!flash.active) {
    return;
  }

  const age = elapsed - flash.startTime;

  if (age < 0 || age > tritiumCanisterScoopFlashDurationSeconds) {
    flash.active = false;
    flash.group.visible = false;
    flash.light.intensity = 0;
    return;
  }

  const progress = clamp(age / tritiumCanisterScoopFlashDurationSeconds, 0, 1);
  const burst = getNuclearStyleRetinalFlashBurst(progress);
  const solarPointVisibility = frame.solarPointVisibilityForWorldPosition(flash.group.position);
  const opacity = burst * opacityMultiplier * solarPointVisibility;

  flash.group.visible = opacity > 0.01;
  flash.core.material.size = THREE.MathUtils.lerp(
    tritiumCanisterScoopFlashCoreStartPixels,
    tritiumCanisterScoopFlashCoreEndPixels,
    progress
  );
  flash.halo.material.size = THREE.MathUtils.lerp(
    tritiumCanisterScoopFlashHaloStartPixels,
    tritiumCanisterScoopFlashHaloEndPixels,
    progress
  );
  setBasicOpacity(flash.core.material, opacity * 0.82);
  setBasicOpacity(flash.halo.material, opacity * 0.24);
  flash.light.distance = tritiumCanisterScoopFlashLightDistance * frame.sceneUnitScale;
  flash.light.visible = opacity > 0.02;
  flash.light.intensity = opacity * tritiumCanisterScoopFlashLightIntensity;
}

function updateTritiumReceiverScoopGlow(
  effect: TritiumWorkEffect,
  frame: TritiumWorkFrame,
  elapsed: number,
  opacityMultiplier: number
): void {
  const age = elapsed - effect.lastScoopAt;

  if (age < 0 || age > tritiumReceiverScoopGlowDurationSeconds) {
    return;
  }

  const progress = clamp(age / tritiumReceiverScoopGlowDurationSeconds, 0, 1);
  const expansion = smootherStep(0, 1, progress);
  const fade = Math.pow(1 - progress, 1.28);
  const solarPointVisibility = frame.solarPointVisibilityForWorldPosition(
    frame.receiverWorldPosition
  );
  const opacity = fade * opacityMultiplier * solarPointVisibility;
  const sceneScale = Math.max(0.001, frame.sceneUnitScale);

  effect.receiverHalo.position.copy(frame.receiverWorldPosition);
  effect.receiverCore.position.copy(frame.receiverWorldPosition);
  effect.receiverLight.position.copy(frame.receiverWorldPosition);
  effect.receiverHalo.scale.setScalar(
    THREE.MathUtils.lerp(
      tritiumReceiverScoopGlowHaloStartScale,
      tritiumReceiverScoopGlowHaloEndScale,
      expansion
    ) * sceneScale
  );
  effect.receiverCore.scale.setScalar(
    THREE.MathUtils.lerp(
      tritiumReceiverScoopGlowCoreStartScale,
      tritiumReceiverScoopGlowCoreEndScale,
      expansion
    ) * sceneScale
  );
  setBasicOpacity(effect.receiverHalo.material, opacity * 0.64);
  setBasicOpacity(effect.receiverCore.material, opacity * 0.78);
  effect.receiverHalo.visible = opacity > 0.012;
  effect.receiverCore.visible = opacity > 0.02;
  effect.receiverLight.distance = tritiumReceiverScoopGlowLightDistance * sceneScale;
  effect.receiverLight.visible = opacity > 0.03;
  effect.receiverLight.intensity = opacity * tritiumReceiverScoopGlowLightIntensity;
}

function getTritiumFramePoint(
  frame: TritiumWorkFrame,
  radius: number,
  latitude: number,
  longitude: number
): THREE.Vector3 {
  const cosLatitude = Math.cos(latitude);
  return frame.bodyPosition
    .clone()
    .addScaledVector(frame.radialAxis, Math.cos(longitude) * cosLatitude * radius)
    .addScaledVector(mapPlaneUp, Math.sin(latitude) * radius)
    .addScaledVector(frame.tangentAxis, Math.sin(longitude) * cosLatitude * radius);
}

function getTritiumShipOrbitRadius(frame: TritiumWorkFrame): number {
  const shipOffset = frame.shipWorldPosition.clone().sub(frame.bodyPosition);
  return Math.max(
    frame.planetRadius * 1.18,
    Math.hypot(shipOffset.dot(frame.radialAxis), shipOffset.dot(frame.tangentAxis))
  );
}

function getTritiumCanisterScoopPlaneLatitude(
  frame: TritiumWorkFrame,
  orbitRadius: number
): number {
  const scoopPlaneOffset = frame.receiverWorldPosition
    .clone()
    .sub(frame.bodyPosition)
    .dot(mapPlaneUp);
  return Math.asin(clamp(scoopPlaneOffset / Math.max(orbitRadius, 0.001), -0.92, 0.92));
}

function getTritiumCanisterScreenScale(
  position: THREE.Vector3,
  camera: THREE.PerspectiveCamera,
  frame: TritiumWorkFrame,
  screenPixels: number
): number {
  return (
    getWorldUnitsForScreenPixels(camera, position, frame.viewportHeight, screenPixels) /
    tritiumCanisterModelReferenceDiameter
  );
}

function getTritiumCanisterBokehOrbitScale(frame: TritiumWorkFrame): number {
  const orbitRatio = clamp(frame.nodeOrbitRadius / tritiumCanisterBokehReferenceOrbitRadius, 0, 1);
  return Math.max(
    tritiumCanisterBokehMinimumOrbitScale,
    1 - (1 - orbitRatio) * tritiumCanisterBokehSmallOrbitReduction
  );
}

function getTritiumOrbitTangent(
  radial: THREE.Vector3,
  tangent: THREE.Vector3,
  angle: number,
  orbitDirection: number
): THREE.Vector3 {
  return radial
    .clone()
    .multiplyScalar(-Math.sin(angle) * orbitDirection)
    .addScaledVector(tangent, Math.cos(angle) * orbitDirection)
    .normalize();
}

function angleDistance(a: number, b: number): number {
  return Math.abs(positiveModulo(a - b + Math.PI, Math.PI * 2) - Math.PI);
}

function getPointToSegmentDistance(
  point: THREE.Vector3,
  segmentStart: THREE.Vector3,
  segmentEnd: THREE.Vector3
): number {
  const segment = segmentEnd.clone().sub(segmentStart);
  const segmentLengthSquared = segment.lengthSq();

  if (segmentLengthSquared <= 0.000001) {
    return point.distanceTo(segmentStart);
  }

  const progress = clamp(point.clone().sub(segmentStart).dot(segment) / segmentLengthSquared, 0, 1);
  const closestPoint = segmentStart.clone().addScaledVector(segment, progress);
  return point.distanceTo(closestPoint);
}

function signedAngleDelta(from: number, to: number): number {
  return positiveModulo(to - from + Math.PI, Math.PI * 2) - Math.PI;
}

function getTritiumCanisterLongitudinalPhase(
  canister: TritiumCanister,
  sampleTime: number
): number {
  const age = sampleTime - canister.startTime;

  if (age <= 0) {
    return canister.startLongitude;
  }

  if (age < canister.ascentDuration) {
    return (
      canister.startLongitude +
      signedAngleDelta(canister.startLongitude, canister.orbitEntryLongitude) *
        clamp(age / canister.ascentDuration, 0, 1)
    );
  }

  return (
    canister.orbitEntryLongitude + canister.orbitSpeed * Math.max(0, age - canister.ascentDuration)
  );
}

function getTritiumCanisterSpacingClearance(
  effect: TritiumWorkEffect,
  launchLongitude: number,
  orbitEntryLongitude: number,
  launchTime: number,
  insertionTime: number
): number {
  let clearance = Number.POSITIVE_INFINITY;

  for (const canister of effect.canisters) {
    if (
      !canister.active ||
      canister.capturing ||
      launchTime > canister.startTime + canister.lifetime
    ) {
      continue;
    }

    const otherLaunchPhase = getTritiumCanisterLongitudinalPhase(canister, launchTime);
    const otherInsertionPhase = getTritiumCanisterLongitudinalPhase(canister, insertionTime);

    clearance = Math.min(
      clearance,
      angleDistance(launchLongitude, otherLaunchPhase) - tritiumCanisterLaunchAngularSpacing,
      angleDistance(orbitEntryLongitude, otherInsertionPhase) - tritiumCanisterOrbitAngularSpacing
    );
  }

  return clearance;
}

function createRadialGlowSprite(
  name: string,
  color: THREE.ColorRepresentation,
  opacity: number,
  size: number
): THREE.Sprite {
  const material = new THREE.SpriteMaterial({
    map: getRadialGlowTexture(name, color),
    color,
    opacity,
    transparent: true,
    depthWrite: false,
    depthTest: true,
    blending: THREE.AdditiveBlending
  });
  material.toneMapped = false;
  const sprite = new THREE.Sprite(material);
  sprite.name = name;
  sprite.scale.setScalar(size);
  sprite.renderOrder = 39;
  return sprite;
}

function setBasicOpacity(material: THREE.Material | THREE.Material[], opacity: number): void {
  const materials = Array.isArray(material) ? material : [material];

  for (const candidate of materials) {
    if (
      candidate instanceof THREE.MeshBasicMaterial ||
      candidate instanceof THREE.MeshStandardMaterial ||
      candidate instanceof THREE.PointsMaterial ||
      candidate instanceof THREE.LineBasicMaterial ||
      candidate instanceof THREE.SpriteMaterial
    ) {
      candidate.opacity = clamp(opacity, 0, 1);
      candidate.transparent = true;
    }
  }
}

function syncBasicMeshMaterial(
  material: THREE.Material | THREE.Material[],
  color: THREE.ColorRepresentation,
  opacity: number
): void {
  const materials = Array.isArray(material) ? material : [material];

  for (const candidate of materials) {
    if (candidate instanceof THREE.MeshBasicMaterial) {
      candidate.color.set(color);
      candidate.opacity = clamp(opacity, 0, 1);
      candidate.transparent = true;
    }
  }
}

function setObjectOpacity(object: THREE.Object3D, opacity: number): void {
  object.traverse((child) => {
    setRenderableOpacity(child, opacity);
  });
}

function getShipBloomMaterialColor(material: THREE.Material): THREE.Color | null {
  if (
    material instanceof THREE.MeshBasicMaterial ||
    material instanceof THREE.MeshStandardMaterial ||
    material instanceof THREE.PointsMaterial ||
    material instanceof THREE.LineBasicMaterial ||
    material instanceof THREE.SpriteMaterial
  ) {
    return material.color;
  }

  return null;
}

function setRenderableOpacity(object: THREE.Object3D, opacity: number): void {
  if (!isDisposableRenderable(object)) {
    return;
  }

  const materials = Array.isArray(object.material) ? object.material : [object.material];

  for (const material of materials) {
    if (
      material instanceof THREE.MeshBasicMaterial ||
      material instanceof THREE.MeshStandardMaterial ||
      material instanceof THREE.PointsMaterial ||
      material instanceof THREE.LineBasicMaterial ||
      material instanceof THREE.SpriteMaterial
    ) {
      material.opacity = clamp(opacity, 0, 1);
      material.transparent = true;
    }
  }
}

function setShipModelOpacity(
  model: THREE.Object3D,
  opacity: number,
  includeComplexDetail: boolean
): void {
  model.traverse((child) => {
    if (!includeComplexDetail && child.userData["shipComplexModelDetail"] === true) {
      return;
    }

    setRenderableOpacity(child, opacity);
  });
}

function syncShipComplexModelDetailVisibility(model: THREE.Object3D, visible: boolean): void {
  if (model.userData["shipComplexModelDetailVisible"] === visible) {
    return;
  }

  model.userData["shipComplexModelDetailVisible"] = visible;

  model.traverse((child) => {
    if (child.userData["shipComplexModelDetail"] !== true) {
      return;
    }

    child.visible = visible;

    if (!visible) {
      setRenderableOpacity(child, 0);
    }
  });
}

function hideShipMarkerGroup(group: THREE.Group): void {
  for (const child of group.children) {
    child.visible = false;
  }
}

function shouldHideDisabledSceneObject(name: string): boolean {
  return (
    (!productiveNodeMarkersEnabled &&
      disabledProductiveMarkerNameFragments.some((fragment) => name.includes(fragment))) ||
    (!tritiumSurfaceGridEnabled &&
      disabledTritiumSurfaceGridNameFragments.some((fragment) => name.includes(fragment))) ||
    (!shipyardSurfaceGridEnabled &&
      disabledShipyardSurfaceGridNameFragments.some((fragment) => name.includes(fragment))) ||
    (!tritiumWorkEffectsEnabled &&
      disabledTritiumWorkEffectNameFragments.some((fragment) => name.includes(fragment)))
  );
}

function shouldRenderIndustrialSurfaceLightsForNode(node: NodeSnapshot | undefined): boolean {
  if (node?.type === "tritium") {
    return tritiumSurfaceGridEnabled;
  }

  if (node?.type === "shipyard") {
    return shipyardSurfaceGridEnabled;
  }

  return false;
}

function fadeMarkedExtremeZoomUiObjects(root: THREE.Object3D, opacityMultiplier: number): void {
  root.traverse((child) => {
    if (child.userData["extremeZoomUiFade"] !== true) {
      return;
    }

    multiplyObjectPresentationOpacity(child, opacityMultiplier);
  });
}

function fadeMarkedExtremeZoomCelestialGhosts(
  root: THREE.Object3D,
  opacityMultiplier: number
): void {
  root.traverse((child) => {
    if (child.userData["extremeZoomCelestialGhostFade"] !== true) {
      return;
    }

    multiplyObjectPresentationOpacity(child, opacityMultiplier);
  });
}

function multiplyObjectPresentationOpacity(
  object: THREE.Object3D,
  opacityMultiplier: number
): void {
  object.traverse((child) => {
    if (child.userData["preserveExtremeZoomUiOpacity"] === true) {
      return;
    }

    if (!isDisposableRenderable(child)) {
      return;
    }

    const materials = Array.isArray(child.material) ? child.material : [child.material];

    for (const material of materials) {
      multiplyMaterialPresentationOpacity(material, opacityMultiplier);
    }
  });
}

function setPreserveExtremeZoomUiOpacity(object: THREE.Object3D, preserve: boolean): void {
  object.traverse((child) => {
    child.userData["preserveExtremeZoomUiOpacity"] = preserve;
  });
}

function multiplyMaterialPresentationOpacity(
  material: THREE.Material,
  opacityMultiplier: number
): void {
  if (material instanceof THREE.ShaderMaterial) {
    for (const key of ["dashOpacity", "opacity"]) {
      const uniform = material.uniforms[key];

      if (uniform !== undefined && typeof uniform.value === "number") {
        const baseOpacityKey = `extremeZoomBase:${key}`;
        const baseOpacity: unknown = material.userData[baseOpacityKey];
        const resolvedBaseOpacity = typeof baseOpacity === "number" ? baseOpacity : uniform.value;
        material.userData[baseOpacityKey] = resolvedBaseOpacity;
        uniform.value = clamp(resolvedBaseOpacity * opacityMultiplier, 0, 1.35);
      }
    }

    return;
  }

  if (
    material instanceof THREE.MeshBasicMaterial ||
    material instanceof THREE.MeshStandardMaterial ||
    material instanceof THREE.PointsMaterial ||
    material instanceof THREE.LineBasicMaterial ||
    material instanceof THREE.SpriteMaterial
  ) {
    const baseOpacity: unknown = material.userData["extremeZoomBaseOpacity"];
    const resolvedBaseOpacity = typeof baseOpacity === "number" ? baseOpacity : material.opacity;
    material.userData["extremeZoomBaseOpacity"] = resolvedBaseOpacity;
    material.opacity = clamp(resolvedBaseOpacity * opacityMultiplier, 0, 1);
    material.transparent = true;
  }
}

function getShipDetailProgress(distance: number, tuning: Cinematic3dVisualTuning): number {
  const fullModelDistance = tuning.shipModelCollapseDistance * 0.56;
  const fullDotDistance = tuning.shipModelCollapseDistance * 1.18;
  return 1 - smoothStep(fullModelDistance, fullDotDistance, distance);
}

function getOrbitObjectReadabilityBoost(
  detailProgress: number,
  tuning: Cinematic3dVisualTuning,
  strength = 1
): number {
  const rawBoost = THREE.MathUtils.lerp(
    tuning.orbitObjectZoomOutReadabilityBoost,
    tuning.orbitObjectZoomInReadabilityBoost,
    smoothStep(0.12, 0.9, detailProgress)
  );

  return 1 + (rawBoost - 1) * clamp(strength, 0, 1);
}

function getOrbitLargeBodyReadabilityBoost(
  bodyScreenRadiusPixels: number | undefined,
  tuning: Cinematic3dVisualTuning,
  strength = 1
): number {
  if (bodyScreenRadiusPixels === undefined) {
    return 1;
  }

  const rawBoost = THREE.MathUtils.lerp(
    1,
    tuning.orbitObjectLargeBodyReadabilityBoost,
    smoothStep(
      tuning.orbitObjectLargeBodyScreenRadiusStartPx,
      tuning.orbitObjectLargeBodyScreenRadiusEndPx,
      bodyScreenRadiusPixels
    )
  );

  return 1 + (rawBoost - 1) * clamp(strength, 0, 1);
}

function getShipMarkerReadableScreenPixels(context: {
  bodyScreenRadiusPixels?: number;
  detailProgress: number;
  modelScreenPixelMultiplier: number;
  tuning: Cinematic3dVisualTuning;
  zoomOutBoost?: number;
}): number {
  const readabilityBoost =
    getOrbitObjectReadabilityBoost(context.detailProgress, context.tuning) *
    getOrbitLargeBodyReadabilityBoost(context.bodyScreenRadiusPixels, context.tuning);
  const markerScreenPixels =
    THREE.MathUtils.lerp(
      context.tuning.shipDotScreenPixels * context.tuning.shipDotScale,
      context.tuning.shipModelScreenPixels *
        context.tuning.shipModelScale *
        context.modelScreenPixelMultiplier,
      context.detailProgress
    ) *
    shipMarkerReadableScaleMultiplier *
    readabilityBoost;

  if (context.zoomOutBoost === undefined) {
    return markerScreenPixels;
  }

  return Math.max(
    markerScreenPixels,
    context.tuning.shipDotMinPx * context.zoomOutBoost * readabilityBoost
  );
}

function getConstructionCargoReadableScreenPixels(context: {
  bodyScreenRadiusPixels: number | undefined;
  detailProgress: number;
  tuning: Cinematic3dVisualTuning;
  zoomOutBoost: number;
}): number {
  const detailMix = smoothStep(0.08, 1, context.detailProgress);
  const readabilityBoost =
    getOrbitObjectReadabilityBoost(context.detailProgress, context.tuning) *
    getOrbitLargeBodyReadabilityBoost(context.bodyScreenRadiusPixels, context.tuning, 0.72);
  const cargoZoomOutBoost = THREE.MathUtils.lerp(
    context.tuning.constructionCargoZoomOutReadabilityBoost,
    1,
    smoothStep(0.18, 1, context.detailProgress)
  );
  const markerScreenPixels =
    THREE.MathUtils.lerp(
      context.tuning.constructionCargoZoomedOutScreenPixels,
      context.tuning.constructionCargoZoomedInScreenPixels,
      detailMix
    ) *
    cargoZoomOutBoost *
    readabilityBoost;

  return Math.max(
    markerScreenPixels,
    context.tuning.shipDotMinPx * context.zoomOutBoost * readabilityBoost
  );
}

function computeNodeShipOrbitAngle(
  nodeId: string,
  elapsed: number,
  tuning: Cinematic3dVisualTuning,
  markerIndex = 0,
  markerCount = 1
): number {
  const orbitAngularSpeed = tuning.shipOrbitAngularSpeed;
  // Ship orbit position must stay continuous; beat pulses can accent lights, not retime motion.
  return (
    hashBodySeed(nodeId) * Math.PI * 2 +
    elapsed * orbitAngularSpeed * nodeShipOrbitDirection -
    markerIndex * (Math.PI * 0.16) +
    (markerCount - 1) * Math.PI * 0.08
  );
}

function getArrivalOrbitHandoffKey(nodeId: string, factionId: FactionId): string {
  return `${nodeId}:${factionId}`;
}

function getStrategicContestedOrbitBasis(slot: number): Readonly<{
  diagonal: THREE.Vector3;
  forward: THREE.Vector3;
  normal: THREE.Vector3;
}> {
  const right = new THREE.Vector3(1, 0, 0);
  const up = new THREE.Vector3(
    0,
    Math.cos(contestedStrategicViewPitch),
    -Math.sin(contestedStrategicViewPitch)
  ).normalize();
  const forward = new THREE.Vector3(
    0,
    -Math.sin(contestedStrategicViewPitch),
    -Math.cos(contestedStrategicViewPitch)
  ).normalize();
  const diagonal = right
    .clone()
    .addScaledVector(up, slot === 0 ? 1 : -1)
    .normalize();
  const normal = forward.clone().cross(diagonal).normalize();
  return { diagonal, forward, normal };
}

function getContestedThrusterJetSlot(nodeId: string, beatIndex: number): number | null {
  const lane = Math.floor(
    hashStringToUnitInterval(`contested-thruster-lane:${nodeId}`) * contestedThrusterJetCycleBeats
  );
  const slot = positiveModulo(beatIndex + lane, contestedThrusterJetCycleBeats);

  return slot === 0 || slot === 3 || slot === 6 ? slot : null;
}

const contestedThrusterJetGeometryByRatio = new Map<string, THREE.CylinderGeometry>();
const sharedUnitSphereGeometries = new Map<string, THREE.SphereGeometry>();
let sharedUnitCircleGeometry: THREE.BufferGeometry | null = null;

function createContestedThrusterJetMesh(
  name: string,
  source: THREE.Vector3,
  direction: THREE.Vector3,
  length: number,
  farRadius: number,
  nearRadius: number,
  color: THREE.ColorRepresentation,
  opacity: number,
  renderOrder: number
): THREE.Mesh {
  const geometry = getContestedThrusterJetGeometry(nearRadius / Math.max(0.001, farRadius));
  const material = new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity: clamp(opacity, 0, 1),
    depthWrite: false,
    depthTest: true,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide
  });
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = name;
  mesh.position.copy(source).addScaledVector(direction, length / 2);
  mesh.quaternion.setFromUnitVectors(mapPlaneUp, direction);
  mesh.scale.set(farRadius, length, farRadius);
  mesh.renderOrder = renderOrder;
  mesh.userData["usesSharedGeometry"] = true;
  return mesh;
}

function getContestedThrusterJetGeometry(nearToFarRatio: number): THREE.CylinderGeometry {
  const ratio = clamp(nearToFarRatio, 0.04, 1);
  const key = ratio.toFixed(3);
  const existing = contestedThrusterJetGeometryByRatio.get(key);

  if (existing !== undefined) {
    return existing;
  }

  const geometry = new THREE.CylinderGeometry(1, ratio, 1, 8, 1, true);
  contestedThrusterJetGeometryByRatio.set(key, geometry);
  return geometry;
}

function getSharedUnitSphereGeometry(
  widthSegments: number,
  heightSegments: number
): THREE.SphereGeometry {
  const key = `${widthSegments}:${heightSegments}`;
  const existing = sharedUnitSphereGeometries.get(key);

  if (existing !== undefined) {
    return existing;
  }

  const geometry = new THREE.SphereGeometry(1, widthSegments, heightSegments);
  sharedUnitSphereGeometries.set(key, geometry);
  return geometry;
}

function getSharedUnitCircleGeometry(): THREE.BufferGeometry {
  if (sharedUnitCircleGeometry !== null) {
    return sharedUnitCircleGeometry;
  }

  const segmentCount = 256;
  const positions = new Float32Array(segmentCount * 3);

  for (let index = 0; index < segmentCount; index += 1) {
    const angle = (index / segmentCount) * Math.PI * 2;
    const offset = index * 3;
    positions[offset] = Math.cos(angle);
    positions[offset + 1] = 0;
    positions[offset + 2] = Math.sin(angle);
  }

  sharedUnitCircleGeometry = new THREE.BufferGeometry();
  sharedUnitCircleGeometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  sharedUnitCircleGeometry.computeBoundingSphere();
  return sharedUnitCircleGeometry;
}

function getCargoOrbitPosition(formation: NodeShipFormation, cargoAngle: number): THREE.Vector3 {
  return new THREE.Vector3(
    Math.cos(cargoAngle) * formation.orbitRadius,
    formation.origin.y,
    Math.sin(cargoAngle) * formation.orbitRadius
  );
}

function getOrbitingShipMinimumWorldSize(detailProgress: number): number {
  return THREE.MathUtils.lerp(
    orbitingShipMinimumWorldSizeZoomOut,
    orbitingShipMinimumWorldSizeZoomIn,
    smoothStep(orbitingShipMinimumWorldSizeModelDetailStart, 1, detailProgress)
  );
}

function getConstructionCargoShipLocalScale(context: {
  bodyScreenRadiusPixels: number | undefined;
  camera: THREE.PerspectiveCamera;
  detailProgress: number;
  groupScale: number;
  tuning: Cinematic3dVisualTuning;
  viewportHeight: number;
  worldPosition: THREE.Vector3;
  zoomOutBoost: number;
}): number {
  const readableMarkerScreenPixels = getConstructionCargoReadableScreenPixels({
    bodyScreenRadiusPixels: context.bodyScreenRadiusPixels,
    detailProgress: context.detailProgress,
    tuning: context.tuning,
    zoomOutBoost: context.zoomOutBoost
  });
  const markerWorldSize = getWorldUnitsForScreenPixels(
    context.camera,
    context.worldPosition,
    context.viewportHeight,
    readableMarkerScreenPixels
  );
  const minWorldSize = getOrbitingShipMinimumWorldSize(context.detailProgress);
  const markerReadableWorldSize = Math.max(markerWorldSize, minWorldSize);
  return markerReadableWorldSize / Math.max(0.001, context.groupScale);
}

function getConstructionCargoOrbitTangent(
  cargoAngle: number,
  orbitDirection: 1 | -1
): THREE.Vector3 {
  return new THREE.Vector3(-Math.sin(cargoAngle), 0, Math.cos(cargoAngle))
    .multiplyScalar(orbitDirection)
    .normalize();
}

function getConstructionCargoOrbitDirection(): 1 | -1 {
  return constructionCargoOrbitAngularSpeed >= 0 ? 1 : -1;
}

function getConstructionCargoOrbitQuaternion(
  cargoAngle: number,
  orbitDirection: 1 | -1 = getConstructionCargoOrbitDirection()
): THREE.Quaternion {
  return new THREE.Quaternion().setFromUnitVectors(
    positiveXAxis,
    getConstructionCargoOrbitTangent(cargoAngle, orbitDirection)
  );
}

function getConstructionCargoOrbitAngleAtDistanceOffset(
  baseAngle: number,
  distanceOffset: number,
  orbitRadius: number,
  orbitDirection: 1 | -1
): number {
  return baseAngle + (orbitDirection * distanceOffset) / Math.max(0.001, orbitRadius);
}

function getConstructionCargoLaunchDurationSeconds(stage: number): number {
  const kind = getConstructionCargoModuleKind(stage);

  if (kind === "ring") {
    return constructionCargoRingLaunchDurationSeconds + seededUnit(stage, 522) * 0.12;
  }

  if (kind === "engine") {
    return constructionCargoEngineLaunchDurationSeconds + seededUnit(stage, 622) * 0.16;
  }

  return constructionCargoLaunchDurationSeconds + seededUnit(stage, 622) * 0.18;
}

function getConstructionCargoSettleDurationSeconds(stage: number): number {
  return getConstructionCargoModuleKind(stage) === "engine"
    ? constructionCargoEngineSettleDurationSeconds
    : constructionCargoOrbitSettleDurationSeconds;
}

function getConstructionCargoLaunchDelaySeconds(stage: number, launchIndex: number): number {
  const kind = getConstructionCargoModuleKind(stage);
  const baseDelay =
    kind === "ring"
      ? constructionCargoRingLaunchDelaySeconds
      : kind === "engine"
        ? constructionCargoEngineLaunchDelaySeconds
        : constructionCargoModuleLaunchDelaySeconds;
  return baseDelay + seededUnit(launchIndex, 618) * constructionCargoLaunchDelayJitterSeconds;
}

function getConstructionCargoAssemblyLaunchDelaySeconds(stage: number): number {
  return (
    (getConstructionCargoLaunchDelaySeconds(stage, stage) +
      Math.max(0, stage) * constructionCargoAssemblyLaunchStaggerSeconds) *
    constructionCargoAssemblyTimingScale
  );
}

function getConstructionCargoAssemblyLaunchDurationSeconds(stage: number): number {
  return getConstructionCargoLaunchDurationSeconds(stage) * constructionCargoAssemblyTimingScale;
}

function getConstructionCargoAssemblySettleDurationSeconds(stage: number): number {
  return getConstructionCargoSettleDurationSeconds(stage) * constructionCargoAssemblyTimingScale;
}

function getConstructionCargoAssemblyModuleLaunchStartedAt(
  assemblyStartedAt: number,
  stage: number
): number {
  return assemblyStartedAt + getConstructionCargoAssemblyLaunchDelaySeconds(stage);
}

function getConstructionCargoBaseAxialOffset(kind: ConstructionCargoModuleKind): number {
  if (kind === "fuel-scoop") {
    return constructionCargoModuleOffsets.fuelScoop.base;
  }

  if (kind === "weapons") {
    return constructionCargoModuleOffsets.weapons.base;
  }

  if (kind === "radiator") {
    return constructionCargoModuleOffsets.radiator.base;
  }

  if (kind === "engine") {
    return constructionCargoModuleOffsets.engine.base;
  }

  return 0;
}

function getConstructionCargoPieceOffset(
  kind: ConstructionCargoModuleKind,
  pushProgress: number,
  detailProgress = 1,
  minimumPieceSpacing = 0,
  allowModelFusion = false
): number {
  const zoomOutSeparationProgress = getConstructionCargoUiSeparationProgress(detailProgress);
  const uiSeparationProgress = Math.max(
    zoomOutSeparationProgress,
    smoothStep(0.28, 0.78, detailProgress)
  );
  const spacingMultiplier = THREE.MathUtils.lerp(
    1,
    constructionCargoZoomOutPieceSpacingMultiplier,
    zoomOutSeparationProgress
  );
  const minimumSpacing = Math.max(
    allowModelFusion ? 0 : constructionCargoModelMinimumPieceSpacing,
    Math.max(0, minimumPieceSpacing) * uiSeparationProgress
  );
  const pushSpacing = constructionCargoAssemblyPushSpacing * spacingMultiplier;
  const engineBase = constructionCargoModuleOffsets.engine.base * spacingMultiplier;
  const radiatorBase = constructionCargoModuleOffsets.radiator.base * spacingMultiplier;
  const weaponsBase = constructionCargoModuleOffsets.weapons.base * spacingMultiplier;
  const fuelScoopBase = constructionCargoModuleOffsets.fuelScoop.base * spacingMultiplier;
  const radiatorFinal = constructionCargoModuleOffsets.radiator.final * spacingMultiplier;
  const weaponsFinal = constructionCargoModuleOffsets.weapons.final * spacingMultiplier;
  const fuelScoopFinal = constructionCargoModuleOffsets.fuelScoop.final * spacingMultiplier;
  const engineOffset = THREE.MathUtils.lerp(
    engineBase,
    constructionCargoModuleOffsets.engine.final,
    pushProgress
  );
  const radiatorOffset = Math.min(
    radiatorFinal,
    Math.max(radiatorBase, engineOffset + pushSpacing)
  );
  const weaponsOffset = Math.min(weaponsFinal, Math.max(weaponsBase, radiatorOffset + pushSpacing));
  const fuelScoopOffset = Math.min(
    fuelScoopFinal,
    Math.max(fuelScoopBase, weaponsOffset + pushSpacing)
  );

  if (kind === "engine") {
    return getConstructionCargoMinimumSeparatedOrbitOffset(kind, engineOffset, minimumSpacing);
  }

  if (kind === "radiator") {
    return getConstructionCargoMinimumSeparatedOrbitOffset(kind, radiatorOffset, minimumSpacing);
  }

  if (kind === "weapons") {
    return getConstructionCargoMinimumSeparatedOrbitOffset(kind, weaponsOffset, minimumSpacing);
  }

  if (kind === "fuel-scoop") {
    return getConstructionCargoMinimumSeparatedOrbitOffset(kind, fuelScoopOffset, minimumSpacing);
  }

  return 0;
}

function getConstructionCargoUiSeparationProgress(detailProgress: number): number {
  return (
    1 -
    smoothStep(
      constructionCargoUiSeparationDetailStart,
      constructionCargoUiSeparationDetailEnd,
      detailProgress
    )
  );
}

function getConstructionCargoMinimumSeparatedOrbitOffset(
  kind: ConstructionCargoModuleKind,
  offset: number,
  minimumPieceSpacing: number
): number {
  const laneIndex = getConstructionCargoOrbitSeparationLaneIndex(kind);

  if (laneIndex <= 0 || minimumPieceSpacing <= 0) {
    return offset;
  }

  const minimumOffset = -minimumPieceSpacing * laneIndex;

  return Math.abs(offset) >= Math.abs(minimumOffset) ? offset : minimumOffset;
}

function getConstructionCargoOrbitSeparationLaneIndex(kind: ConstructionCargoModuleKind): number {
  if (kind === "fuel-scoop") {
    return 1;
  }

  if (kind === "weapons") {
    return 2;
  }

  if (kind === "radiator") {
    return 3;
  }

  if (kind === "engine") {
    return 4;
  }

  return 0;
}

function getConstructionCargoAssemblyPushProgress(age: number): number {
  return smootherStep(
    0,
    1,
    (age - getConstructionCargoAssemblyPushStartSeconds()) /
      (constructionCargoAssemblyPushDurationSeconds * constructionCargoAssemblyTimingScale)
  );
}

function getConstructionCargoAssemblyPushStartSeconds(): number {
  const engineStage = 4;
  return (
    getConstructionCargoAssemblyLaunchDelaySeconds(engineStage) +
    getConstructionCargoAssemblyLaunchDurationSeconds(engineStage) *
      constructionCargoAssemblyEnginePushAscentProgress +
    getConstructionCargoAssemblySettleDurationSeconds(engineStage) *
      constructionCargoAssemblyEnginePushSettleProgress
  );
}

function getConstructionCargoLaunchLongitude(context: {
  cargoIndex: number;
  kind: ConstructionCargoModuleKind;
  launchDelay: number;
  orbitRadius: number;
  sceneUnitScale: number;
  shipAngle: number;
}): number {
  const orbitDirection = getConstructionCargoOrbitDirection();
  const launchShipAngle =
    context.shipAngle + constructionCargoOrbitAngularSpeed * context.launchDelay;

  if (context.kind === "ring") {
    const tailAngleOffset =
      ((constructionCargoFollowDistance + constructionCargoConvoyFollowExtraDistance) *
        context.sceneUnitScale) /
      Math.max(0.001, context.orbitRadius);
    const launchOffset =
      orbitDirection *
      (tailAngleOffset +
        constructionCargoLaunchTailLeadAngle +
        seededUnit(context.cargoIndex, 520) * 0.035);
    const surfaceDrift = (seededUnit(context.cargoIndex, 521) - 0.5) * 0.035;
    return launchShipAngle - launchOffset + surfaceDrift;
  }

  const launchFollowDistance =
    (constructionCargoFollowDistance +
      constructionCargoConvoyFollowExtraDistance -
      getConstructionCargoBaseAxialOffset(context.kind)) *
    context.sceneUnitScale;
  const launchOffset =
    orbitDirection *
    (launchFollowDistance / Math.max(0.001, context.orbitRadius) +
      0.09 +
      seededUnit(context.cargoIndex, 620) * 0.035);
  const surfaceDrift = (seededUnit(context.cargoIndex, 621) - 0.5) * 0.03;
  return launchShipAngle - launchOffset + surfaceDrift;
}

function getOrAssignConstructionCargoLaunchLongitude(
  cargo: THREE.Object3D,
  context: {
    cargoIndex: number;
    kind: ConstructionCargoModuleKind;
    launchDelay: number;
    orbitRadius: number;
    sceneUnitScale: number;
    shipAngle: number;
  }
): number {
  const existing = Number(cargo.userData["constructionLaunchLongitude"]);

  if (Number.isFinite(existing)) {
    return existing;
  }

  const launchLongitude = getConstructionCargoLaunchLongitude(context);
  cargo.userData["constructionLaunchLongitude"] = launchLongitude;
  return launchLongitude;
}

function getConstructionCargoOrbitPose(context: {
  bodyCenter: THREE.Vector3;
  bodyRadius: number;
  cargoIndex: number;
  detailProgress: number;
  formation: NodeShipFormation;
  allowModelFusion: boolean;
  minimumPieceSpacing: number;
  pushProgress: number;
  sceneUnitScale: number;
  settleProgress: number;
  uiSeparationProgress: number;
}): Readonly<{
  angle: number;
  followAngle: number;
  position: THREE.Vector3;
  quaternion: THREE.Quaternion;
  tangent: THREE.Vector3;
}> {
  const kind = getConstructionCargoModuleKind(context.cargoIndex);
  const orbitDirection = getConstructionCargoOrbitDirection();
  const settle = smootherStep(0, 1, context.settleProgress);
  const zoomDistance =
    clamp(context.uiSeparationProgress, 0, 1) *
    constructionCargoFollowZoomDistance *
    context.sceneUnitScale;
  const convoyFollowDistance = constructionCargoConvoyFollowExtraDistance * context.sceneUnitScale;
  const followDistance =
    (constructionCargoFollowDistance + constructionCargoOrbitSettleLagDistance * (1 - settle)) *
      context.sceneUnitScale +
    convoyFollowDistance +
    zoomDistance;
  const followAngle =
    context.formation.angle -
    orbitDirection * (followDistance / Math.max(0.001, context.formation.orbitRadius));
  const pieceAngle = getConstructionCargoOrbitAngleAtDistanceOffset(
    followAngle,
    getConstructionCargoPieceOffset(
      kind,
      context.pushProgress,
      context.detailProgress,
      context.minimumPieceSpacing,
      context.allowModelFusion
    ) * context.sceneUnitScale,
    context.formation.orbitRadius,
    orbitDirection
  );
  const tangent = getConstructionCargoOrbitTangent(pieceAngle, orbitDirection);
  const position = getCargoOrbitPosition(context.formation, pieceAngle);
  position.y = context.formation.origin.y;

  return {
    angle: pieceAngle,
    followAngle,
    position,
    quaternion: getConstructionCargoOrbitQuaternion(pieceAngle, orbitDirection),
    tangent
  };
}

function getConstructionCargoUiMarkerOrbitPosition(context: {
  cargoAngle: number;
  cargoCount: number;
  cargoIndex: number;
  followAngle: number;
  formation: NodeShipFormation;
  separationProgress: number;
}): THREE.Vector3 {
  const count = Math.max(1, Math.floor(context.cargoCount));

  if (count <= 1) {
    return getCargoOrbitPosition(context.formation, context.followAngle);
  }

  const angleStep = constructionCargoUiMarkerArcSpanRadians / Math.max(1, count - 1);
  const orbitDirection = getConstructionCargoOrbitDirection();
  const separatedMarkerAngle =
    context.followAngle - orbitDirection * angleStep * clamp(context.cargoIndex, 0, count - 1);
  const markerAngle =
    context.cargoAngle +
    signedAngleDelta(context.cargoAngle, separatedMarkerAngle) *
      smootherStep(0, 1, clamp(context.separationProgress, 0, 1));

  return getCargoOrbitPosition(context.formation, markerAngle);
}

function getConstructionCargoLaunchSurfacePoint(context: {
  bodyCenter: THREE.Vector3;
  bodyRadius: number;
  launchLongitude: number;
}): THREE.Vector3 {
  const surfaceRadius = context.bodyRadius * constructionCargoLaunchSurfaceScale;

  return new THREE.Vector3(
    context.bodyCenter.x + Math.cos(context.launchLongitude) * surfaceRadius,
    context.bodyCenter.y,
    context.bodyCenter.z + Math.sin(context.launchLongitude) * surfaceRadius
  );
}

function getConstructionCargoLaunchPose(context: {
  bodyCenter: THREE.Vector3;
  bodyRadius: number;
  cargoIndex: number;
  kind: ConstructionCargoModuleKind;
  launchLongitude: number;
  nodeOrbitRadius: number;
  targetPosition: THREE.Vector3;
  targetTangent: THREE.Vector3;
  progress: number;
}): Readonly<{ position: THREE.Vector3; quaternion: THREE.Quaternion }> {
  void context.cargoIndex;
  void context.kind;
  void context.nodeOrbitRadius;
  const progress = smootherStep(0, 1, context.progress);
  const surfaceAngle = context.launchLongitude;
  const start = getConstructionCargoLaunchSurfacePoint(context);
  const launchNormal = start.clone().sub(context.bodyCenter).normalize();
  const launchBendTangent = getConstructionCargoOrbitTangent(
    surfaceAngle,
    getConstructionCargoOrbitDirection() === 1 ? -1 : 1
  );
  const targetTangent = context.targetTangent.clone();
  const firstControl = start
    .clone()
    .addScaledVector(launchNormal, context.bodyRadius * 0.62)
    .addScaledVector(launchBendTangent, context.bodyRadius * 0.16);
  const secondControl = context.targetPosition
    .clone()
    .addScaledVector(launchNormal, context.bodyRadius * 0.18)
    .addScaledVector(targetTangent, -context.bodyRadius * 0.26);
  const position = sampleCubicBezier3(
    start,
    firstControl,
    secondControl,
    context.targetPosition,
    progress
  );
  const tangent = sampleCubicBezierTangent3(
    start,
    firstControl,
    secondControl,
    context.targetPosition,
    progress
  );
  tangent.y = 0;

  if (tangent.lengthSq() <= 0.0001) {
    tangent.copy(targetTangent);
  } else {
    tangent.normalize();
  }

  tangent.lerp(targetTangent, smoothStep(0.76, 1, context.progress)).normalize();
  const launchQuaternion = new THREE.Quaternion().setFromUnitVectors(
    positiveXAxis,
    launchNormal.multiplyScalar(-1)
  );
  const targetQuaternion = new THREE.Quaternion().setFromUnitVectors(positiveXAxis, targetTangent);

  return {
    position,
    quaternion: launchQuaternion.slerp(
      targetQuaternion,
      smootherStep(0.16, 1, clamp(context.progress, 0, 1))
    )
  };
}

function getConstructionCargoAssemblyPose(context: {
  age: number;
  cargoCount: number;
  cargoIndex: number;
  finalFormation: NodeShipFormation;
  finalQuaternion: THREE.Quaternion;
  finalShipPosition: THREE.Vector3;
  handoffLeadDistanceLocal: number;
  handoffSpacingLocal: number;
  allowModelFusion: boolean;
  minimumPieceSpacing: number;
  sceneUnitScale: number;
  sourcePosition: THREE.Vector3;
  sourceQuaternion: THREE.Quaternion;
}): Readonly<{
  morphProgress: number;
  opacityMultiplier: number;
  position: THREE.Vector3;
  quaternion: THREE.Quaternion;
  scaleMultiplier: number;
}> {
  const cargoCount = Math.max(1, Math.floor(context.cargoCount));
  const rawFinalMorphProgress =
    (context.age - getConstructionCargoAssemblyFinalMorphStart(cargoCount)) /
    constructionCargoAssemblyFinalMorphSeconds;
  const morphProgress = smootherStep(0, 1, rawFinalMorphProgress);
  const morphPulse = Math.sin(morphProgress * Math.PI);
  const kind = getConstructionCargoModuleKind(context.cargoIndex);
  const orbitDirection = getConstructionCargoOrbitDirection();
  const finalPieceAngle = getConstructionCargoOrbitAngleAtDistanceOffset(
    context.finalFormation.angle,
    getConstructionCargoPieceOffset(
      kind,
      1,
      1,
      context.minimumPieceSpacing,
      context.allowModelFusion
    ) * context.sceneUnitScale,
    context.finalFormation.orbitRadius,
    orbitDirection
  );
  const finalOrbitPosition = getCargoOrbitPosition(context.finalFormation, finalPieceAngle);
  const finalHandoffPosition = getConstructionCargoAssemblyHandoffPosition({
    cargoIndex: context.cargoIndex,
    finalFormation: context.finalFormation,
    finalShipPosition: context.finalShipPosition,
    handoffLeadDistanceLocal: context.handoffLeadDistanceLocal,
    handoffSpacingLocal: context.handoffSpacingLocal
  });
  const finalPosition = finalOrbitPosition.lerp(
    finalHandoffPosition,
    context.cargoIndex === 0 ? morphProgress : smootherStep(0.92, 1, morphProgress)
  );

  return {
    morphProgress,
    opacityMultiplier: 1 - smootherStep(0.88, 1, morphProgress),
    position: context.sourcePosition.clone().lerp(finalPosition, morphProgress),
    quaternion: context.sourceQuaternion.clone().slerp(context.finalQuaternion, morphProgress),
    scaleMultiplier: 1 + morphPulse * 0.055
  };
}

function getConstructionCargoAssemblyHandoffPosition(context: {
  cargoIndex: number;
  finalFormation: NodeShipFormation;
  finalShipPosition: THREE.Vector3;
  handoffLeadDistanceLocal: number;
  handoffSpacingLocal: number;
}): THREE.Vector3 {
  return context.finalShipPosition
    .clone()
    .addScaledVector(
      context.finalFormation.behind,
      Math.max(0, context.handoffLeadDistanceLocal) +
        Math.max(0, context.handoffSpacingLocal) * Math.max(0, context.cargoIndex)
    );
}

function getConstructionCargoAssemblyFinalMorphStart(cargoCount: number): number {
  void cargoCount;
  return (
    getConstructionCargoAssemblyPushStartSeconds() +
    constructionCargoAssemblyPushDurationSeconds * constructionCargoAssemblyTimingScale +
    constructionCargoAssemblyActivationHoldSeconds * constructionCargoAssemblyTimingScale
  );
}

function getConstructionCargoAssemblyFinalMorphProgress(age: number, cargoCount: number): number {
  return smootherStep(
    0,
    1,
    (age - getConstructionCargoAssemblyFinalMorphStart(cargoCount)) /
      (constructionCargoAssemblyFinalMorphSeconds * constructionCargoAssemblyTimingScale)
  );
}

function getConstructionCargoAssemblyReadyAge(cargoCount: number): number {
  return (
    getConstructionCargoAssemblyFinalMorphStart(cargoCount) +
    constructionCargoAssemblyFinalMorphSeconds * constructionCargoAssemblyTimingScale
  );
}

function hasShipyardProductionEvent(snapshot: SolarSystemSnapshot): boolean {
  return snapshot.debugEvents.some((event) => event.type === "SHIP_PRODUCED");
}

function getBurnTransitIdFromTargetKey(targetKey: string | null): string | null {
  const prefix = "burn:";

  if (targetKey === null || !targetKey.startsWith(prefix)) {
    return null;
  }

  return targetKey.slice(prefix.length);
}

function isBurnTargetKey(targetKey: string | null): boolean {
  return getBurnTransitIdFromTargetKey(targetKey) !== null;
}

function isCloseInspectableTargetKey(targetKey: string | null): boolean {
  return isBurnTargetKey(targetKey) || getMissileIdFromTargetKey(targetKey) !== null;
}

function isSelectionTransparentTargetKey(targetKey: string | null): boolean {
  return targetKey === "body:sun";
}

function getMissileTargetKey(missile: Pick<ActiveMissile, "id">): string {
  return `missile:${missile.id}`;
}

function getMissileIdFromTargetKey(targetKey: string | null): string | null {
  const prefix = "missile:";

  if (targetKey === null || !targetKey.startsWith(prefix)) {
    return null;
  }

  return targetKey.slice(prefix.length);
}

function isRenderableBurnPlanAffordable(plan: RenderableBurnPlan): boolean {
  return !("isAffordable" in plan) || plan.isAffordable !== false;
}

function isResolvedBurnTrajectoryRenderable(
  trajectory: ResolvedBurnTrajectory | null
): trajectory is ResolvedBurnTrajectory {
  return (
    trajectory !== null &&
    trajectory.presentationPoints.length >= 2 &&
    measurePolylineLength(trajectory.presentationPoints) > 0.001
  );
}

function toCssColor(color: THREE.ColorRepresentation): string {
  return `#${new THREE.Color(color).getHexString()}`;
}

function toCssRgba(color: THREE.Color, alpha: number): string {
  const red = Math.round(color.r * 255);
  const green = Math.round(color.g * 255);
  const blue = Math.round(color.b * 255);
  return `rgba(${red}, ${green}, ${blue}, ${clamp(alpha, 0, 1)})`;
}

function brightenColor(color: THREE.ColorRepresentation, amount: number): THREE.Color {
  return new THREE.Color(color).lerp(new THREE.Color(0xffffff), clamp(amount, 0, 1));
}

function getTutorialAttentionNodeColorPulse(pulse: CinematicTutorialAttentionPulse | null): number {
  if (pulse === null || pulse.intensity <= 0.001) {
    return 0;
  }

  const beat = 0.5 + Math.sin(clamp(pulse.phase, 0, 1) * Math.PI * 2) * 0.5;
  const intensity = smootherStep(0.04, 0.86, pulse.intensity);
  return (
    intensity *
    THREE.MathUtils.lerp(
      tutorialAttentionNodeColorPulseMinMix,
      tutorialAttentionNodeColorPulseMaxMix,
      smoothStep(0.08, 1, beat)
    )
  );
}

function getTutorialAttentionNodeOnOffOpacityMultiplier(
  pulse: CinematicTutorialAttentionPulse | null
): number {
  if (pulse === null || pulse.nodeBlinkMode !== "on-off" || pulse.intensity <= 0.001) {
    return 1;
  }

  return clamp(pulse.phase, 0, 1) < 0.5 ? 1 : 0;
}

function getTutorialAttentionNodeColor(
  baseColor: THREE.ColorRepresentation,
  pulseColor: THREE.ColorRepresentation,
  pulseMix: number
): THREE.Color {
  return new THREE.Color(baseColor).lerp(new THREE.Color(pulseColor), clamp(pulseMix, 0, 1));
}

function dimColor(color: THREE.ColorRepresentation, amount: number): THREE.Color {
  return new THREE.Color(color).multiplyScalar(clamp(amount, 0, 1));
}

function createBurnTrajectoryMesh(
  points: readonly THREE.Vector3[],
  color: THREE.ColorRepresentation,
  opacity: number,
  elapsed: number,
  thicknessMultiplier = 1,
  isInvalid = false,
  anchorStartDash = false,
  coreRadiusLimit?: number,
  detailMode: BurnTrajectoryDetailMode = "full",
  cameraPosition?: THREE.Vector3,
  beatPulse: CinematicVisualPulse | null = null,
  animationSpeedMultiplier = 1,
  reusableGroup?: THREE.Group,
  visibleStartProgress = 0,
  anchorEndDash = false,
  planeReflection: TrajectoryPlaneReflectionOptions = {
    accentSpeed: 0,
    enabled: false,
    elapsed,
    showAnimatedAccent: false
  }
): THREE.Group {
  // Camera-facing ribbon extrusion is handled in the vertex shader.
  void cameraPosition;
  const group = reusableGroup ?? new THREE.Group();
  const hasUnchangedPoints = group.userData["burnTrajectoryPoints"] === points;
  const cachedDistance = getNumericUserData(group, "burnTrajectoryDistance");
  const distance =
    hasUnchangedPoints && Number.isFinite(cachedDistance)
      ? cachedDistance
      : measurePolylineLength(points);
  const dashCycle = isInvalid ? clamp(distance * 0.048, 11, 30) : clamp(distance * 0.055, 12, 34);
  const dashLength = dashCycle * (isInvalid ? 0.32 : 0.58);
  const dashAnimationState = rebaseBurnTrajectoryDashAnimationState(
    getBurnTrajectoryDashAnimationState(group),
    dashCycle,
    getBurnTrajectoryDashPhase(
      elapsed,
      dashCycle,
      animationSpeedMultiplier,
      beatPulse,
      anchorStartDash
    ),
    elapsed
  );
  const dashPhase = anchorStartDash ? 0 : dashAnimationState.phase;
  group.name = isInvalid ? "burn-trajectory-invalid" : "burn-trajectory";
  group.visible = points.length >= 2;
  group.userData["burnTrajectoryDashCycle"] = dashCycle;
  group.userData["burnTrajectoryAnimationSpeedMultiplier"] = animationSpeedMultiplier;
  group.userData["burnTrajectoryAnchorStartDash"] = anchorStartDash;
  group.userData["burnTrajectoryDashAnimationState"] = dashAnimationState;
  group.userData["burnTrajectoryPoints"] = points;
  group.userData["burnTrajectoryDistance"] = distance;
  group.userData["trajectoryAccentSpeed"] = planeReflection.showAnimatedAccent
    ? Math.max(0, planeReflection.accentSpeed)
    : 0;

  if (points.length < 2) {
    return group;
  }

  const reusableDashGroup = group.children.find(
    (child): child is THREE.Group =>
      child instanceof THREE.Group && child.name === "burn-trajectory"
  );
  const dashGroup = createBurnTrajectoryDash(
    points,
    color,
    opacity,
    thicknessMultiplier,
    distance,
    dashCycle,
    dashLength,
    dashPhase,
    coreRadiusLimit,
    detailMode,
    reusableDashGroup,
    visibleStartProgress,
    anchorEndDash,
    hasUnchangedPoints,
    planeReflection
  );
  setObjectShaderUniformNumber(
    dashGroup,
    "trajectoryAccentPhase",
    planeReflection.showAnimatedAccent && planeReflection.accentSpeed > 0
      ? (planeReflection.elapsed * planeReflection.accentSpeed) % 1
      : 0
  );

  for (const child of [...group.children]) {
    if (child === dashGroup) {
      continue;
    }

    group.remove(child);
    disposeObject(child);
  }

  group.add(dashGroup);
  // BURN/FIRE ribbons are direct UI plus UI bloom sources. Leaving them on Three's default world
  // layer tied their glow to the adaptive world-bloom pass, so a performance transition could
  // make only these bright previews appear to lose or regain bloom.
  setExclusiveObjectRenderLayer(group, cinematicUiBloomRenderLayer);
  return group;
}

function getBurnTrajectoryDashPhase(
  elapsed: number,
  dashCycle: number,
  animationSpeedMultiplier: number,
  beatPulse: CinematicVisualPulse | null,
  anchorStartDash: boolean
): number {
  if (anchorStartDash) {
    return 0;
  }

  const dashCycleTiming = getBeatSynchronizedCycle(
    elapsed,
    dashCycle / Math.max(0.001, burnTrajectoryDashFlowSpeed * animationSpeedMultiplier),
    beatPulse
  );
  return dashCycleTiming.synchronized
    ? dashCycleTiming.phase * dashCycle
    : (elapsed * animationSpeedMultiplier * burnTrajectoryDashFlowSpeed) % dashCycle;
}

function getBurnTrajectoryDashAnimationState(
  trajectory: THREE.Group
): BurnTrajectoryDashAnimationState | null {
  const state: unknown = trajectory.userData["burnTrajectoryDashAnimationState"];

  if (typeof state !== "object" || state === null) {
    return null;
  }

  const candidate = state as Partial<BurnTrajectoryDashAnimationState>;
  return typeof candidate.phase === "number" &&
    Number.isFinite(candidate.phase) &&
    typeof candidate.cycle === "number" &&
    Number.isFinite(candidate.cycle) &&
    candidate.cycle > 0 &&
    typeof candidate.elapsed === "number" &&
    Number.isFinite(candidate.elapsed)
    ? {
        phase: candidate.phase,
        cycle: candidate.cycle,
        elapsed: candidate.elapsed
      }
    : null;
}

function getBurnTrajectoryCoreRadius(
  distance: number,
  thicknessMultiplier: number,
  coreRadiusLimit?: number
): number {
  const rawCoreRadius = clamp(distance * 0.0018, 0.34, 1.2) * thicknessMultiplier;
  return coreRadiusLimit === undefined ? rawCoreRadius : Math.min(rawCoreRadius, coreRadiusLimit);
}

function getBurnTrajectoryCoreHalfWidth(
  distance: number,
  thicknessMultiplier: number,
  detailMode: BurnTrajectoryDetailMode,
  coreRadiusLimit?: number
): number {
  const coreRadius = getBurnTrajectoryCoreRadius(distance, thicknessMultiplier, coreRadiusLimit);
  return detailMode === "simple" ? coreRadius * 1.12 : coreRadius;
}

function createBurnTrajectoryDash(
  points: readonly THREE.Vector3[],
  color: THREE.ColorRepresentation,
  opacity: number,
  thicknessMultiplier: number,
  distance: number,
  dashCycle: number,
  dashLength: number,
  dashPhase: number,
  coreRadiusLimit?: number,
  detailMode: BurnTrajectoryDetailMode = "full",
  reusableGroup?: THREE.Group,
  visibleStartProgress = 0,
  anchorEndDash = false,
  hasUnchangedPoints = false,
  planeReflection: TrajectoryPlaneReflectionOptions = {
    accentSpeed: 0,
    enabled: false,
    elapsed: 0,
    showAnimatedAccent: false
  }
): THREE.Group {
  const coreRadius = getBurnTrajectoryCoreRadius(distance, thicknessMultiplier, coreRadiusLimit);
  const group = reusableGroup ?? new THREE.Group();
  const terminalAnchorProgress = anchorEndDash
    ? clamp((dashLength * 0.42) / Math.max(0.001, distance), 0.0015, 0.025)
    : 0;
  group.name = "burn-trajectory";
  const trajectoryLayerNames = new Set([
    "burn-trajectory-glow",
    "burn-trajectory-edge-spine",
    "burn-trajectory-core",
    "burn-trajectory-plane-reflection"
  ]);

  for (const child of [...group.children]) {
    if (child instanceof THREE.Mesh && trajectoryLayerNames.has(child.name)) {
      continue;
    }

    group.remove(child);
    disposeObject(child);
  }

  const reusableCore = getBurnTrajectoryDashLayer(group, "burn-trajectory-core");
  const coreHalfWidth = getBurnTrajectoryCoreHalfWidth(
    distance,
    thicknessMultiplier,
    detailMode,
    coreRadiusLimit
  );
  const coreEdgeSoftness = detailMode === "simple" ? 0.22 : 0.18;
  const core = createBurnTrajectoryDashLayer(
    points,
    coreHalfWidth,
    color,
    opacity,
    distance,
    dashCycle,
    dashLength,
    dashPhase,
    coreEdgeSoftness,
    0,
    reusableCore,
    visibleStartProgress,
    terminalAnchorProgress,
    undefined,
    hasUnchangedPoints
  );
  core.name = "burn-trajectory-core";
  core.renderOrder = 38;
  core.visible = true;
  setShaderUniformNumber(
    core.material,
    "trajectoryAccentStrength",
    planeReflection.showAnimatedAccent ? 1.2 : 0
  );
  const reflection = syncBurnTrajectoryPlaneReflection(
    group,
    core,
    color,
    opacity,
    distance,
    dashCycle,
    dashLength,
    dashPhase,
    visibleStartProgress,
    terminalAnchorProgress,
    coreRadius,
    planeReflection
  );

  if (detailMode === "simple") {
    const reusableGlow = getBurnTrajectoryDashLayer(group, "burn-trajectory-glow");
    const reusableEdgeSpine = getBurnTrajectoryDashLayer(group, "burn-trajectory-edge-spine");
    if (reusableGlow !== undefined) {
      reusableGlow.visible = false;
    }
    if (reusableEdgeSpine !== undefined) {
      reusableEdgeSpine.visible = false;
    }
    group.add(core);
    if (reflection !== undefined) {
      group.add(reflection);
    }
    return group;
  }

  const reusableGlow = getBurnTrajectoryDashLayer(group, "burn-trajectory-glow");
  const glowHalfWidth = coreRadius * 2.45;
  const glow = createBurnTrajectoryDashLayer(
    points,
    glowHalfWidth,
    color,
    opacity * 0.24,
    distance,
    dashCycle,
    dashLength,
    dashPhase,
    0.72,
    0,
    reusableGlow,
    visibleStartProgress,
    terminalAnchorProgress,
    core.geometry
  );
  glow.name = "burn-trajectory-glow";
  glow.renderOrder = 37.8;
  glow.visible = true;
  setShaderUniformNumber(
    glow.material,
    "trajectoryAccentStrength",
    planeReflection.showAnimatedAccent ? 0.36 : 0
  );

  const reusableEdgeSpine = getBurnTrajectoryDashLayer(group, "burn-trajectory-edge-spine");
  const edgeHalfWidth = coreRadius * 1.25;
  const edgeSpine = createBurnTrajectoryDashLayer(
    points,
    edgeHalfWidth,
    color,
    opacity * 0.36,
    distance,
    dashCycle,
    dashLength,
    dashPhase,
    0.48,
    0.78,
    reusableEdgeSpine,
    visibleStartProgress,
    terminalAnchorProgress,
    core.geometry
  );
  edgeSpine.name = "burn-trajectory-edge-spine";
  edgeSpine.renderOrder = 37.9;
  edgeSpine.visible = true;
  setShaderUniformNumber(
    edgeSpine.material,
    "trajectoryAccentStrength",
    planeReflection.showAnimatedAccent ? 0.58 : 0
  );
  group.add(glow, edgeSpine, core);
  if (reflection !== undefined) {
    group.add(reflection);
  }
  return group;
}

function syncBurnTrajectoryPlaneReflection(
  group: THREE.Group,
  core: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>,
  color: THREE.ColorRepresentation,
  opacity: number,
  distance: number,
  dashCycle: number,
  dashLength: number,
  dashPhase: number,
  visibleStartProgress: number,
  terminalAnchorProgress: number,
  coreRadius: number,
  options: TrajectoryPlaneReflectionOptions
): THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial> | undefined {
  const reusableReflection = getBurnTrajectoryDashLayer(group, "burn-trajectory-plane-reflection");

  if (!options.enabled) {
    if (reusableReflection !== undefined) {
      reusableReflection.visible = false;
    }
    return undefined;
  }

  const customReflectionPoints =
    options.points !== undefined && options.points.length >= 2 ? options.points : undefined;
  const readability = clamp(options.readability ?? 0, 0, 1);
  const reflectionOpacity =
    opacity *
    trajectoryPlaneReflectionOpacityMultiplier *
    THREE.MathUtils.lerp(1, firePreviewReflectionOpacityBoost, readability);
  const reflectionHalfWidth =
    coreRadius *
    trajectoryPlaneReflectionWidthMultiplier *
    THREE.MathUtils.lerp(1, firePreviewReflectionWidthBoost, readability);
  const reflectionAccentStrength = options.showAnimatedAccent
    ? THREE.MathUtils.lerp(1, firePreviewReflectionAccentBoost, readability)
    : 0;
  const reflectionScreenOffsetScale =
    customReflectionPoints === undefined ? 1 : readability * firePreviewReflectionScreenOffsetScale;
  const reflectionSunPosition = options.sunPosition ?? mapPlaneOrigin;
  const reflectionTurnCount = clamp(
    Math.round(options.turnCount ?? 0),
    0,
    trajectoryPlaneReflectionMaximumTurnMarkers
  );
  const reflectionDistance =
    customReflectionPoints === undefined ? distance : measurePolylineLength(customReflectionPoints);
  const reflection =
    reusableReflection ??
    new THREE.Mesh(
      customReflectionPoints === undefined
        ? core.geometry
        : createBurnTrajectoryRibbonGeometry(customReflectionPoints, reflectionDistance),
      createBurnTrajectoryPlaneReflectionMaterial(
        color,
        reflectionOpacity,
        reflectionDistance,
        dashCycle,
        dashLength,
        dashPhase,
        visibleStartProgress,
        terminalAnchorProgress,
        reflectionHalfWidth,
        options.showAnimatedAccent && options.accentSpeed > 0
          ? (options.elapsed * options.accentSpeed) % 1
          : 0,
        reflectionAccentStrength,
        reflectionScreenOffsetScale,
        reflectionSunPosition,
        reflectionTurnCount,
        readability
      )
    );
  const wasUsingSharedGeometry = reflection.userData["usesSharedGeometry"] === true;

  if (customReflectionPoints === undefined) {
    if (!wasUsingSharedGeometry && reflection.geometry !== core.geometry) {
      reflection.geometry.dispose();
    }
    reflection.geometry = core.geometry;
    reflection.userData["usesSharedGeometry"] = true;
  } else {
    if (wasUsingSharedGeometry) {
      reflection.geometry = createBurnTrajectoryRibbonGeometry(
        customReflectionPoints,
        reflectionDistance
      );
    }
    syncBurnTrajectoryRibbonGeometry(reflection, customReflectionPoints, reflectionDistance);
    reflection.userData["usesSharedGeometry"] = false;
  }
  reflection.frustumCulled = false;
  reflection.name = "burn-trajectory-plane-reflection";
  reflection.renderOrder = 37.65;
  reflection.visible = true;
  const reflectionDepth = clamp(
    Math.max(
      distance * trajectoryPlaneReflectionDistanceDepthRatio,
      coreRadius * trajectoryPlaneReflectionCoreDepthMultiplier
    ),
    trajectoryPlaneReflectionMinimumDepth,
    trajectoryPlaneReflectionMaximumDepth
  );

  if (customReflectionPoints === undefined) {
    reflection.position.set(0, -reflectionDepth, 0);
    reflection.scale.set(1, -trajectoryPlaneReflectionVerticalScale, 1);
  } else {
    reflection.position.set(0, 0, 0);
    reflection.scale.set(1, 1, 1);
  }
  syncBurnTrajectoryPlaneReflectionMaterial(
    reflection.material,
    color,
    reflectionOpacity,
    reflectionDistance,
    dashCycle,
    dashLength,
    dashPhase,
    visibleStartProgress,
    terminalAnchorProgress,
    reflectionHalfWidth,
    options.showAnimatedAccent && options.accentSpeed > 0
      ? (options.elapsed * options.accentSpeed) % 1
      : 0,
    reflectionAccentStrength,
    reflectionScreenOffsetScale,
    reflectionSunPosition,
    reflectionTurnCount,
    readability
  );
  return reflection;
}

function createBurnTrajectoryDashLayer(
  points: readonly THREE.Vector3[],
  radius: number,
  color: THREE.ColorRepresentation,
  opacity: number,
  distance: number,
  dashCycle: number,
  dashLength: number,
  dashPhase: number,
  edgeSoftnessMultiplier: number,
  verticalBias = 0,
  reusableMesh?: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>,
  visibleStartProgress = 0,
  terminalAnchorProgress = 0,
  sharedGeometry?: THREE.BufferGeometry,
  hasUnchangedPoints = false
): THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial> {
  if (reusableMesh === undefined) {
    const mesh = new THREE.Mesh(
      sharedGeometry ?? createBurnTrajectoryRibbonGeometry(points, distance),
      createBurnTrajectoryDashMaterial(
        color,
        opacity,
        distance,
        dashCycle,
        dashLength,
        dashPhase,
        edgeSoftnessMultiplier,
        visibleStartProgress,
        terminalAnchorProgress,
        radius,
        verticalBias
      )
    );
    if (sharedGeometry === undefined) {
      storeBurnTrajectoryRibbonGeometryState(mesh, points);
    }
    mesh.frustumCulled = false;
    return mesh;
  }

  if (sharedGeometry === undefined) {
    if (!hasUnchangedPoints) {
      syncBurnTrajectoryRibbonGeometry(reusableMesh, points, distance);
    }
  } else {
    reusableMesh.geometry = sharedGeometry;
  }
  syncBurnTrajectoryDashMaterial(
    reusableMesh.material,
    color,
    opacity,
    distance,
    dashCycle,
    dashLength,
    dashPhase,
    edgeSoftnessMultiplier,
    visibleStartProgress,
    terminalAnchorProgress,
    radius,
    verticalBias
  );
  return reusableMesh;
}

function getBurnTrajectoryDashLayer(
  group: THREE.Group,
  name: string
): THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial> | undefined {
  const layer = group.children.find((child) => child instanceof THREE.Mesh && child.name === name);
  return layer instanceof THREE.Mesh && layer.material instanceof THREE.ShaderMaterial
    ? (layer as THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>)
    : undefined;
}

function syncBurnTrajectoryRibbonGeometry(
  mesh: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>,
  points: readonly THREE.Vector3[],
  distance: number
): void {
  if (isBurnTrajectoryRibbonGeometryCurrent(mesh, points)) {
    return;
  }

  const currentGeometry = mesh.geometry;
  const currentPosition = currentGeometry.getAttribute("position");
  const currentUv = currentGeometry.getAttribute("uv");
  const currentTangent = currentGeometry.getAttribute("ribbonTangent");
  const currentSideSign = currentGeometry.getAttribute("ribbonSideSign");
  const currentIndex = currentGeometry.getIndex();
  const canReuseBuffers =
    currentPosition instanceof THREE.BufferAttribute &&
    currentUv instanceof THREE.BufferAttribute &&
    currentTangent instanceof THREE.BufferAttribute &&
    currentSideSign instanceof THREE.BufferAttribute &&
    currentPosition.count === points.length * 2 &&
    currentUv.count === points.length * 2 &&
    currentTangent.count === points.length * 2 &&
    currentSideSign.count === points.length * 2 &&
    currentIndex !== null &&
    currentIndex.count === Math.max(0, points.length - 1) * 6;

  if (!canReuseBuffers) {
    currentGeometry.dispose();
    mesh.geometry = createBurnTrajectoryRibbonGeometry(points, distance);
    storeBurnTrajectoryRibbonGeometryState(mesh, points);
    return;
  }

  writeBurnTrajectoryRibbonGeometryBuffers(currentGeometry, points, distance);
  currentPosition.needsUpdate = true;
  currentUv.needsUpdate = true;
  currentTangent.needsUpdate = true;
  currentSideSign.needsUpdate = true;
  currentIndex.needsUpdate = true;
  storeBurnTrajectoryRibbonGeometryState(mesh, points);
}

function writeBurnTrajectoryRibbonGeometryBuffers(
  geometry: THREE.BufferGeometry,
  points: readonly THREE.Vector3[],
  distance: number
): void {
  const positionAttribute = geometry.getAttribute("position");
  const uvAttribute = geometry.getAttribute("uv");
  const tangentAttribute = geometry.getAttribute("ribbonTangent");
  const sideSignAttribute = geometry.getAttribute("ribbonSideSign");
  const indexAttribute = geometry.getIndex();

  if (
    !(positionAttribute instanceof THREE.BufferAttribute) ||
    !(uvAttribute instanceof THREE.BufferAttribute) ||
    !(tangentAttribute instanceof THREE.BufferAttribute) ||
    !(sideSignAttribute instanceof THREE.BufferAttribute) ||
    indexAttribute === null
  ) {
    return;
  }

  const tangent = new THREE.Vector3();
  let cumulativeDistance = 0;

  for (let index = 0; index < points.length; index += 1) {
    const point = points[index];

    if (point === undefined) {
      continue;
    }

    const previous = points[Math.max(0, index - 1)] ?? point;
    const next = points[Math.min(points.length - 1, index + 1)] ?? point;
    tangent.copy(next).sub(previous);

    if (tangent.lengthSq() <= 0.0001) {
      tangent.set(1, 0, 0);
    } else {
      tangent.normalize();
    }

    if (index > 0) {
      const priorPoint = points[index - 1];

      if (priorPoint !== undefined) {
        cumulativeDistance += priorPoint.distanceTo(point);
      }
    }

    const distanceUv = cumulativeDistance / Math.max(0.001, distance);
    positionAttribute.setXYZ(index * 2, point.x, point.y, point.z);
    positionAttribute.setXYZ(index * 2 + 1, point.x, point.y, point.z);
    tangentAttribute.setXYZ(index * 2, tangent.x, tangent.y, tangent.z);
    tangentAttribute.setXYZ(index * 2 + 1, tangent.x, tangent.y, tangent.z);
    sideSignAttribute.setX(index * 2, -1);
    sideSignAttribute.setX(index * 2 + 1, 1);
    uvAttribute.setXY(index * 2, distanceUv, 0);
    uvAttribute.setXY(index * 2 + 1, distanceUv, 1);

    if (index > 0) {
      const base = index * 2;
      const indexOffset = (index - 1) * 6;
      indexAttribute.setX(indexOffset, base - 2);
      indexAttribute.setX(indexOffset + 1, base - 1);
      indexAttribute.setX(indexOffset + 2, base);
      indexAttribute.setX(indexOffset + 3, base);
      indexAttribute.setX(indexOffset + 4, base - 1);
      indexAttribute.setX(indexOffset + 5, base + 1);
    }
  }

  geometry.computeBoundingSphere();
}

type BurnTrajectoryRibbonGeometryState = {
  pointCoordinates: Float64Array;
};

function isBurnTrajectoryRibbonGeometryCurrent(
  mesh: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>,
  points: readonly THREE.Vector3[]
): boolean {
  const state = mesh.userData["burnTrajectoryRibbonGeometryState"] as
    | BurnTrajectoryRibbonGeometryState
    | undefined;

  if (state === undefined || state.pointCoordinates.length !== points.length * 3) {
    return false;
  }

  for (let index = 0; index < points.length; index += 1) {
    const point = points[index];
    const coordinateIndex = index * 3;

    if (
      point === undefined ||
      state.pointCoordinates[coordinateIndex] !== point.x ||
      state.pointCoordinates[coordinateIndex + 1] !== point.y ||
      state.pointCoordinates[coordinateIndex + 2] !== point.z
    ) {
      return false;
    }
  }

  return true;
}

function storeBurnTrajectoryRibbonGeometryState(
  mesh: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>,
  points: readonly THREE.Vector3[]
): void {
  const previousState = mesh.userData["burnTrajectoryRibbonGeometryState"] as
    | BurnTrajectoryRibbonGeometryState
    | undefined;
  const pointCoordinates =
    previousState?.pointCoordinates.length === points.length * 3
      ? previousState.pointCoordinates
      : new Float64Array(points.length * 3);

  for (let index = 0; index < points.length; index += 1) {
    const point = points[index];

    if (point === undefined) {
      continue;
    }

    const coordinateIndex = index * 3;
    pointCoordinates[coordinateIndex] = point.x;
    pointCoordinates[coordinateIndex + 1] = point.y;
    pointCoordinates[coordinateIndex + 2] = point.z;
  }

  mesh.userData["burnTrajectoryRibbonGeometryState"] = {
    pointCoordinates
  } satisfies BurnTrajectoryRibbonGeometryState;
}

function syncBurnTrajectoryDashMaterial(
  material: THREE.ShaderMaterial,
  color: THREE.ColorRepresentation,
  opacity: number,
  distance: number,
  dashCycle: number,
  dashLength: number,
  dashPhase: number,
  edgeSoftnessMultiplier: number,
  visibleStartProgress: number,
  terminalAnchorProgress: number,
  halfWidth: number,
  verticalBias: number
): void {
  const dashColor: unknown = material.uniforms["dashColor"]?.value;

  if (dashColor instanceof THREE.Color) {
    dashColor.set(color);
  }

  setShaderUniformNumber(material, "dashOpacity", opacity);
  material.userData["extremeZoomBase:dashOpacity"] = opacity;
  setShaderUniformNumber(material, "dashDistance", Math.max(0.001, distance));
  setShaderUniformNumber(material, "dashCycle", Math.max(0.001, dashCycle));
  setShaderUniformNumber(material, "dashLength", Math.max(0.001, dashLength));
  setShaderUniformNumber(material, "dashPhase", dashPhase);
  setShaderUniformNumber(material, "dashEdgeSoftness", Math.max(0.45, edgeSoftnessMultiplier));
  setShaderUniformNumber(material, "dashVisibleStart", clamp(visibleStartProgress, 0, 1));
  setShaderUniformNumber(
    material,
    "dashTerminalAnchorProgress",
    clamp(terminalAnchorProgress, 0, 0.1)
  );
  setShaderUniformNumber(material, "ribbonHalfWidth", Math.max(0.001, halfWidth));
  setShaderUniformNumber(material, "ribbonVerticalBias", clamp(verticalBias, 0, 1));
}

function createBurnTrajectoryRibbonGeometry(
  points: readonly THREE.Vector3[],
  distance: number
): THREE.BufferGeometry {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    "position",
    new THREE.BufferAttribute(new Float32Array(points.length * 2 * 3), 3)
  );
  geometry.setAttribute(
    "uv",
    new THREE.BufferAttribute(new Float32Array(points.length * 2 * 2), 2)
  );
  geometry.setAttribute(
    "ribbonTangent",
    new THREE.BufferAttribute(new Float32Array(points.length * 2 * 3), 3)
  );
  geometry.setAttribute(
    "ribbonSideSign",
    new THREE.BufferAttribute(new Float32Array(points.length * 2), 1)
  );
  geometry.setIndex(
    new THREE.BufferAttribute(new Uint16Array(Math.max(0, points.length - 1) * 6), 1)
  );
  writeBurnTrajectoryRibbonGeometryBuffers(geometry, points, distance);
  return geometry;
}

function createBurnTrajectoryDashMaterial(
  color: THREE.ColorRepresentation,
  opacity: number,
  distance: number,
  dashCycle: number,
  dashLength: number,
  dashPhase: number,
  edgeSoftnessMultiplier: number,
  visibleStartProgress: number,
  terminalAnchorProgress: number,
  halfWidth: number,
  verticalBias: number
): THREE.ShaderMaterial {
  return new THREE.ShaderMaterial({
    uniforms: {
      dashColor: { value: new THREE.Color(color) },
      dashOpacity: { value: opacity },
      dashDistance: { value: Math.max(0.001, distance) },
      dashCycle: { value: Math.max(0.001, dashCycle) },
      dashLength: { value: Math.max(0.001, dashLength) },
      dashPhase: { value: dashPhase },
      dashEdgeSoftness: { value: Math.max(0.45, edgeSoftnessMultiplier) },
      dashVisibleStart: { value: clamp(visibleStartProgress, 0, 1) },
      dashTerminalAnchorProgress: { value: clamp(terminalAnchorProgress, 0, 0.1) },
      ribbonHalfWidth: { value: Math.max(0.001, halfWidth) },
      ribbonVerticalBias: { value: clamp(verticalBias, 0, 1) },
      trajectoryAccentPhase: { value: 0 },
      trajectoryAccentStrength: { value: 0 }
    },
    transparent: true,
    // A trajectory can be viewed almost edge-on when the camera is lowered to the orbital
    // plane. Its camera-facing frame may then cross the view direction between presentation
    // updates; rendering both faces keeps FIRE/BURN previews visible through that transition.
    side: THREE.DoubleSide,
    depthTest: false,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    vertexShader: `
      attribute vec3 ribbonTangent;
      attribute float ribbonSideSign;
      uniform float ribbonHalfWidth;
      uniform float ribbonVerticalBias;
      varying vec2 vDashUv;

      void main() {
        vec4 worldCenter = modelMatrix * vec4(position, 1.0);
        vec3 worldTangent = normalize(mat3(modelMatrix) * ribbonTangent);
        vec3 toCamera = cameraPosition - worldCenter.xyz;
        float toCameraLengthSq = dot(toCamera, toCamera);
        vec3 viewDirection = toCameraLengthSq > 0.000001
          ? toCamera * inversesqrt(toCameraLengthSq)
          : vec3(0.0, 1.0, 0.0);
        vec3 cameraFacingSide = cross(worldTangent, viewDirection);
        vec3 planarTangent = vec3(worldTangent.x, 0.0, worldTangent.z);

        if (dot(planarTangent, planarTangent) <= 0.000001) {
          planarTangent = vec3(1.0, 0.0, 0.0);
        } else {
          planarTangent = normalize(planarTangent);
        }

        vec3 planarSide = normalize(vec3(-planarTangent.z, 0.0, planarTangent.x));
        vec3 fallbackSide = normalize(
          mix(planarSide, vec3(0.0, 1.0, 0.0), ribbonVerticalBias)
        );
        vec3 ribbonSide = dot(cameraFacingSide, cameraFacingSide) > 0.000001
          ? normalize(cameraFacingSide)
          : fallbackSide;
        vec3 worldPosition =
          worldCenter.xyz + ribbonSide * ribbonSideSign * ribbonHalfWidth;
        vDashUv = uv;
        gl_Position = projectionMatrix * viewMatrix * vec4(worldPosition, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 dashColor;
      uniform float dashOpacity;
      uniform float dashDistance;
      uniform float dashCycle;
      uniform float dashLength;
      uniform float dashPhase;
      uniform float dashEdgeSoftness;
      uniform float dashVisibleStart;
      uniform float dashTerminalAnchorProgress;
      uniform float trajectoryAccentPhase;
      uniform float trajectoryAccentStrength;
      varying vec2 vDashUv;

      void main() {
        float alongDistance = vDashUv.x * dashDistance;
        float dashPosition = mod(alongDistance - dashPhase + dashCycle, dashCycle);
        float edgeWidth = min(dashLength * 0.5, dashCycle * 0.16) * dashEdgeSoftness;
        float lead = smoothstep(0.0, edgeWidth, dashPosition);
        float trail = 1.0 - smoothstep(dashLength - edgeWidth, dashLength, dashPosition);
        float lateral = abs(vDashUv.y - 0.5) * 2.0;
        float lateralMask = 1.0 - smoothstep(0.66, 1.04, lateral);
        float visibleMask = dashVisibleStart <= 0.0001
          ? 1.0
          : smoothstep(dashVisibleStart, dashVisibleStart + 0.003, vDashUv.x);
        float terminalAnchor = dashTerminalAnchorProgress <= 0.000001
          ? 0.0
          : smoothstep(
              1.0 - dashTerminalAnchorProgress,
              1.0 - dashTerminalAnchorProgress * 0.28,
              vDashUv.x
            );
        float dashMask = clamp(
          max(min(lead, trail), terminalAnchor) * lateralMask * visibleMask,
          0.0,
          1.0
        );
        float wrappedAccentDistance = abs(
          fract(vDashUv.x - trajectoryAccentPhase + 0.5) - 0.5
        );
        float accent = exp(
          -pow(wrappedAccentDistance / ${trajectoryPlaneReflectionGlintWidth.toFixed(3)}, 2.0)
        );
        float accentCross = pow(max(0.0, 1.0 - lateral), 5.0);
        float accentMask =
          accent * accentCross * visibleMask * trajectoryAccentStrength;
        float combinedMask = clamp(dashMask + accentMask * 1.15, 0.0, 1.35);

        if (combinedMask <= 0.01) {
          discard;
        }

        vec3 accentColor = mix(
          dashColor,
          vec3(1.0),
          clamp(accentMask * 1.45, 0.0, 1.0)
        );
        gl_FragColor = vec4(accentColor, dashOpacity * combinedMask);
      }
    `
  });
}

function syncBurnTrajectoryPlaneReflectionMaterial(
  material: THREE.ShaderMaterial,
  color: THREE.ColorRepresentation,
  opacity: number,
  distance: number,
  dashCycle: number,
  dashLength: number,
  dashPhase: number,
  visibleStartProgress: number,
  terminalAnchorProgress: number,
  halfWidth: number,
  accentPhase: number,
  accentStrength: number,
  screenOffsetScale: number,
  sunPosition: THREE.Vector3,
  turnCount: number,
  readability: number
): void {
  const reflectionColor: unknown = material.uniforms["reflectionColor"]?.value;

  if (reflectionColor instanceof THREE.Color) {
    reflectionColor.set(color).lerp(new THREE.Color(0xd9fbff), 0.48);
  }

  const reflectionSunPosition: unknown = material.uniforms["sunPosition"]?.value;

  if (reflectionSunPosition instanceof THREE.Vector3) {
    reflectionSunPosition.copy(sunPosition);
  }

  setShaderUniformNumber(material, "reflectionOpacity", opacity);
  material.userData["extremeZoomBase:reflectionOpacity"] = opacity;
  setShaderUniformNumber(material, "dashDistance", Math.max(0.001, distance));
  setShaderUniformNumber(material, "dashCycle", Math.max(0.001, dashCycle));
  setShaderUniformNumber(material, "dashLength", Math.max(0.001, dashLength));
  setShaderUniformNumber(material, "dashPhase", dashPhase);
  setShaderUniformNumber(material, "dashVisibleStart", clamp(visibleStartProgress, 0, 1));
  setShaderUniformNumber(
    material,
    "dashTerminalAnchorProgress",
    clamp(terminalAnchorProgress, 0, 0.1)
  );
  setShaderUniformNumber(material, "ribbonHalfWidth", Math.max(0.001, halfWidth));
  setShaderUniformNumber(material, "trajectoryAccentPhase", accentPhase);
  setShaderUniformNumber(material, "trajectoryAccentStrength", accentStrength);
  setShaderUniformNumber(material, "reflectionScreenOffsetScale", screenOffsetScale);
  setShaderUniformNumber(material, "reflectionTurnCount", turnCount);
  setShaderUniformNumber(material, "reflectionReadability", readability);
}

function createBurnTrajectoryPlaneReflectionMaterial(
  color: THREE.ColorRepresentation,
  opacity: number,
  distance: number,
  dashCycle: number,
  dashLength: number,
  dashPhase: number,
  visibleStartProgress: number,
  terminalAnchorProgress: number,
  halfWidth: number,
  accentPhase: number,
  accentStrength: number,
  screenOffsetScale: number,
  sunPosition: THREE.Vector3,
  turnCount: number,
  readability: number
): THREE.ShaderMaterial {
  const material = new THREE.ShaderMaterial({
    uniforms: {
      reflectionColor: {
        value: new THREE.Color(color).lerp(new THREE.Color(0xd9fbff), 0.48)
      },
      reflectionOpacity: { value: opacity },
      trajectoryAccentPhase: { value: accentPhase },
      trajectoryAccentStrength: { value: accentStrength },
      dashDistance: { value: Math.max(0.001, distance) },
      dashCycle: { value: Math.max(0.001, dashCycle) },
      dashLength: { value: Math.max(0.001, dashLength) },
      dashPhase: { value: dashPhase },
      dashVisibleStart: { value: clamp(visibleStartProgress, 0, 1) },
      dashTerminalAnchorProgress: { value: clamp(terminalAnchorProgress, 0, 0.1) },
      ribbonHalfWidth: { value: Math.max(0.001, halfWidth) },
      reflectionScreenOffsetScale: { value: screenOffsetScale },
      reflectionTurnCount: { value: turnCount },
      reflectionReadability: { value: readability },
      sunPosition: { value: sunPosition.clone() }
    },
    transparent: true,
    side: THREE.DoubleSide,
    depthTest: false,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    vertexShader: `
      attribute vec3 ribbonTangent;
      attribute float ribbonSideSign;
      uniform float ribbonHalfWidth;
      uniform float reflectionScreenOffsetScale;
      uniform vec3 sunPosition;
      varying vec2 vReflectionUv;
      varying float vReflectionGrazing;
      varying float vReflectionSolarAlignment;

      void main() {
        vec4 worldCenter = modelMatrix * vec4(position, 1.0);
        vec3 worldTangent = normalize(mat3(modelMatrix) * ribbonTangent);
        vec3 toCamera = cameraPosition - worldCenter.xyz;
        float toCameraLengthSq = dot(toCamera, toCamera);
        vec3 viewDirection = toCameraLengthSq > 0.000001
          ? toCamera * inversesqrt(toCameraLengthSq)
          : vec3(0.0, 1.0, 0.0);
        vec3 cameraFacingSide = cross(worldTangent, viewDirection);
        vec3 planarTangent = vec3(worldTangent.x, 0.0, worldTangent.z);

        if (dot(planarTangent, planarTangent) <= 0.000001) {
          planarTangent = vec3(1.0, 0.0, 0.0);
        } else {
          planarTangent = normalize(planarTangent);
        }

        vec3 planarSide = normalize(vec3(-planarTangent.z, 0.0, planarTangent.x));
        vec3 ribbonSide = dot(cameraFacingSide, cameraFacingSide) > 0.000001
          ? normalize(cameraFacingSide)
          : planarSide;
        vec3 worldPosition =
          worldCenter.xyz + ribbonSide * ribbonSideSign * ribbonHalfWidth;
        vec3 planeNormal = vec3(0.0, 1.0, 0.0);
        vec3 toSun = sunPosition - worldCenter.xyz;
        float toSunLengthSq = dot(toSun, toSun);
        vec3 lightDirection = toSunLengthSq > 0.000001
          ? toSun * inversesqrt(toSunLengthSq)
          : vec3(1.0, 0.0, 0.0);
        vec3 reflectedLight = reflect(-lightDirection, planeNormal);
        vReflectionUv = uv;
        vReflectionGrazing = 1.0 - abs(dot(viewDirection, planeNormal));
        vReflectionSolarAlignment = max(dot(reflectedLight, viewDirection), 0.0);
        vec4 clipPosition = projectionMatrix * viewMatrix * vec4(worldPosition, 1.0);
        // A small refractive split keeps the reflection legible even when the camera is nearly
        // normal to the orbital plane, where a geometrically exact mirror would fully overlap.
        clipPosition.xy += vec2(
          ${trajectoryPlaneReflectionScreenOffsetX.toFixed(4)},
          ${trajectoryPlaneReflectionScreenOffsetY.toFixed(4)}
        ) * clipPosition.w * reflectionScreenOffsetScale;
        gl_Position = clipPosition;
      }
    `,
    fragmentShader: `
      uniform vec3 reflectionColor;
      uniform float reflectionOpacity;
      uniform float reflectionTurnCount;
      uniform float trajectoryAccentPhase;
      uniform float trajectoryAccentStrength;
      uniform float reflectionReadability;
      uniform float dashDistance;
      uniform float dashCycle;
      uniform float dashLength;
      uniform float dashPhase;
      uniform float dashVisibleStart;
      uniform float dashTerminalAnchorProgress;
      varying vec2 vReflectionUv;
      varying float vReflectionGrazing;
      varying float vReflectionSolarAlignment;

      void main() {
        float alongDistance = vReflectionUv.x * dashDistance;
        float dashPosition = mod(alongDistance - dashPhase + dashCycle, dashCycle);
        float edgeWidth = min(dashLength * 0.5, dashCycle * 0.24);
        float lead = smoothstep(0.0, edgeWidth, dashPosition);
        float trail = 1.0 - smoothstep(dashLength - edgeWidth, dashLength, dashPosition);
        float lateral = abs(vReflectionUv.y - 0.5) * 2.0;
        float softRibbon = 1.0 - smoothstep(0.08, 1.0, lateral);
        float centerCore = 1.0 - smoothstep(0.02, 0.34, lateral);
        float visibleMask = dashVisibleStart <= 0.0001
          ? 1.0
          : smoothstep(dashVisibleStart, dashVisibleStart + 0.004, vReflectionUv.x);
        float terminalAnchor = dashTerminalAnchorProgress <= 0.000001
          ? 0.0
          : smoothstep(
              1.0 - dashTerminalAnchorProgress,
              1.0 - dashTerminalAnchorProgress * 0.28,
              vReflectionUv.x
        );
        float reflectedDash = max(min(lead, trail), terminalAnchor) * softRibbon * visibleMask;
        float turnPatternEnabled = step(0.5, reflectionTurnCount);
        float turnCellPhase = fract(
          vReflectionUv.x * max(1.0, reflectionTurnCount)
        );
        float distanceToTurnMarker = abs(turnCellPhase - 0.5);
        float turnMarkerCore =
          (
            1.0 -
            smoothstep(
              ${trajectoryPlaneReflectionTurnMarkerCoreInnerRadius.toFixed(3)},
              ${trajectoryPlaneReflectionTurnMarkerCoreOuterRadius.toFixed(3)},
              distanceToTurnMarker
            )
          )
          * centerCore
          * visibleMask
          * turnPatternEnabled;
        float turnMarkerHalo =
          (
            1.0 -
            smoothstep(
              ${trajectoryPlaneReflectionTurnMarkerHaloInnerRadius.toFixed(3)},
              ${trajectoryPlaneReflectionTurnMarkerHaloOuterRadius.toFixed(3)},
              distanceToTurnMarker
            )
          )
          * softRibbon
          * visibleMask
          * turnPatternEnabled;
        float glintCenter = trajectoryAccentPhase;
        float wrappedGlintDistance = abs(
          fract(vReflectionUv.x - glintCenter + 0.5) - 0.5
        );
        float glint = exp(
          -pow(wrappedGlintDistance / ${trajectoryPlaneReflectionGlintWidth.toFixed(3)}, 2.0)
        );
        float glintCross = pow(max(0.0, 1.0 - lateral), 5.0);
        float glintRay = exp(
          -pow(
            wrappedGlintDistance /
              ${Math.max(0.001, trajectoryPlaneReflectionGlintWidth * 0.22).toFixed(3)},
            2.0
          )
        ) * (1.0 - smoothstep(0.1, 1.0, lateral));
        // Like the planet rings, the reflection always keeps a low ambient presence. Camera
        // grazing changes it continuously while the actual highlight comes from the solar
        // reflection direction, avoiding a single camera pitch where the whole path pops on.
        float viewGrazingProfile = pow(
          clamp(vReflectionGrazing, 0.0, 1.0),
          ${trajectoryPlaneReflectionViewGrazingExponent.toFixed(2)}
        );
        float solarGlintLobe = pow(
          clamp(vReflectionSolarAlignment, 0.0, 1.0),
          ${trajectoryPlaneReflectionSolarGlintExponent.toFixed(1)}
        );
        float angularVisibility =
          mix(
          ${trajectoryPlaneReflectionMinimumAngularVisibility.toFixed(2)},
          ${trajectoryPlaneReflectionMaximumAngularVisibility.toFixed(2)},
          viewGrazingProfile
        )
        + solarGlintLobe * ${trajectoryPlaneReflectionSolarGlintVisibilityBoost.toFixed(2)};
        float glintAngularVisibility =
          mix(
            ${trajectoryPlaneReflectionMinimumAccentVisibility.toFixed(2)},
            ${trajectoryPlaneReflectionSolarGlintAccentBoost.toFixed(2)},
            solarGlintLobe
          )
          * mix(0.55, 1.0, viewGrazingProfile);
        float glintMask =
          (glint * glintCross + glintRay * 0.9)
          * visibleMask
          * glintAngularVisibility
          * trajectoryAccentStrength;
        // FIRE previews keep a faint continuous silhouette below the reflected dashes. The
        // narrow core preserves their direction at distant zooms without turning other
        // trajectory reflections into solid paths.
        float continuousSilhouette =
          (softRibbon * 0.26 + centerCore * 0.74)
          * visibleMask
          * reflectionReadability;
        float reflectionMask =
          max(reflectedDash, continuousSilhouette * 0.2)
          * angularVisibility;
        float turnPatternMask =
          (
            turnMarkerCore * ${trajectoryPlaneReflectionTurnMarkerCoreGain.toFixed(2)}
            + turnMarkerHalo *
              reflectedDash *
              ${trajectoryPlaneReflectionTurnMarkerNeighborGain.toFixed(2)}
          )
          * angularVisibility;
        reflectionMask +=
          reflectedDash
          * centerCore
          * reflectionReadability
          * angularVisibility
          * 0.24;
        reflectionMask += turnPatternMask;
        float alpha = reflectionOpacity * (reflectionMask + glintMask * 1.85);

        if (alpha <= 0.004) {
          discard;
        }

        float turnColorHighlight = clamp(
          turnMarkerCore + turnMarkerHalo * reflectedDash * 0.4,
          0.0,
          1.0
        );
        vec3 glintColor = mix(
          reflectionColor,
          vec3(1.0),
          clamp(
            glintMask * 1.4 +
              turnColorHighlight * ${trajectoryPlaneReflectionTurnMarkerColorGain.toFixed(2)},
            0.0,
            1.0
          )
        );
        gl_FragColor = vec4(glintColor, alpha);
      }
    `
  });
  material.name = "burn-trajectory-plane-reflection-material";
  return material;
}

function getMissileLaunchIgnitionFlash(launchProgress: number): number {
  const attack = smoothStep(
    missileLaunchIgnitionStartProgress,
    missileLaunchIgnitionPeakProgress,
    launchProgress
  );
  const decay =
    1 -
    smoothStep(missileLaunchIgnitionPeakProgress, missileLaunchIgnitionEndProgress, launchProgress);
  return attack * decay;
}

function createMissileEvadeProjectileSaturation(
  getMuzzlePosition: (projectileIndex: number) => THREE.Vector3 | null,
  detonationPosition: THREE.Vector3,
  age: number,
  seed: number
): THREE.Points<THREE.BufferGeometry, THREE.ShaderMaterial> | null {
  if (age > missileEvadeProjectilePresentationDurationSeconds) {
    return null;
  }

  const positions: number[] = [];
  const colors: number[] = [];
  const opacities: number[] = [];
  const seedOffset = Math.floor(seed * 100_003);
  const tracerColor = new THREE.Color(0xffffff);

  for (
    let projectileIndex = 0;
    projectileIndex < missileEvadeProjectileCount;
    projectileIndex += 1
  ) {
    const seededIndex = projectileIndex + seedOffset;
    const rawProgress = projectileIndex / Math.max(1, missileEvadeProjectileCount - 1);
    const progress = getMissileEvadeTracerEmissionProgress(rawProgress);
    const terminalDensity = smootherStep(0.58, 1, progress);
    const isTargetShot = projectileIndex === missileEvadeProjectileCount - 1;
    const shotAge =
      age -
      (progress * missileEvadeTracerBurstDurationSeconds + seededUnit(seededIndex, 705) * 0.002);
    const flightDuration = isTargetShot
      ? missileEvadeProjectileTravelDurationSeconds
      : missileEvadeProjectileFlightDurationSeconds;

    if (shotAge < 0 || shotAge > flightDuration) {
      continue;
    }

    const muzzlePosition = getMuzzlePosition(projectileIndex);

    if (muzzlePosition === null) {
      continue;
    }

    const tracerInterceptionPosition = getMissileEvadeTracerInterceptionPosition(
      detonationPosition,
      muzzlePosition,
      progress
    );
    const axis = tracerInterceptionPosition.sub(muzzlePosition);
    const range = axis.length();

    if (range <= 0.001) {
      continue;
    }

    axis.normalize();
    const coneBasisA = new THREE.Vector3().crossVectors(axis, mapPlaneUp);

    if (coneBasisA.lengthSq() < 0.0001) {
      coneBasisA.set(0, 0, 1).cross(axis);
    }

    coneBasisA.normalize();
    const coneBasisB = new THREE.Vector3().crossVectors(axis, coneBasisA).normalize();
    const spinAngle =
      getMissileEvadeTracerSpinAngle(progress, 11.8) + (seededUnit(seededIndex, 712) - 0.5) * 0.24;
    const naturalConeRadius =
      getMissileEvadeTracerConeRadius(progress, range) *
      (0.88 + seededUnit(seededIndex, 703) * 0.24);
    const coneRadius = isTargetShot
      ? 0
      : Math.max(naturalConeRadius, range * missileEvadeTracerMinimumMissRadiusRatio);
    const radialDirection = coneBasisA
      .clone()
      .multiplyScalar(Math.cos(spinAngle))
      .addScaledVector(coneBasisB, Math.sin(spinAngle))
      .normalize();
    const isOffTarget =
      !isTargetShot &&
      progress > 0.52 &&
      projectileIndex % missileEvadeOffTargetTracerInterval === 3;
    const aimVector = axis
      .clone()
      .multiplyScalar(range)
      .addScaledVector(radialDirection, coneRadius);

    if (isOffTarget) {
      const missAngle = seededUnit(seededIndex, 710) * Math.PI * 2;
      const missDirection = coneBasisA
        .clone()
        .multiplyScalar(Math.cos(missAngle))
        .addScaledVector(coneBasisB, Math.sin(missAngle));
      const missDistance = range * THREE.MathUtils.lerp(0.028, 0.058, seededUnit(seededIndex, 711));
      aimVector.addScaledVector(missDirection, missDistance);
    }

    const shotDirection = aimVector.normalize();
    const travelProgress = clamp(
      shotAge / missileEvadeProjectileTravelDurationSeconds,
      0,
      missileEvadeProjectileFlightDurationSeconds / missileEvadeProjectileTravelDurationSeconds
    );
    const attack = smoothStep(0, 0.012, shotAge);
    const distanceFade = isTargetShot
      ? 1
      : 1 -
        smoothStep(
          missileEvadeProjectileDistanceFadeStartRatio,
          missileEvadeProjectileFlightDurationSeconds / missileEvadeProjectileTravelDurationSeconds,
          travelProgress
        );
    const shotOpacity =
      (0.34 + seededUnit(seededIndex, 707) * 0.12 + terminalDensity * 0.3) * attack * distanceFade;

    for (let trailIndex = 0; trailIndex < missileEvadeProjectileTrailSamples; trailIndex += 1) {
      const trailProgress = trailIndex / Math.max(1, missileEvadeProjectileTrailSamples - 1);
      const trailFlightProgress =
        travelProgress - missileEvadeProjectileTrailLengthRatio * (1 - trailProgress);

      if (trailFlightProgress <= 0) {
        continue;
      }

      const trailOpacity =
        shotOpacity *
        THREE.MathUtils.lerp(0.12, 1, trailProgress) *
        THREE.MathUtils.lerp(0.8, 1, terminalDensity);

      if (trailOpacity <= 0.004) {
        continue;
      }

      const position = muzzlePosition
        .clone()
        .addScaledVector(shotDirection, range * trailFlightProgress);
      positions.push(position.x, position.y, position.z);
      colors.push(tracerColor.r, tracerColor.g, tracerColor.b);
      opacities.push(clamp(trailOpacity, 0, 1));
    }
  }

  if (positions.length === 0) {
    return null;
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  geometry.setAttribute("projectileOpacity", new THREE.Float32BufferAttribute(opacities, 1));
  const material = new THREE.ShaderMaterial({
    transparent: true,
    depthTest: true,
    depthWrite: false,
    blending: THREE.NormalBlending,
    vertexShader: `
      attribute vec3 color;
      attribute float projectileOpacity;
      varying vec3 vColor;
      varying float vProjectileOpacity;

      void main() {
        vColor = color;
        vProjectileOpacity = projectileOpacity;
        gl_PointSize = 1.0;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying vec3 vColor;
      varying float vProjectileOpacity;

      void main() {
        gl_FragColor = vec4(vColor, max(vProjectileOpacity, 0.0));
      }
    `
  });
  material.toneMapped = false;
  const burst = new THREE.Points(geometry, material);
  burst.name = "missile-evade-pds-projectile-saturation";
  burst.renderOrder = 45;
  burst.frustumCulled = false;
  return burst;
}

function createMissileEvadeTracerBurst(
  getMuzzlePosition: (projectileIndex: number) => THREE.Vector3 | null,
  detonationPosition: THREE.Vector3,
  age: number,
  seed: number
): THREE.Group | null {
  if (age > missileEvadeTracerBurstDurationSeconds + missileEvadeTracerAfterglowDurationSeconds) {
    return null;
  }
  const positions: number[] = [];
  const colors: number[] = [];
  const opacities: number[] = [];
  const trailPointPositions: number[] = [];
  const trailPointOpacities: number[] = [];
  const headPositions: number[] = [];
  const headOpacities: number[] = [];
  const seedOffset = Math.floor(seed * 100_003);

  function appendSegment(
    start: THREE.Vector3,
    end: THREE.Vector3,
    color: THREE.ColorRepresentation,
    tailOpacity: number,
    headOpacity: number
  ): void {
    if (Math.max(tailOpacity, headOpacity) <= 0.004) {
      return;
    }

    positions.push(start.x, start.y, start.z, end.x, end.y, end.z);
    const tracerColor = new THREE.Color(color);
    colors.push(
      tracerColor.r,
      tracerColor.g,
      tracerColor.b,
      tracerColor.r,
      tracerColor.g,
      tracerColor.b
    );
    opacities.push(clamp(tailOpacity, 0, 1), clamp(headOpacity, 0, 1));

    for (let pointIndex = 0; pointIndex < missileEvadeTracerTrailPointSamples; pointIndex += 1) {
      const pointProgress = pointIndex / Math.max(1, missileEvadeTracerTrailPointSamples - 1);
      const pointOpacity = THREE.MathUtils.lerp(tailOpacity, headOpacity, pointProgress);

      if (pointOpacity <= 0.004) {
        continue;
      }

      trailPointPositions.push(
        THREE.MathUtils.lerp(start.x, end.x, pointProgress),
        THREE.MathUtils.lerp(start.y, end.y, pointProgress),
        THREE.MathUtils.lerp(start.z, end.z, pointProgress)
      );
      trailPointOpacities.push(clamp(pointOpacity, 0, 1));
    }
  }

  let projectileIndex = 0;
  let tracerIndex = 0;

  while (projectileIndex < missileEvadeProjectileCount) {
    const seededIndex = projectileIndex + seedOffset;
    const rawProgress = projectileIndex / Math.max(1, missileEvadeProjectileCount - 1);
    const progress = getMissileEvadeTracerEmissionProgress(rawProgress);
    const terminalDensity = smootherStep(0.58, 1, progress);
    const projectileInterval = getMissileEvadeTracerProjectileInterval(
      tracerIndex,
      terminalDensity
    );
    const isTargetShot = projectileIndex + projectileInterval >= missileEvadeProjectileCount;
    const segmentAge =
      age -
      (progress * missileEvadeTracerBurstDurationSeconds + seededUnit(seededIndex, 705) * 0.002);
    const lifetime =
      missileEvadeTracerAfterglowDurationSeconds +
      seededUnit(seededIndex, 706) * 0.026 -
      smoothStep(0.7, 1, progress) * 0.018;

    if (segmentAge < 0 || segmentAge > lifetime) {
      projectileIndex += projectileInterval;
      tracerIndex += 1;
      continue;
    }

    const muzzlePosition = getMuzzlePosition(projectileIndex);

    if (muzzlePosition === null) {
      projectileIndex += projectileInterval;
      tracerIndex += 1;
      continue;
    }

    const tracerInterceptionPosition = getMissileEvadeTracerInterceptionPosition(
      detonationPosition,
      muzzlePosition,
      progress
    );
    const axis = tracerInterceptionPosition.sub(muzzlePosition);
    const range = axis.length();

    if (range <= 0.001) {
      projectileIndex += projectileInterval;
      tracerIndex += 1;
      continue;
    }

    axis.normalize();
    const coneBasisA = new THREE.Vector3().crossVectors(axis, mapPlaneUp);

    if (coneBasisA.lengthSq() < 0.0001) {
      coneBasisA.set(0, 0, 1).cross(axis);
    }

    coneBasisA.normalize();
    const coneBasisB = new THREE.Vector3().crossVectors(axis, coneBasisA).normalize();
    const spinAngle = getMissileEvadeTracerSpinAngle(progress, missileEvadeTracerSpiralTurns);
    const naturalConeRadius =
      getMissileEvadeTracerConeRadius(progress, range) *
      (0.985 + seededUnit(seededIndex, 703) * 0.03);
    const coneRadius = isTargetShot
      ? 0
      : Math.max(naturalConeRadius, range * missileEvadeTracerMinimumMissRadiusRatio);
    const radialDirection = coneBasisA
      .clone()
      .multiplyScalar(Math.cos(spinAngle))
      .addScaledVector(coneBasisB, Math.sin(spinAngle))
      .normalize();
    const isOffTarget =
      !isTargetShot && progress > 0.52 && tracerIndex % missileEvadeOffTargetTracerInterval === 3;
    const aimVector = axis
      .clone()
      .multiplyScalar(range)
      .addScaledVector(radialDirection, coneRadius);

    if (isOffTarget) {
      const missAngle = seededUnit(seededIndex, 710) * Math.PI * 2;
      const missDirection = coneBasisA
        .clone()
        .multiplyScalar(Math.cos(missAngle))
        .addScaledVector(coneBasisB, Math.sin(missAngle));
      const missDistance = range * THREE.MathUtils.lerp(0.012, 0.028, seededUnit(seededIndex, 711));
      aimVector.addScaledVector(missDirection, missDistance);
    }

    const shotDirection = aimVector.normalize();

    const segmentProgress = clamp(segmentAge / lifetime, 0, 1);
    const attack = smoothStep(0, 0.012, segmentAge);
    const fade = 1 - smootherStep(0.18, 1, segmentProgress);
    const distanceFade = 0.36;
    const tracerColor = 0xffffff;
    const baseOpacity = 0.18 + seededUnit(seededIndex, 707) * 0.08 + terminalDensity * 0.18;
    const rawFlightProgress = segmentAge / missileEvadeTracerFlightDurationSeconds;
    const flightProgress = clamp(rawFlightProgress, 0, 1);
    const headDistance = range * flightProgress;
    const wallFade =
      1 -
      smoothStep(
        0.01,
        missileEvadeTracerWallFadeSeconds,
        Math.max(0, segmentAge - missileEvadeTracerFlightDurationSeconds)
      );
    const headOpacity = baseOpacity * attack * fade * distanceFade * wallFade;
    const postImpactProgress = clamp(
      (segmentAge - missileEvadeTracerFlightDurationSeconds) /
        missileEvadeTracerImpactTrailCollapseSeconds,
      0,
      1
    );
    const initialTrailLength = Math.min(headDistance, range * missileEvadeTracerTrailLengthRatio);
    const trailLength =
      isTargetShot && segmentAge > missileEvadeTracerFlightDurationSeconds
        ? range * missileEvadeTracerTrailLengthRatio * (1 - smootherStep(0, 1, postImpactProgress))
        : initialTrailLength;

    if (trailLength > range * 0.002 && headOpacity > 0.004) {
      const trailStartDistance = Math.max(0, headDistance - trailLength);
      const tail = muzzlePosition.clone().addScaledVector(shotDirection, trailStartDistance);
      const head = muzzlePosition.clone().addScaledVector(shotDirection, headDistance);
      const tailOpacity = headOpacity * THREE.MathUtils.lerp(0.025, 0.06, terminalDensity);

      appendSegment(tail, head, tracerColor, tailOpacity, headOpacity);
      headPositions.push(head.x, head.y, head.z);
      headOpacities.push(Math.min(1, headOpacity * 2.4));
    }

    projectileIndex += projectileInterval;
    tracerIndex += 1;
  }

  if (positions.length === 0 || headPositions.length === 0) {
    return null;
  }

  const trailGeometry = new THREE.BufferGeometry();
  trailGeometry.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  trailGeometry.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  trailGeometry.setAttribute("tracerOpacity", new THREE.Float32BufferAttribute(opacities, 1));
  const trailMaterial = new THREE.ShaderMaterial({
    transparent: true,
    depthTest: true,
    depthWrite: false,
    blending: THREE.NormalBlending,
    vertexShader: `
      attribute vec3 color;
      attribute float tracerOpacity;
      varying vec3 vColor;
      varying float vTracerOpacity;

      void main() {
        vColor = color;
        vTracerOpacity = tracerOpacity;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying vec3 vColor;
      varying float vTracerOpacity;

      void main() {
        gl_FragColor = vec4(vColor, max(vTracerOpacity, 0.0));
      }
    `
  });
  trailMaterial.toneMapped = false;
  const trails = new THREE.LineSegments(trailGeometry, trailMaterial);
  trails.name = "missile-evade-pds-tracer-trails";
  const trailPointGeometry = new THREE.BufferGeometry();
  trailPointGeometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(trailPointPositions, 3)
  );
  trailPointGeometry.setAttribute(
    "tracerTrailOpacity",
    new THREE.Float32BufferAttribute(trailPointOpacities, 1)
  );
  const trailPointMaterial = new THREE.ShaderMaterial({
    transparent: true,
    depthTest: true,
    depthWrite: false,
    blending: THREE.NormalBlending,
    vertexShader: `
      attribute float tracerTrailOpacity;
      varying float vTracerTrailOpacity;

      void main() {
        vTracerTrailOpacity = tracerTrailOpacity;
        gl_PointSize = 1.0;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying float vTracerTrailOpacity;

      void main() {
        vec2 center = gl_PointCoord - vec2(0.5);

        if (dot(center, center) > 0.25) {
          discard;
        }

        gl_FragColor = vec4(vec3(1.0), max(vTracerTrailOpacity, 0.0));
      }
    `
  });
  trailPointMaterial.toneMapped = false;
  const trailPoints = new THREE.Points(trailPointGeometry, trailPointMaterial);
  trailPoints.name = "missile-evade-pds-tracer-trail-points";
  const headGeometry = new THREE.BufferGeometry();
  headGeometry.setAttribute("position", new THREE.Float32BufferAttribute(headPositions, 3));
  headGeometry.setAttribute(
    "tracerHeadOpacity",
    new THREE.Float32BufferAttribute(headOpacities, 1)
  );
  const headMaterial = new THREE.ShaderMaterial({
    transparent: true,
    depthTest: true,
    depthWrite: false,
    blending: THREE.NormalBlending,
    vertexShader: `
      attribute float tracerHeadOpacity;
      varying float vTracerHeadOpacity;

      void main() {
        vTracerHeadOpacity = tracerHeadOpacity;
        gl_PointSize = 1.0;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying float vTracerHeadOpacity;

      void main() {
        vec2 center = gl_PointCoord - vec2(0.5);

        if (dot(center, center) > 0.25) {
          discard;
        }

        gl_FragColor = vec4(vec3(1.0), max(vTracerHeadOpacity, 0.0));
      }
    `
  });
  headMaterial.toneMapped = false;
  const heads = new THREE.Points(headGeometry, headMaterial);
  heads.name = "missile-evade-pds-tracer-heads";
  const burst = new THREE.Group();
  burst.name = "missile-evade-pds-tracer-burst";
  burst.renderOrder = 45;
  burst.frustumCulled = false;
  burst.add(trails, trailPoints, heads);
  return burst;
}

function getMissileEvadeTracerEmissionProgress(rawProgress: number): number {
  if (rawProgress < 0.24) {
    return (rawProgress / 0.24) * 0.48;
  }

  const terminalProgress = (rawProgress - 0.24) / 0.76;
  return (
    0.48 +
    (1 - Math.pow(1 - terminalProgress, missileEvadeTracerTerminalAccelerationExponent)) * 0.52
  );
}

function getMissileEvadeTracerProjectileInterval(
  tracerIndex: number,
  terminalDensity: number
): number {
  const baseInterval =
    tracerIndex % 2 === 0
      ? missileEvadeTracerProjectileIntervalA
      : missileEvadeTracerProjectileIntervalB;
  const centerThinning = THREE.MathUtils.lerp(
    1,
    missileEvadeCentralTracerIntervalMultiplier,
    terminalDensity
  );
  return Math.max(1, Math.round(baseInterval * centerThinning));
}

function getMissileEvadeInterceptionDelaySeconds(seed: number): number {
  if (missileEvadeProjectilePresentationStyle === "saturation") {
    const seededIndex = missileEvadeProjectileCount - 1 + Math.floor(seed * 100_003);
    return (
      missileEvadeTracerBurstDurationSeconds +
      seededUnit(seededIndex, 705) * 0.002 +
      missileEvadeProjectileTravelDurationSeconds
    );
  }

  return getMissileEvadeTracerTargetShotImpactSeconds(seed);
}

function getMissileEvadeTracerTargetShotImpactSeconds(seed: number): number {
  const seedOffset = Math.floor(seed * 100_003);
  let projectileIndex = 0;
  let tracerIndex = 0;

  while (projectileIndex < missileEvadeProjectileCount) {
    const seededIndex = projectileIndex + seedOffset;
    const rawProgress = projectileIndex / Math.max(1, missileEvadeProjectileCount - 1);
    const progress = getMissileEvadeTracerEmissionProgress(rawProgress);
    const terminalDensity = smootherStep(0.58, 1, progress);
    const projectileInterval = getMissileEvadeTracerProjectileInterval(
      tracerIndex,
      terminalDensity
    );

    if (projectileIndex + projectileInterval >= missileEvadeProjectileCount) {
      return (
        progress * missileEvadeTracerBurstDurationSeconds +
        seededUnit(seededIndex, 705) * 0.002 +
        missileEvadeTracerFlightDurationSeconds
      );
    }

    projectileIndex += projectileInterval;
    tracerIndex += 1;
  }

  return missileEvadeDetonationDelaySeconds;
}

function getMissileEvadeTracerSpinAngle(progress: number, turns: number): number {
  return getMissileEvadeTracerSpiralProgress(progress) * Math.PI * 2 * turns;
}

function getMissileEvadeTracerConeRadius(progress: number, range: number): number {
  const initialSweep = 1 - smootherStep(0.04, 1, progress);
  const terminalNeedle = 1 - smoothStep(0.82, 1, progress) * 0.995;
  return range * missileEvadeTracerMaxConeRadiusRatio * initialSweep * terminalNeedle;
}

function getMissileEvadeTracerSpiralProgress(progress: number): number {
  return 1 - Math.pow(1 - progress, missileEvadeTracerSpiralEaseExponent);
}

function getMissileEvadeTracerInterceptionPosition(
  detonationPosition: THREE.Vector3,
  muzzlePosition: THREE.Vector3,
  approachProgress: number
): THREE.Vector3 {
  return detonationPosition
    .clone()
    .lerp(muzzlePosition, clamp(approachProgress, 0, 1) * missileEvadeTracerMissileApproachRatio);
}

function getMissileFlightProgress(missile: ActiveMissile, visualTurn: number): number {
  return clamp((visualTurn - missile.issuedTurn) / Math.max(1, missile.missileEtaTurns), 0, 1);
}

function getPolylineVerticalRange(points: readonly THREE.Vector3[]): Readonly<{
  max: number;
  min: number;
}> {
  if (points.length === 0) {
    return { max: 0, min: 0 };
  }

  let min = Number.POSITIVE_INFINITY;
  let max = Number.NEGATIVE_INFINITY;

  for (const point of points) {
    min = Math.min(min, point.y);
    max = Math.max(max, point.y);
  }

  return {
    max: roundDebugNumber(max),
    min: roundDebugNumber(min)
  };
}

function roundDebugNumber(value: number): number {
  return Math.round(value * 1000) / 1000;
}

function findSharpestTrajectoryTurn(points: readonly THREE.Vector3[]): Readonly<{
  index: number;
  t: number;
  turnDegrees: number;
  previous: THREE.Vector3;
  current: THREE.Vector3;
  next: THREE.Vector3;
}> | null {
  let best: Readonly<{
    index: number;
    t: number;
    turnDegrees: number;
    previous: THREE.Vector3;
    current: THREE.Vector3;
    next: THREE.Vector3;
  }> | null = null;

  for (let index = 1; index < points.length - 1; index += 1) {
    const previous = points[index - 1];
    const current = points[index];
    const next = points[index + 1];

    if (previous === undefined || current === undefined || next === undefined) {
      continue;
    }

    const incoming = current.clone().sub(previous);
    const outgoing = next.clone().sub(current);

    if (incoming.lengthSq() <= 0.0001 || outgoing.lengthSq() <= 0.0001) {
      continue;
    }

    incoming.normalize();
    outgoing.normalize();
    const turnDegrees = THREE.MathUtils.radToDeg(Math.acos(clamp(incoming.dot(outgoing), -1, 1)));

    if (best === null || turnDegrees > best.turnDegrees) {
      best = {
        index,
        t: index / Math.max(1, points.length - 1),
        turnDegrees,
        previous: previous.clone(),
        current: current.clone(),
        next: next.clone()
      };
    }
  }

  return best;
}

function normalizeRadians(angle: number): number {
  let normalized = angle;

  while (normalized <= -Math.PI) {
    normalized += Math.PI * 2;
  }

  while (normalized > Math.PI) {
    normalized -= Math.PI * 2;
  }

  return normalized;
}

function getAngularDistanceRadians(first: number, second: number): number {
  return Math.abs(normalizeRadians(first - second));
}

function lerpRadians(from: number, to: number, amount: number): number {
  return from + normalizeRadians(to - from) * clamp(amount, 0, 1);
}

function getCameraYawForPlanarOffset(offset: THREE.Vector3): number {
  const planarOffset = new THREE.Vector3(offset.x, 0, offset.z);

  if (planarOffset.lengthSq() <= 0.0001) {
    return 0;
  }

  planarOffset.normalize();
  return Math.atan2(planarOffset.x, planarOffset.z);
}

function getCameraPositionForOrbitState(
  focus: THREE.Vector3,
  yaw: number,
  pitch: number,
  distance: number
): THREE.Vector3 {
  const horizontal = Math.cos(pitch) * distance;
  const vertical = Math.sin(pitch) * distance;

  return new THREE.Vector3(
    focus.x + Math.sin(yaw) * horizontal,
    focus.y + vertical,
    focus.z + Math.cos(yaw) * horizontal
  );
}

function getYawForDirection(direction: THREE.Vector3): number {
  const planarDirection = new THREE.Vector3(direction.x, 0, direction.z);

  if (planarDirection.lengthSq() <= 0.0001) {
    return 0;
  }

  planarDirection.normalize();
  return Math.atan2(-planarDirection.z, planarDirection.x);
}

function getMedianNumber(values: readonly number[]): number {
  if (values.length === 0) {
    return 0;
  }

  const sorted = [...values].sort((first, second) => first - second);
  const middle = Math.floor(sorted.length / 2);

  if (sorted.length % 2 === 1) {
    return sorted[middle] ?? 0;
  }

  return ((sorted[middle - 1] ?? 0) + (sorted[middle] ?? 0)) / 2;
}

function getTrajectoryLabelAnchor(points: readonly THREE.Vector3[]): THREE.Vector3 | null {
  if (points.length === 0) {
    return null;
  }

  return samplePolylineAtProgress(points, 0.82).position.clone();
}

function getBurnFutureLabelAnchor(
  currentPosition: THREE.Vector3,
  futurePosition: THREE.Vector3,
  futureRingRadius: number
): THREE.Vector3 | null {
  const direction = futurePosition.clone().sub(currentPosition);
  direction.y = 0;

  if (direction.lengthSq() <= 0.0001) {
    return null;
  }

  direction.normalize();
  const side = new THREE.Vector3(-direction.z, 0, direction.x);
  return futurePosition
    .clone()
    .addScaledVector(side, clamp(futureRingRadius * 0.42, 5, 18))
    .addScaledVector(mapPlaneUp, 2.4);
}

function getBurnTrajectoryLabelAnchor(points: readonly THREE.Vector3[]): THREE.Vector3 | null {
  if (points.length === 0) {
    return null;
  }

  const sample = samplePolylineAtProgress(points, 0.78);
  const side = new THREE.Vector3(-sample.direction.z, 0, sample.direction.x);

  if (side.lengthSq() <= 0.0001) {
    side.set(1, 0, 0);
  }

  return sample.position
    .clone()
    .addScaledVector(side.normalize(), clamp(measurePolylineLength(points) * 0.018, 5, 14))
    .addScaledVector(mapPlaneUp, 2.4);
}

function groupIncomingMissilesByTarget(
  missiles: readonly PendingFireOrder[]
): ReadonlyMap<string, readonly PendingFireOrder[]> {
  const grouped = new Map<string, PendingFireOrder[]>();

  for (const missile of missiles) {
    const current = grouped.get(missile.targetNodeId) ?? [];
    current.push(missile);
    grouped.set(missile.targetNodeId, current);
  }

  return grouped;
}

function getEarliestIncomingMissile(
  missiles: readonly PendingFireOrder[]
): PendingFireOrder | null {
  return (
    [...missiles].sort((first, second) => {
      if (first.impactTurn !== second.impactTurn) {
        return first.impactTurn - second.impactTurn;
      }

      return first.id.localeCompare(second.id);
    })[0] ?? null
  );
}

export function getIncomingFireImpactChronology<
  TFireImpact extends Pick<PendingFireOrder, "id" | "impactTurn">
>(missiles: readonly TFireImpact[]): readonly TFireImpact[] {
  const representativeByImpactTurn = new Map<number, TFireImpact>();

  for (const missile of [...missiles].sort((first, second) => first.id.localeCompare(second.id))) {
    if (!representativeByImpactTurn.has(missile.impactTurn)) {
      representativeByImpactTurn.set(missile.impactTurn, missile);
    }
  }

  return [...representativeByImpactTurn.values()].sort((first, second) => {
    return first.impactTurn - second.impactTurn || first.id.localeCompare(second.id);
  });
}

function compareFireArrivalsForPresentation(
  first: Pick<PendingFireOrder, "impactTurn" | "targetNodeId"> &
    Partial<Pick<PendingFireOrder, "id">>,
  second: Pick<PendingFireOrder, "impactTurn" | "targetNodeId"> &
    Partial<Pick<PendingFireOrder, "id">>
): number {
  return (
    first.impactTurn - second.impactTurn ||
    first.targetNodeId.localeCompare(second.targetNodeId) ||
    (first.id ?? "").localeCompare(second.id ?? "")
  );
}

function compareMissileThreatsForPresentation(first: ActiveMissile, second: ActiveMissile): number {
  return compareFireArrivalsForPresentation(first, second);
}

function createActiveBurnPickerObject(): THREE.Mesh {
  return createTargetPickerObject("active-burn-picker");
}

