function applyPlanetRingGlintMultiplier(group: THREE.Group, multiplier: number): void {
  for (const child of group.children) {
    if (child instanceof THREE.Mesh) {
      const ringMesh = child as THREE.Mesh<THREE.BufferGeometry, THREE.Material | THREE.Material[]>;
      const material = ringMesh.material;

      if (material instanceof THREE.ShaderMaterial) {
        setShaderUniformNumber(material, "glintPresentationBoost", multiplier);
      }
    }
  }
}

function createUranusRingVisibilityThread(options: {
  name: string;
  radiusRatio: number;
  tubeRadius: number;
  color: THREE.ColorRepresentation;
  opacity: number;
}): THREE.Mesh {
  const geometry = new THREE.TorusGeometry(
    uranusRingSystemBaseOuterRadius * options.radiusRatio,
    options.tubeRadius,
    10,
    224
  );
  geometry.rotateX(Math.PI / 2);
  const material = new THREE.MeshBasicMaterial({
    color: options.color,
    transparent: true,
    opacity: options.opacity,
    depthTest: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending
  });
  material.toneMapped = false;
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = options.name;
  mesh.renderOrder = 24.2;
  return mesh;
}

function createSaturnRingBand(options: {
  name: string;
  innerRatio: number;
  outerRatio: number;
  color: THREE.ColorRepresentation;
  opacity: number;
  seed: number;
  bloomBoost: number;
  headOnOpacity?: number;
  edgeOnOpacityBoost?: number;
  ambientLightBoost?: number;
  sunFacingExponent?: number;
  glintExponent?: number;
  glintBoost?: number;
  baseOuterRadius?: number;
}): THREE.Mesh {
  const baseOuterRadius = options.baseOuterRadius ?? saturnRingSystemBaseOuterRadius;
  const innerRadius = baseOuterRadius * options.innerRatio;
  const outerRadius = baseOuterRadius * options.outerRatio;
  const geometry = new THREE.RingGeometry(innerRadius, outerRadius, 224, 1);
  geometry.rotateX(Math.PI / 2);
  const material = createSaturnRingMaterial(
    options.color,
    options.opacity,
    innerRadius,
    outerRadius,
    options.seed,
    options.bloomBoost,
    options.headOnOpacity ?? 1,
    options.edgeOnOpacityBoost ?? 1,
    options.ambientLightBoost ?? 0,
    options.sunFacingExponent ?? 0.48,
    options.glintExponent ?? 22,
    options.glintBoost ?? 1
  );
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = options.name;
  mesh.userData["planetRingBaseOpacity"] = options.opacity;
  mesh.userData["planetRingHeadOnOpacity"] = options.headOnOpacity ?? 1;
  mesh.userData["planetRingEdgeOnOpacityBoost"] = options.edgeOnOpacityBoost ?? 1;
  mesh.renderOrder = 23.5 + options.bloomBoost * 0.01;
  return mesh;
}

function createSaturnRingMaterial(
  color: THREE.ColorRepresentation,
  opacity: number,
  innerRadius: number,
  outerRadius: number,
  seed: number,
  bloomBoost: number,
  headOnOpacity: number,
  edgeOnOpacityBoost: number,
  ambientLightBoost: number,
  sunFacingExponent: number,
  glintExponent: number,
  glintBoost: number
): THREE.ShaderMaterial {
  const material = new THREE.ShaderMaterial({
    transparent: true,
    depthTest: true,
    depthWrite: false,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending,
    uniforms: {
      ringColor: { value: new THREE.Color(color) },
      opacity: { value: opacity },
      innerRadius: { value: innerRadius },
      outerRadius: { value: outerRadius },
      sunPosition: { value: new THREE.Vector3() },
      time: { value: 0 },
      beatElapsed: { value: 0 },
      beatSeconds: { value: 1 },
      beatSync: { value: 0 },
      seed: { value: seed },
      bloomBoost: { value: bloomBoost },
      headOnOpacity: { value: headOnOpacity },
      edgeOnOpacityBoost: { value: edgeOnOpacityBoost },
      ambientLightBoost: { value: ambientLightBoost },
      sunFacingExponent: { value: sunFacingExponent },
      glintExponent: { value: glintExponent },
      glintBoost: { value: glintBoost },
      glintPresentationBoost: { value: 1 },
      ...createDynamicSolarLightingUniforms()
    },
    vertexShader: `
      varying vec3 vLocalPosition;
      varying vec3 vWorldPosition;
      varying vec3 vWorldNormal;

      void main() {
        vLocalPosition = position;
        vec4 worldPosition = modelMatrix * vec4(position, 1.0);
        vWorldPosition = worldPosition.xyz;
        vWorldNormal = normalize(mat3(modelMatrix) * normal);
        gl_Position = projectionMatrix * viewMatrix * worldPosition;
      }
    `,
    fragmentShader: `
      uniform vec3 ringColor;
      uniform float opacity;
      uniform float innerRadius;
      uniform float outerRadius;
      uniform vec3 sunPosition;
      uniform float time;
      uniform float beatElapsed;
      uniform float beatSeconds;
      uniform float beatSync;
      uniform float seed;
      uniform float bloomBoost;
      uniform float headOnOpacity;
      uniform float edgeOnOpacityBoost;
      uniform float ambientLightBoost;
      uniform float sunFacingExponent;
      uniform float glintExponent;
      uniform float glintBoost;
      uniform float glintPresentationBoost;
      varying vec3 vLocalPosition;
      varying vec3 vWorldPosition;
      varying vec3 vWorldNormal;
      ${dynamicSolarLightingShaderFunctions}

      float beatSynchronizedAngle(float angularFrequency) {
        float safeFrequency = max(0.000001, abs(angularFrequency));
        float baseCycle = 6.28318530718 / safeFrequency;
        float gridSeconds = max(0.000001, beatSeconds / ${presentationCycleBeatGridSubdivisions.toFixed(1)});
        float gridSteps = max(1.0, floor(baseCycle / gridSeconds + 0.5));
        float synchronizedCycle = gridSteps * gridSeconds;
        float nudgeRatio = abs(synchronizedCycle - baseCycle) / max(0.001, baseCycle);

        if (beatSync < 0.5 || nudgeRatio > ${presentationBeatMaxNudgeRatio.toFixed(2)}) {
          return time * angularFrequency;
        }

        return beatElapsed / synchronizedCycle * 6.28318530718;
      }

      void main() {
        vec3 normal = normalize(vWorldNormal);
        vec3 lightDirection = normalize(sunPosition - vWorldPosition);
        vec3 viewDirection = normalize(cameraPosition - vWorldPosition);
        float solarVisibility = getDynamicSolarVisibility(vWorldPosition, sunPosition);
        float radial = length(vLocalPosition.xz);
        float radialProgress =
          clamp((radial - innerRadius) / max(0.001, outerRadius - innerRadius), 0.0, 1.0);
        float innerFeather = smoothstep(0.0, 0.08, radialProgress);
        float outerFeather = 1.0 - smoothstep(0.88, 1.0, radialProgress);
        float softEdge = innerFeather * outerFeather;
        float angle = atan(vLocalPosition.z, vLocalPosition.x);
        float bandNoise =
          0.56 +
          sin(radial * 17.0 + seed * 9.0) * 0.22 +
          sin(radial * 38.0 - angle * 2.7 + seed * 5.0) * 0.13 +
          sin(angle * 9.0 + seed * 3.0) * 0.05;
        float bandStructure = smoothstep(0.18, 0.72, bandNoise);
        float sunFacing = pow(max(abs(dot(normal, lightDirection)), 0.0), sunFacingExponent);
        vec3 reflectedLight = reflect(-lightDirection, normal);
        float glint = pow(max(dot(reflectedLight, viewDirection), 0.0), glintExponent);
        float grazing = pow(1.0 - abs(dot(normal, viewDirection)), 1.45);
        float headOn = pow(abs(dot(normal, viewDirection)), 0.72);
        float viewProfile = clamp(mix(edgeOnOpacityBoost, headOnOpacity, headOn), 0.0, 2.2);
        float shimmer = 0.86 + sin(
          angle * 5.0 + radial * 5.5 + beatSynchronizedAngle(0.18) + seed * 4.0
        ) * 0.14;
        float glintBreath = 0.74 + sin(
          angle * 3.4 + beatSynchronizedAngle(-0.14) + seed * 7.0
        ) * 0.14;
        float alpha =
          opacity *
          softEdge *
          shimmer *
          viewProfile *
          (0.42 + bandStructure * 0.72) *
          (0.62 + sunFacing * solarVisibility * 0.82 + grazing * 0.28);
        vec3 solarGold = vec3(1.0, 0.73, 0.42);
        vec3 color = ringColor * (
          0.48 +
          ambientLightBoost +
          sunFacing * solarVisibility * 0.62 +
          grazing * 0.18
        );
        color +=
          solarGold *
          glint *
          solarVisibility *
          glintBreath *
          (0.85 + bloomBoost * 1.25) *
          glintBoost *
          glintPresentationBoost;
        alpha +=
          glint *
          solarVisibility *
          glintBreath *
          opacity *
          softEdge *
          viewProfile *
          (1.15 + bloomBoost * 1.9) *
          glintBoost *
          glintPresentationBoost;

        if (alpha <= 0.002) {
          discard;
        }

        gl_FragColor = vec4(color, alpha);
      }
    `
  });
  material.toneMapped = false;
  return material;
}

function getDisplayPositionForRawMapPosition(
  position: Vec2,
  snapshot: SolarSystemSnapshot,
  displayState: CinematicDisplayState
): Vec2 {
  const nearestBody = findNearestBody(position, snapshot.bodies);

  if (
    nearestBody !== null &&
    nearestBody.distance <= Math.max(30, nearestBody.body.visualRadius * 6)
  ) {
    const bodyDisplayPosition = displayState.bodyPositions.get(nearestBody.body.id);

    if (bodyDisplayPosition !== undefined) {
      const localScale = getBodyDisplayOffsetScale(nearestBody.body, snapshot, displayState);
      return {
        x: bodyDisplayPosition.x + (position.x - nearestBody.body.position.x) * localScale,
        y: bodyDisplayPosition.y + (position.y - nearestBody.body.position.y) * localScale
      };
    }
  }

  return {
    x: position.x * displayState.heliocentricScale,
    y: position.y * displayState.heliocentricScale
  };
}

function getRawMapPositionForDisplayPosition(
  displayPosition: Vec2,
  snapshot: SolarSystemSnapshot,
  displayState: CinematicDisplayState
): Vec2 {
  let nearestDisplayBody: Readonly<{
    body: BodySnapshot;
    displayPosition: Vec2;
    distance: number;
    localScale: number;
    threshold: number;
  }> | null = null;

  for (const body of snapshot.bodies) {
    const bodyDisplayPosition = displayState.bodyPositions.get(body.id);

    if (bodyDisplayPosition === undefined) {
      continue;
    }

    const localScale = getBodyDisplayOffsetScale(body, snapshot, displayState);
    const threshold = Math.max(30, body.visualRadius * 6) * localScale;
    const distance = Math.hypot(
      displayPosition.x - bodyDisplayPosition.x,
      displayPosition.y - bodyDisplayPosition.y
    );

    if (distance > threshold) {
      continue;
    }

    const normalizedDistance = distance / Math.max(0.0001, threshold);
    const nearestNormalizedDistance =
      nearestDisplayBody === null
        ? Number.POSITIVE_INFINITY
        : nearestDisplayBody.distance / Math.max(0.0001, nearestDisplayBody.threshold);

    if (
      nearestDisplayBody === null ||
      normalizedDistance < nearestNormalizedDistance ||
      (normalizedDistance === nearestNormalizedDistance && distance < nearestDisplayBody.distance)
    ) {
      nearestDisplayBody = {
        body,
        displayPosition: bodyDisplayPosition,
        distance,
        localScale,
        threshold
      };
    }
  }

  if (nearestDisplayBody !== null) {
    const localScale = Math.max(0.0001, nearestDisplayBody.localScale);
    return {
      x:
        nearestDisplayBody.body.position.x +
        (displayPosition.x - nearestDisplayBody.displayPosition.x) / localScale,
      y:
        nearestDisplayBody.body.position.y +
        (displayPosition.y - nearestDisplayBody.displayPosition.y) / localScale
    };
  }

  const heliocentricScale = Math.max(0.0001, displayState.heliocentricScale);
  return {
    x: displayPosition.x / heliocentricScale,
    y: displayPosition.y / heliocentricScale
  };
}

function findNearestBody(
  position: Vec2,
  bodies: readonly BodySnapshot[]
): Readonly<{ body: BodySnapshot; distance: number }> | null {
  let nearest: Readonly<{ body: BodySnapshot; distance: number }> | null = null;

  for (const body of bodies) {
    const distance = Math.hypot(position.x - body.position.x, position.y - body.position.y);

    if (nearest === null || distance < nearest.distance) {
      nearest = { body, distance };
    }
  }

  return nearest;
}

function getBodyDisplayOffsetScale(
  body: BodySnapshot,
  snapshot: SolarSystemSnapshot,
  displayState: CinematicDisplayState
): number {
  if (body.parentId === null || body.orbitRadius <= 0) {
    return displayState.heliocentricScale;
  }

  const parent = snapshot.bodies.find((candidate) => candidate.id === body.parentId);
  const bodyDisplayPosition = displayState.bodyPositions.get(body.id);
  const parentDisplayPosition =
    parent === undefined ? undefined : displayState.bodyPositions.get(parent.id);

  if (
    parent === undefined ||
    bodyDisplayPosition === undefined ||
    parentDisplayPosition === undefined
  ) {
    return displayState.heliocentricScale;
  }

  const displayOrbitRadius = Math.hypot(
    bodyDisplayPosition.x - parentDisplayPosition.x,
    bodyDisplayPosition.y - parentDisplayPosition.y
  );
  return displayOrbitRadius / body.orbitRadius;
}

function getProjectedShadowLengthMultiplier(body: BodySnapshot): number {
  return body.id === "jupiter" ||
    body.id === "saturn" ||
    body.id === "uranus" ||
    body.id === "neptune"
    ? giantProjectedShadowLengthMultiplier
    : 1;
}

function toVector3(position: Vec2): THREE.Vector3 {
  return new THREE.Vector3(position.x, 0, position.y);
}

function getBodyScale(body: BodySnapshot): number {
  if (body.visualClass === "star") {
    return body.visualRadius * 1.45;
  }

  if (body.kind === "moon") {
    return Math.max(5, body.visualRadius * 2.2);
  }

  return Math.max(8, body.visualRadius * 1.8);
}

function isEarthLikeProtectedBody(body: BodySnapshot): boolean {
  return body.visualClass === "protected";
}

function getBodySelfRotationSpeed(body: BodySnapshot, tuning: Cinematic3dVisualTuning): number {
  if (body.visualClass === "star") {
    return tuning.sunSurfaceAnimationSpeed;
  }

  if (isEarthLikeProtectedBody(body)) {
    return tuning.earthRotationSpeed;
  }

  const direction = body.id === "venus" || body.id === "uranus" ? -1 : 1;

  if (body.visualClass === "gasGiant" || body.visualClass === "iceGiant") {
    const giantVariation = THREE.MathUtils.lerp(
      0.92,
      1.24,
      hashStringToUnitInterval(`self-rotation:${body.id}`)
    );
    return direction * tuning.tritiumPatternSpeed * giantVariation;
  }

  const baseSpeed = body.kind === "moon" ? tuning.moonRotationSpeed : tuning.planetRotationSpeed;
  const variation = THREE.MathUtils.lerp(
    0.82,
    1.24,
    hashStringToUnitInterval(`self-rotation:${body.id}`)
  );

  return direction * baseSpeed * variation;
}

function getGiantPatternFamily(body: BodySnapshot): number {
  switch (body.id) {
    case "jupiter":
      return 1;
    case "saturn":
      return 2;
    case "uranus":
      return 3;
    case "neptune":
      return 4;
    default:
      return 0;
  }
}

function getLocalSystemRootId(
  body: BodySnapshot,
  bodiesById: ReadonlyMap<string, BodySnapshot>
): string | null {
  if (body.visualClass === "star") {
    return null;
  }

  let current: BodySnapshot = body;

  while (true) {
    if (current.visualClass === "star") {
      return null;
    }

    if (current.parentId === null) {
      return current.id;
    }

    const parent = bodiesById.get(current.parentId);

    if (parent === undefined || parent.visualClass === "star") {
      return current.id;
    }

    current = parent;
  }
}

function getMeshLocalDirection(mesh: THREE.Object3D, worldDirection: THREE.Vector3): THREE.Vector3 {
  const worldQuaternion = new THREE.Quaternion();
  mesh.getWorldQuaternion(worldQuaternion);
  return worldDirection.clone().applyQuaternion(worldQuaternion.invert()).normalize();
}

function getBodyPalette(body: BodySnapshot): Readonly<{
  base: THREE.ColorRepresentation;
  accent: THREE.ColorRepresentation;
  mottle: number;
}> {
  if (body.visualClass === "protected") {
    return { base: 0x2f6f91, accent: 0x8fb6d3, mottle: 0.09 };
  }

  if (body.visualClass === "protectedMoon") {
    return { base: 0xc7ccd4, accent: 0x777d88, mottle: 0.18 };
  }

  if (body.visualClass === "gasGiant") {
    if (body.id === "saturn") {
      return { base: 0xbda57b, accent: 0xf1d59a, mottle: 0 };
    }

    return { base: 0xae8d61, accent: 0xe7d0aa, mottle: 0 };
  }

  if (body.visualClass === "iceGiant") {
    if (body.id === "neptune") {
      return { base: 0x356fae, accent: 0x8bb9d5, mottle: 0 };
    }

    return { base: 0x5f9fb6, accent: 0xb6d7df, mottle: 0 };
  }

  if (body.visualClass === "dwarfBinary") {
    return { base: 0xa79c8e, accent: 0x625f63, mottle: 0.38 };
  }

  if (body.id === "mars") {
    return { base: 0xa56a4f, accent: 0x6d4539, mottle: 0.38 };
  }

  if (body.id === "venus") {
    return { base: 0xa88d65, accent: 0xd3b47d, mottle: 0.28 };
  }

  if (body.id === "mercury") {
    return { base: 0x827b72, accent: 0x4c4a48, mottle: 0.42 };
  }

  if (body.id === "io") {
    return { base: 0xb99e62, accent: 0x59493a, mottle: 0.44 };
  }

  if (body.id === "europa") {
    return { base: 0xb7afa0, accent: 0x69594f, mottle: 0.4 };
  }

  if (body.id === "ganymede") {
    return { base: 0x81766b, accent: 0xb0a18d, mottle: 0.46 };
  }

  if (body.id === "callisto") {
    return { base: 0x615d59, accent: 0x9a8976, mottle: 0.48 };
  }

  if (body.id === "titan") {
    return { base: 0xa88756, accent: 0xd0b477, mottle: 0.36 };
  }

  if (body.id === "iapetus") {
    return { base: 0xb7b1a4, accent: 0x4f4b4a, mottle: 0.5 };
  }

  if (body.id === "oberon") {
    return { base: 0x6e7074, accent: 0x9a857a, mottle: 0.42 };
  }

  if (body.id === "titania") {
    return { base: 0x9e9c94, accent: 0x727d7b, mottle: 0.4 };
  }

  if (body.id === "triton") {
    return { base: 0xa7a5a5, accent: 0x806f7a, mottle: 0.44 };
  }

  if (body.id === "charon") {
    return { base: 0x77777a, accent: 0xa08c85, mottle: 0.46 };
  }

  if (body.kind === "moon") {
    const paletteSeed = hashStringToUnitInterval(`solid-palette:${body.id}`);
    const paletteDetailSeed = hashStringToUnitInterval(`solid-palette-detail:${body.id}`);
    const base = new THREE.Color(0x928b83).offsetHSL(
      THREE.MathUtils.lerp(-0.035, 0.045, paletteSeed),
      THREE.MathUtils.lerp(-0.03, 0.055, paletteDetailSeed),
      THREE.MathUtils.lerp(-0.055, 0.045, paletteSeed)
    );
    const accent = new THREE.Color(0x5f6268).offsetHSL(
      THREE.MathUtils.lerp(0.035, -0.045, paletteSeed),
      THREE.MathUtils.lerp(-0.02, 0.07, paletteDetailSeed),
      THREE.MathUtils.lerp(-0.04, 0.06, paletteDetailSeed)
    );
    return { base, accent, mottle: THREE.MathUtils.lerp(0.38, 0.48, paletteDetailSeed) };
  }

  return { base: 0x91877a, accent: 0x5c574f, mottle: 0.34 };
}

function getSolidSurfaceFeatureStrength(body: BodySnapshot): number {
  if (
    body.visualClass === "star" ||
    body.visualClass === "protected" ||
    body.visualClass === "protectedMoon" ||
    body.visualClass === "gasGiant" ||
    body.visualClass === "iceGiant"
  ) {
    return 0;
  }

  const identityVariation = THREE.MathUtils.lerp(
    0.88,
    1,
    hashStringToUnitInterval(`solid-features:${body.id}`)
  );

  if (body.kind === "moon") {
    return 0.96 * identityVariation;
  }

  if (body.kind === "dwarfPlanet") {
    return 0.84 * identityVariation;
  }

  return 0.72 * identityVariation;
}

function hashBodySeed(id: string): number {
  let hash = 0;

  for (let index = 0; index < id.length; index += 1) {
    hash = (hash * 31 + id.charCodeAt(index)) % 997;
  }

  return 0.2 + hash / 997;
}

function hashStringToUnitInterval(id: string): number {
  let hash = 2166136261;

  for (let index = 0; index < id.length; index += 1) {
    hash ^= id.charCodeAt(index);
    hash = Math.imul(hash, 16777619) >>> 0;
  }

  return hash / 0x100000000;
}

function getStableBurnTransferFieldAngle(id: string): number {
  let hash = 2166136261;

  for (let index = 0; index < id.length; index += 1) {
    hash ^= id.charCodeAt(index);
    hash = Math.imul(hash, 16777619) >>> 0;
  }

  return (hash / 0x100000000) * Math.PI * 2;
}

function setShaderUniformNumber(
  material: THREE.Material | THREE.Material[],
  key: string,
  value: number
): void {
  for (const shaderMaterial of getShaderMaterials(material)) {
    const uniform = shaderMaterial.uniforms[key];

    if (uniform !== undefined) {
      uniform.value = value;
    }
  }
}

function setObjectShaderUniformNumber(object: THREE.Object3D, key: string, value: number): void {
  object.traverse((child) => {
    if (!isDisposableRenderable(child)) {
      return;
    }

    setShaderUniformNumber(child.material, key, value);
  });
}

function setShaderUniformVector(
  material: THREE.Material | THREE.Material[],
  key: string,
  value: THREE.Vector3
): void {
  for (const shaderMaterial of getShaderMaterials(material)) {
    const uniform = shaderMaterial.uniforms[key];

    if (uniform !== undefined && uniform.value instanceof THREE.Vector3) {
      uniform.value.copy(value);
    }
  }
}

function syncDynamicSolarLightingMaterial(
  material: THREE.Material | THREE.Material[],
  enabled: boolean,
  sunRadius: number,
  occluders: readonly DynamicSolarOccluder[]
): void {
  for (const shaderMaterial of getShaderMaterials(material)) {
    const strengthUniform = shaderMaterial.uniforms["dynamicSolarLightingStrength"];
    const sunRadiusUniform = shaderMaterial.uniforms["dynamicSolarSunRadius"];
    const countUniform = shaderMaterial.uniforms["dynamicSolarOccluderCount"];
    const occludersUniform = shaderMaterial.uniforms["dynamicSolarOccluders"];

    if (
      strengthUniform === undefined ||
      sunRadiusUniform === undefined ||
      countUniform === undefined ||
      occludersUniform === undefined ||
      !Array.isArray(occludersUniform.value)
    ) {
      continue;
    }

    strengthUniform.value = enabled ? 1 : 0;
    sunRadiusUniform.value = Math.max(0, sunRadius);
    countUniform.value = Math.min(maxDynamicSolarOccluders, occluders.length);

    for (let index = 0; index < maxDynamicSolarOccluders; index += 1) {
      const uniformValue: unknown = occludersUniform.value[index];

      if (!(uniformValue instanceof THREE.Vector4)) {
        continue;
      }

      const occluder = occluders[index];
      if (occluder === undefined) {
        uniformValue.set(0, 0, 0, 0);
      } else {
        uniformValue.set(
          occluder.position.x,
          occluder.position.y,
          occluder.position.z,
          occluder.radius
        );
      }
    }
  }
}

function setShaderUniformColor(
  material: THREE.Material | THREE.Material[],
  key: string,
  value: THREE.ColorRepresentation
): void {
  for (const shaderMaterial of getShaderMaterials(material)) {
    const uniform = shaderMaterial.uniforms[key];

    if (uniform !== undefined && uniform.value instanceof THREE.Color) {
      uniform.value.set(value);
    }
  }
}

function isVector3Array(value: unknown): value is THREE.Vector3[] {
  return Array.isArray(value) && value.every((item) => item instanceof THREE.Vector3);
}

function isNumberArray(value: unknown): value is number[] {
  return Array.isArray(value) && value.every((item) => typeof item === "number");
}

function isColorArray(value: unknown): value is THREE.Color[] {
  return Array.isArray(value) && value.every((item) => item instanceof THREE.Color);
}

function getShaderMaterials(material: THREE.Material | THREE.Material[]): THREE.ShaderMaterial[] {
  const materials = Array.isArray(material) ? material : [material];
  return materials.filter((candidate): candidate is THREE.ShaderMaterial => {
    return candidate instanceof THREE.ShaderMaterial;
  });
}

function getProductiveMarkerZoomOutFallbackPulseIntensity(phase: number): number {
  const clampedPhase = clamp(phase, 0, 1);
  const attack = 0.08;
  const decay = 0.48;

  if (clampedPhase < attack) {
    const progress = clampedPhase / attack;
    return 1 - (1 - progress) ** 3;
  }

  if (clampedPhase < decay) {
    const progress = (clampedPhase - attack) / Math.max(0.001, decay - attack);
    return 1 - progress ** 3 * 0.82;
  }

  return 0;
}

function getNumericUserData(object: THREE.Object3D, key: string): number {
  const userData = object.userData as Record<string, unknown>;
  const value = userData[key];
  return typeof value === "number" ? value : 0;
}

function getStringUserData(object: THREE.Object3D, key: string): string {
  const userData = object.userData as Record<string, unknown>;
  const value = userData[key];
  return typeof value === "string" ? value : "";
}

function roundDiagnosticNumber(value: number): number {
  return Math.round(value * 1000) / 1000;
}

function roundDiagnosticVector(vector: THREE.Vector3): readonly number[] {
  return [
    roundDiagnosticNumber(vector.x),
    roundDiagnosticNumber(vector.y),
    roundDiagnosticNumber(vector.z)
  ];
}

function readDiagnosticNumberProperty(object: object, key: string): number | null {
  const value = (object as Record<string, unknown>)[key];
  return typeof value === "number" ? value : null;
}

function readDiagnosticBooleanProperty(object: object, key: string): boolean | null {
  const value = (object as Record<string, unknown>)[key];
  return typeof value === "boolean" ? value : null;
}

function getDiagnosticMaterialColor(material: THREE.Material): string | null {
  const color = (material as THREE.Material & { color?: unknown }).color;

  if (color instanceof THREE.Color) {
    return `#${color.getHexString()}`;
  }

  if (material instanceof THREE.ShaderMaterial) {
    for (const key of ["color", "baseColor", "accentColor", "shadowCoreColor"]) {
      const uniform = material.uniforms[key];

      if (uniform?.value instanceof THREE.Color) {
        return `#${uniform.value.getHexString()}`;
      }
    }
  }

  return null;
}

function disposeObject(object: THREE.Object3D): void {
  object.traverse((child: THREE.Object3D) => {
    if (isDisposableRenderable(child)) {
      if (child instanceof THREE.Sprite) {
        // Sprite geometry is managed by Three.js; dispose the material below.
      } else if (child.userData["usesSharedGeometry"] !== true) {
        child.geometry.dispose();
      }

      if (Array.isArray(child.material)) {
        for (const material of child.material) {
          material.dispose();
        }
      } else {
        child.material.dispose();
      }
    }
  });
}

function createTutorialNodeToNodeCameraAssistControlFocus(
  startFocus: THREE.Vector3,
  targetFocus: THREE.Vector3
): THREE.Vector3 {
  const travel = targetFocus.clone().sub(startFocus);
  travel.y = 0;
  const travelDistance = travel.length();

  if (travelDistance <= 0.001) {
    return startFocus.clone().lerp(targetFocus, 0.5);
  }

  const midpoint = startFocus.clone().lerp(targetFocus, 0.5);
  const lateral = new THREE.Vector3(-travel.z, 0, travel.x).normalize();
  const outward = midpoint.clone();
  outward.y = 0;

  if (outward.lengthSq() > 0.0001 && lateral.dot(outward.normalize()) < 0) {
    lateral.negate();
  }

  const curveAmount = clamp(
    travelDistance * tutorialNodeToNodeCameraAssistCurveDistanceRatio,
    tutorialNodeToNodeCameraAssistCurveMinWorldUnits,
    tutorialNodeToNodeCameraAssistCurveMaxWorldUnits
  );

  return midpoint.addScaledVector(lateral, curveAmount);
}

function sampleTutorialNodeToNodeCameraAssistFocus(
  startFocus: THREE.Vector3,
  curveControlFocus: THREE.Vector3,
  targetFocus: THREE.Vector3,
  progress: number,
  output: THREE.Vector3
): THREE.Vector3 {
  const clampedProgress = clamp(progress, 0, 1);
  const inverseProgress = 1 - clampedProgress;

  return output
    .copy(startFocus)
    .multiplyScalar(inverseProgress * inverseProgress)
    .addScaledVector(curveControlFocus, 2 * inverseProgress * clampedProgress)
    .addScaledVector(targetFocus, clampedProgress * clampedProgress);
}

function clearGroup(group: THREE.Group): void {
  for (const child of [...group.children]) {
    group.remove(child);
    disposeObject(child);
  }
}

function isDisposableRenderable(child: THREE.Object3D): child is DisposableRenderable {
  return (
    child instanceof THREE.Mesh ||
    child instanceof THREE.Line ||
    child instanceof THREE.Points ||
    child instanceof THREE.Sprite
  );
}

function isObjectTreeVisible(object: THREE.Object3D): boolean {
  for (let current: THREE.Object3D | null = object; current !== null; current = current.parent) {
    if (!current.visible) {
      return false;
    }
  }

  return true;
}

function hasNamedObjectAncestor(object: THREE.Object3D, name: string): boolean {
  for (let current: THREE.Object3D | null = object; current !== null; current = current.parent) {
    if (current.name === name) {
      return true;
    }
  }

  return false;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function smoothStep(edge0: number, edge1: number, value: number): number {
  const scaled = clamp((value - edge0) / Math.max(0.0001, edge1 - edge0), 0, 1);
  return scaled * scaled * (3 - 2 * scaled);
}

function scoreOpeningScreenTarget(
  value: number,
  target: number,
  tolerance = multiplayerOpeningScreenTargetTolerance
): number {
  return 1 - clamp(Math.abs(value - target) / Math.max(0.0001, tolerance), 0, 1);
}

function smootherStep(edge0: number, edge1: number, value: number): number {
  const scaled = clamp((value - edge0) / Math.max(0.0001, edge1 - edge0), 0, 1);
  return scaled * scaled * scaled * (scaled * (scaled * 6 - 15) + 10);
}

function fract(value: number): number {
  return value - Math.floor(value);
}

function positiveModulo(value: number, period: number): number {
  return ((value % period) + period) % period;
}

const solarDustTextureSize = 768;
const deepSpaceBackgroundWidth = 2048;
const deepSpaceBackgroundHeight = 1024;

function createDeepSpaceBackgroundTexture(): THREE.CanvasTexture {
  const canvas = document.createElement("canvas");
  canvas.width = deepSpaceBackgroundWidth;
  canvas.height = deepSpaceBackgroundHeight;
  const context = canvas.getContext("2d");

  if (context === null) {
    throw new Error("Cannot create deep space background texture without a 2D canvas context.");
  }

  const image = context.createImageData(deepSpaceBackgroundWidth, deepSpaceBackgroundHeight);
  const pixels = image.data;

  for (let y = 0; y < deepSpaceBackgroundHeight; y += 1) {
    const vertical = y / Math.max(1, deepSpaceBackgroundHeight - 1);
    const eclipticDistance = Math.abs(vertical - 0.55);
    const eclipticHaze = Math.exp(-Math.pow(eclipticDistance / 0.34, 2));
    const upperSkyLift = smoothStep(0.05, 0.92, 1 - vertical);

    for (let x = 0; x < deepSpaceBackgroundWidth; x += 1) {
      const horizontal = x / Math.max(1, deepSpaceBackgroundWidth - 1);
      const index = (y * deepSpaceBackgroundWidth + x) * 4;
      const solarPlaneLift = eclipticHaze * 0.82;
      const horizonSweep = Math.sin(horizontal * Math.PI * 1.15 + vertical * Math.PI * 0.42) * 0.18;
      const dither =
        (fract(Math.sin((x + 0.5) * 12.9898 + (y + 0.5) * 78.233) * 43758.5453) - 0.5) * 0.72;
      const lift = clamp(upperSkyLift * 0.22 + solarPlaneLift + horizonSweep, 0, 1.4);

      pixels[index] = Math.round(7.2 + lift * 3.8 + dither);
      pixels[index + 1] = Math.round(15.4 + lift * 6.8 + dither);
      pixels[index + 2] = Math.round(24.4 + lift * 10.6 + dither);
      pixels[index + 3] = 255;
    }
  }

  context.putImageData(image, 0, 0);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.generateMipmaps = false;
  texture.needsUpdate = true;
  return texture;
}

function createSolarDustTextureCanvas(): HTMLCanvasElement {
  const canvas = document.createElement("canvas");
  canvas.width = solarDustTextureSize;
  canvas.height = solarDustTextureSize;
  const context = canvas.getContext("2d");

  if (context === null) {
    throw new Error("Cannot create solar dust texture without a 2D canvas context.");
  }

  const image = context.createImageData(solarDustTextureSize, solarDustTextureSize);
  const pixels = image.data;

  for (let y = 0; y < solarDustTextureSize; y += 1) {
    for (let x = 0; x < solarDustTextureSize; x += 1) {
      const index = (y * solarDustTextureSize + x) * 4;
      const large = interpolatedTileableNoise2d(x / 128, y / 128, 6, 3);
      const medium = interpolatedTileableNoise2d(x / 64 + 2.1, y / 64 + 4.6, 12, 19);
      const fine = interpolatedTileableNoise2d(x / 24 + 9.2, y / 24 + 1.7, 32, 41);
      const material = clamp(large * 0.52 + medium * 0.34 + fine * 0.14, 0, 1);
      const vein = Math.pow(material, 1.45);
      const alpha = clamp(0.08 + vein * 0.44, 0, 0.48);
      const cold = clamp(vein * 0.65 + medium * 0.2, 0, 1);

      pixels[index] = Math.round(64 + cold * 36);
      pixels[index + 1] = Math.round(84 + cold * 44);
      pixels[index + 2] = Math.round(112 + cold * 54);
      pixels[index + 3] = Math.round(alpha * 255);
    }
  }

  context.putImageData(image, 0, 0);
  return canvas;
}

function interpolatedTileableNoise2d(x: number, y: number, period: number, seed: number): number {
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const xBlend = smoothStep(0, 1, fract(x));
  const yBlend = smoothStep(0, 1, fract(y));
  const topLeft = tileableValueNoise2d(x0, y0, period, seed);
  const topRight = tileableValueNoise2d(x0 + 1, y0, period, seed);
  const bottomLeft = tileableValueNoise2d(x0, y0 + 1, period, seed);
  const bottomRight = tileableValueNoise2d(x0 + 1, y0 + 1, period, seed);
  const top = THREE.MathUtils.lerp(topLeft, topRight, xBlend);
  const bottom = THREE.MathUtils.lerp(bottomLeft, bottomRight, xBlend);
  return THREE.MathUtils.lerp(top, bottom, yBlend);
}

function tileableValueNoise2d(x: number, y: number, period: number, frame: number): number {
  const wrappedX = positiveModulo(x, period);
  const wrappedY = positiveModulo(y, period);
  return valueNoise2d(wrappedX, wrappedY, frame);
}

function easeTurnProgress(
  progress: number,
  ease: Cinematic3dVisualTuning["turnAnimationEase"]
): number {
  const clamped = clamp(progress, 0, 1);

  if (ease === "smootherstep") {
    return clamped * clamped * clamped * (clamped * (clamped * 6 - 15) + 10);
  }

  return clamped * clamped * (3 - 2 * clamped);
}

function valueNoise2d(x: number, y: number, frame: number): number {
  let seed = x * 374761393 + y * 668265263 + frame * 2246822519;
  seed = (seed ^ (seed >>> 13)) * 1274126177;
  return ((seed ^ (seed >>> 16)) >>> 0) / 4294967295;
}

function computeDistanceFade(distance: number, start: number, end: number): number {
  if (end <= start) {
    return 1;
  }

  return clamp(1 - (distance - start) / (end - start), 0.32, 1);
}

const fullFireTrajectoryVisualWeight: FireTrajectoryVisualWeight = {
  opacityMultiplier: 1,
  thicknessMultiplier: 1,
  timingOpacityMultiplier: 1,
  timingRadiusMultiplier: 1,
  targetOpacityMultiplier: 1,
  labelOpacityMultiplier: 1
};

function getFullFireTrajectoryVisualWeight(): FireTrajectoryVisualWeight {
  return fullFireTrajectoryVisualWeight;
}

function getFireEtaTurns(plan: RenderableFirePlan, visualTurn: number): number {
  return Math.max(0, Math.ceil(plan.impactTurn - visualTurn));
}

function getFireTrajectoryVisualWeight(etaTurns: number): FireTrajectoryVisualWeight {
  if (etaTurns <= 1) {
    return fullFireTrajectoryVisualWeight;
  }

  if (etaTurns === 2) {
    return {
      opacityMultiplier: 0.72,
      thicknessMultiplier: 0.86,
      timingOpacityMultiplier: 0.82,
      timingRadiusMultiplier: 0.88,
      targetOpacityMultiplier: 0.9,
      labelOpacityMultiplier: 0.92
    };
  }

  if (etaTurns === 3) {
    return {
      opacityMultiplier: 0.56,
      thicknessMultiplier: 0.74,
      timingOpacityMultiplier: 0.7,
      timingRadiusMultiplier: 0.8,
      targetOpacityMultiplier: 0.78,
      labelOpacityMultiplier: 0.8
    };
  }

  return {
    opacityMultiplier: 0.52,
    thicknessMultiplier: 0.72,
    timingOpacityMultiplier: 0.68,
    timingRadiusMultiplier: 0.78,
    targetOpacityMultiplier: 0.76,
    labelOpacityMultiplier: 0.78
  };
}

function getTrajectoryEtaLabelClassName(text: string, kind: TrajectoryLabelKind): string | null {
  if (kind !== "fire" && kind !== "fire-field" && kind !== "fire-summary") {
    return null;
  }

  const match = /^T-(\d+)/.exec(text);

  if (match === null) {
    return null;
  }

  const etaTurns = Number(match[1]);

  if (etaTurns <= 1) {
    return "cinematic-trajectory-label--eta-imminent";
  }

  if (etaTurns <= 3) {
    return "cinematic-trajectory-label--eta-near";
  }

  return "cinematic-trajectory-label--eta-late";
}

function estimateTrajectoryLabelSize(text: string, kind: TrajectoryLabelKind): TrajectoryLabelSize {
  if (kind === "burn-field" || kind === "fire-field") {
    return {
      width: clamp(text.length * 6.8 + 12, 28, 54),
      height: 18
    };
  }

  if (kind === "burn-hover") {
    return {
      width: clamp(text.length * 7.4 + 16, 56, 132),
      height: 24
    };
  }

  return {
    width: clamp(text.length * 8.2 + 20, 54, kind === "fire-summary" ? 148 : 132),
    height: 28
  };
}

function getTrajectoryLabelPreferredOffset(kind: TrajectoryLabelKind): Vec2 {
  return kind === "burn-hover"
    ? { x: 1, y: -6 }
    : kind === "burn-field"
      ? { x: 0, y: -5 }
      : kind === "fire-field"
        ? { x: 1, y: -4 }
        : { x: 12, y: -14 };
}

function getTrajectoryLabelOffsetCandidates(
  kind: TrajectoryLabelKind,
  size: TrajectoryLabelSize
): Vec2[] {
  const preferred = getTrajectoryLabelPreferredOffset(kind);
  const preferredCenter = {
    x: preferred.x + size.width * 0.5,
    y: preferred.y + size.height * 0.5
  };
  const baseAngle = Math.atan2(preferredCenter.y, preferredCenter.x);
  const baseDistance = clamp(
    Math.hypot(preferredCenter.x, preferredCenter.y),
    kind === "burn-field" || kind === "fire-field" ? 10 : 18,
    kind === "burn-field" || kind === "fire-field" ? 28 : 46
  );
  const angleOffsets = [0, -0.55, 0.55, -1.05, 1.05, 1.72, -1.72, Math.PI, -2.42, 2.42];
  const distanceMultipliers =
    kind === "burn-field" || kind === "fire-field" ? [1, 1.45, 2.05, 2.8] : [1, 1.35, 1.85, 2.45];
  const candidates: Vec2[] = [preferred];

  for (const distanceMultiplier of distanceMultipliers) {
    for (const angleOffset of angleOffsets) {
      const angle = baseAngle + angleOffset;
      const distance = baseDistance * distanceMultiplier;
      candidates.push({
        x: Math.cos(angle) * distance - size.width * 0.5,
        y: Math.sin(angle) * distance - size.height * 0.5
      });
    }
  }

  return candidates;
}

function computeRectOverlapArea(first: ScreenRect, second: ScreenRect): number {
  const width = Math.max(
    0,
    Math.min(first.x + first.width, second.x + second.width) - Math.max(first.x, second.x)
  );
  const height = Math.max(
    0,
    Math.min(first.y + first.height, second.y + second.height) - Math.max(first.y, second.y)
  );
  return width * height;
}

function createCenteredScreenRect(center: Vec2, radius: number): ScreenRect {
  return {
    x: center.x - radius,
    y: center.y - radius,
    width: radius * 2,
    height: radius * 2
  };
}

function labelsOverlap(first: ScreenRect, second: ScreenRect): boolean {
  return (
    first.x < second.x + second.width + 4 &&
    first.x + first.width + 4 > second.x &&
    first.y < second.y + second.height + 4 &&
    first.y + first.height + 4 > second.y
  );
}

function getCinematicLabelOffsetCandidates(context: {
  labelWidth: number;
  labelHeight: number;
  preferredSide: 1 | -1;
  sideGap: number;
  topGap: number;
  allowLongRange: boolean;
}): CinematicLabelOffsetCandidate[] {
  const candidates: CinematicLabelOffsetCandidate[] = [];
  const oppositeSide = context.preferredSide > 0 ? -1 : 1;
  const sideOrder: Array<1 | -1> = [context.preferredSide, oppositeSide];
  const distanceMultipliers = context.allowLongRange ? [1, 1.55, 2.25, 3.2, 4.25] : [1, 1.65];
  const verticalMultipliers = context.allowLongRange
    ? [-0.5, -1.2, 0.45, -2.05, 1.35, -3, 2.25]
    : [-0.5, -1.1, 0.45];

  for (const side of sideOrder) {
    for (const distanceMultiplier of distanceMultipliers) {
      const x =
        side > 0
          ? context.sideGap * distanceMultiplier
          : -context.labelWidth - context.sideGap * distanceMultiplier;

      for (const verticalMultiplier of verticalMultipliers) {
        candidates.push({
          x,
          y:
            verticalMultiplier < 0
              ? context.labelHeight * verticalMultiplier -
                context.topGap * Math.max(0, -verticalMultiplier - 0.5)
              : context.topGap * verticalMultiplier,
          side
        });
      }
    }
  }

  const centeredVerticalOffsets = context.allowLongRange
    ? [
        -context.labelHeight - context.topGap,
        context.topGap,
        -context.labelHeight - context.topGap * 2.2,
        context.topGap * 2.2
      ]
    : [-context.labelHeight - context.topGap, context.topGap];

  for (const y of centeredVerticalOffsets) {
    candidates.push({
      x: -context.labelWidth / 2,
      y,
      side: context.preferredSide
    });
  }

  return candidates;
}

function projectWorldPointToScreen(
  worldPoint: THREE.Vector3,
  camera: THREE.Camera,
  width: number,
  height: number
): Vec2 | null {
  const projected = worldPoint.clone().project(camera);

  if (
    projected.z < -1 ||
    projected.z > 1 ||
    projected.x < -1.3 ||
    projected.x > 1.3 ||
    projected.y < -1.3 ||
    projected.y > 1.3
  ) {
    return null;
  }

  return {
    x: (projected.x * 0.5 + 0.5) * width,
    y: (-projected.y * 0.5 + 0.5) * height
  };
}

function projectWorldPointToViewportScreen(
  worldPoint: THREE.Vector3,
  camera: THREE.Camera,
  width: number,
  height: number
): Vec2 | null {
  const projected = worldPoint.clone().project(camera);

  if (
    projected.z < -1 ||
    projected.z > 1 ||
    projected.x < -1 ||
    projected.x > 1 ||
    projected.y < -1 ||
    projected.y > 1
  ) {
    return null;
  }

  return {
    x: (projected.x * 0.5 + 0.5) * width,
    y: (-projected.y * 0.5 + 0.5) * height
  };
}

function projectWorldPointToExtendedScreen(
  worldPoint: THREE.Vector3,
  camera: THREE.Camera,
  width: number,
  height: number
): Vec2 | null {
  const projected = worldPoint.clone().project(camera);
  const cameraSpace = worldPoint.clone().applyMatrix4(camera.matrixWorldInverse);

  if (
    !Number.isFinite(projected.x) ||
    !Number.isFinite(projected.y) ||
    !Number.isFinite(projected.z) ||
    projected.z < -1 ||
    projected.z > 1 ||
    cameraSpace.z >= -0.001
  ) {
    return null;
  }

  return {
    x: (projected.x * 0.5 + 0.5) * width,
    y: (-projected.y * 0.5 + 0.5) * height
  };
}

function getCameraForwardDistance(
  camera: THREE.PerspectiveCamera,
  worldPoint: THREE.Vector3
): number {
  const forward = new THREE.Vector3();
  camera.getWorldDirection(forward);
  return Math.max(1, worldPoint.clone().sub(camera.position).dot(forward));
}

function unprojectScreenPointAtCameraForwardDistance(
  point: Vec2,
  camera: THREE.PerspectiveCamera,
  width: number,
  height: number,
  forwardDistance: number
): THREE.Vector3 {
  const normalized = new THREE.Vector3(
    (point.x / Math.max(1, width)) * 2 - 1,
    -(point.y / Math.max(1, height)) * 2 + 1,
    0.5
  );
  const rayDirection = normalized.unproject(camera).sub(camera.position).normalize();
  const cameraForward = new THREE.Vector3();
  camera.getWorldDirection(cameraForward);
  const forwardDot = Math.max(0.001, rayDirection.dot(cameraForward));

  return camera.position.clone().addScaledVector(rayDirection, forwardDistance / forwardDot);
}

function clampScreenPointToRect(point: Vec2, rect: ScreenRect): Vec2 {
  return {
    x: clamp(point.x, rect.x, rect.x + rect.width),
    y: clamp(point.y, rect.y, rect.y + rect.height)
  };
}

function isScreenPointInsideRect(point: Vec2, rect: ScreenRect): boolean {
  return (
    point.x >= rect.x &&
    point.x <= rect.x + rect.width &&
    point.y >= rect.y &&
    point.y <= rect.y + rect.height
  );
}

function projectWorldPointToThreatScreen(
  worldPoint: THREE.Vector3,
  camera: THREE.Camera,
  width: number,
  height: number,
  margin: number
): ProjectedThreatPoint {
  const projected = worldPoint.clone().project(camera);
  const cameraSpace = worldPoint.clone().applyMatrix4(camera.matrixWorldInverse);
  let ndcX = projected.x;
  let ndcY = projected.y;
  const isUsableProjection =
    Number.isFinite(ndcX) &&
    Number.isFinite(ndcY) &&
    Number.isFinite(projected.z) &&
    cameraSpace.z < -0.001;

  if (!isUsableProjection) {
    const planarLength = Math.hypot(cameraSpace.x, cameraSpace.y);

    if (planarLength <= 0.001) {
      ndcX = 0;
      ndcY = cameraSpace.z >= 0 ? -1.6 : 0;
    } else {
      const scale = 1.6 / planarLength;
      ndcX = cameraSpace.x * scale;
      ndcY = cameraSpace.y * scale;
    }
  }

  const screen = {
    x: (ndcX * 0.5 + 0.5) * width,
    y: (-ndcY * 0.5 + 0.5) * height
  };
  const isOnScreen =
    isUsableProjection &&
    projected.z >= -1 &&
    projected.z <= 1 &&
    screen.x >= margin &&
    screen.x <= width - margin &&
    screen.y >= margin &&
    screen.y <= height - margin;

  return {
    screen,
    isOnScreen
  };
}

function clampScreenPointToEdge(point: Vec2, width: number, height: number, margin: number): Vec2 {
  const center = { x: width / 2, y: height / 2 };
  let directionX = point.x - center.x;
  let directionY = point.y - center.y;

  if (Math.hypot(directionX, directionY) <= 0.001) {
    directionX = 0;
    directionY = -1;
  }

  const halfWidth = Math.max(1, width / 2 - margin);
  const halfHeight = Math.max(1, height / 2 - margin);
  const scale = Math.min(
    halfWidth / Math.max(0.001, Math.abs(directionX)),
    halfHeight / Math.max(0.001, Math.abs(directionY))
  );

  return {
    x: center.x + directionX * scale,
    y: center.y + directionY * scale
  };
}

function getThreatIndicatorEdge(
  point: Vec2,
  width: number,
  height: number,
  margin: number
): ScreenEdge {
  const distances = [
    { edge: "top" as const, distance: Math.abs(point.y - margin) },
    { edge: "right" as const, distance: Math.abs(point.x - (width - margin)) },
    { edge: "bottom" as const, distance: Math.abs(point.y - (height - margin)) },
    { edge: "left" as const, distance: Math.abs(point.x - margin) }
  ];

  distances.sort((first, second) => first.distance - second.distance);
  return distances[0]?.edge ?? "top";
}

function getAlternatingStackOffset(index: number, spacing: number): number {
  if (index === 0) {
    return 0;
  }

  const magnitude = Math.ceil(index / 2) * spacing;
  return index % 2 === 0 ? magnitude : -magnitude;
}

function distanceToScreenSegment(point: Vec2, first: Vec2, second: Vec2): number {
  const segmentX = second.x - first.x;
  const segmentY = second.y - first.y;
  const lengthSquared = segmentX * segmentX + segmentY * segmentY;

  if (lengthSquared <= 0.001) {
    return Math.hypot(point.x - first.x, point.y - first.y);
  }

  const progress = clamp(
    ((point.x - first.x) * segmentX + (point.y - first.y) * segmentY) / lengthSquared,
    0,
    1
  );
  const closest = {
    x: first.x + segmentX * progress,
    y: first.y + segmentY * progress
  };
  return Math.hypot(point.x - closest.x, point.y - closest.y);
}

function isPointInsideScreenPolygon(point: Vec2, polygon: readonly Vec2[]): boolean {
  let inside = false;

  for (let index = 0, previousIndex = polygon.length - 1; index < polygon.length; index += 1) {
    const current = polygon[index];
    const previous = polygon[previousIndex];

    if (current === undefined || previous === undefined) {
      previousIndex = index;
      continue;
    }

    const crossesY = current.y > point.y !== previous.y > point.y;

    if (crossesY) {
      const intersectionX =
        ((previous.x - current.x) * (point.y - current.y)) / (previous.y - current.y) + current.x;

      if (point.x < intersectionX) {
        inside = !inside;
      }
    }

    previousIndex = index;
  }

  return inside;
}

function createCoronaTexture(): THREE.CanvasTexture {
  const size = 1024;
  const center = size / 2;
  const radius = size * 0.48;
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const context = canvas.getContext("2d");

  if (context === null) {
    throw new Error("Cannot create Sun corona texture without a 2D canvas context.");
  }

  const image = context.createImageData(size, size);
  const pixels = image.data;

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const index = (y * size + x) * 4;
      const dx = (x + 0.5 - center) / radius;
      const dy = (y + 0.5 - center) / radius;
      const distance = Math.hypot(dx, dy);
      const innerFade = smoothStep(0.72, 0.82, distance);
      const outerFade = 1 - smoothStep(0.865, 0.95, distance);
      const limbBand = Math.exp(-Math.pow((distance - 0.84) / 0.105, 2));
      const alphaNoise =
        (fract(Math.sin((x + 0.5) * 19.19 + (y + 0.5) * 41.41) * 24634.6345) - 0.5) * 0.004;
      const alpha = clamp(
        innerFade * outerFade * (0.5 + limbBand * 0.38) + alphaNoise * 0.5 * innerFade * outerFade,
        0,
        0.9
      );

      pixels[index] = 255;
      pixels[index + 1] = 255;
      pixels[index + 2] = 255;
      pixels[index + 3] = Math.round(alpha * 255);
    }
  }

  context.putImageData(image, 0, 0);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.generateMipmaps = false;
  texture.needsUpdate = true;
  return texture;
}

function createSmoothSolarGlareTexture(): THREE.CanvasTexture {
  const canvas = document.createElement("canvas");
  const size = 1024;
  const center = size / 2;
  const visibleRadius = size * 0.46;
  canvas.width = size;
  canvas.height = size;
  const context = canvas.getContext("2d");

  if (context === null) {
    throw new Error("Cannot create smooth solar glare texture without a 2D canvas context.");
  }

  const image = context.createImageData(size, size);
  const pixels = image.data;

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const index = (y * size + x) * 4;
      const dx = (x + 0.5 - center) / visibleRadius;
      const dy = (y + 0.5 - center) / visibleRadius;
      const distance = Math.hypot(dx, dy);
      const innerClear = smoothStep(0.58, 0.72, distance);
      const edgeFade = 1 - smoothStep(0.76, 1, distance);
      const mid = Math.exp(-distance * distance * 3.2) * 0.16;
      const skirt = Math.exp(-distance * distance * 0.82) * 0.042;
      const alphaNoise =
        (fract(Math.sin((x + 0.5) * 12.9898 + (y + 0.5) * 78.233) * 43758.5453) - 0.5) * 0.005;
      const alpha = clamp(
        (mid + skirt) * edgeFade * innerClear + alphaNoise * edgeFade * innerClear,
        0,
        0.34
      );

      pixels[index] = 255;
      pixels[index + 1] = 255;
      pixels[index + 2] = 255;
      pixels[index + 3] = Math.round(alpha * 255);
    }
  }

  context.putImageData(image, 0, 0);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.generateMipmaps = false;
  texture.needsUpdate = true;
  return texture;
}

const radialGlowTextures = new Map<string, THREE.CanvasTexture>();
const sharpPointTextures = new Map<string, THREE.CanvasTexture>();
const bokehPointTextures = new Map<string, THREE.CanvasTexture>();
function getRadialGlowTexture(name: string, color: THREE.ColorRepresentation): THREE.CanvasTexture {
  const cacheKey = `${name}:${new THREE.Color(color).getHexString()}`;
  const existing = radialGlowTextures.get(cacheKey);

  if (existing !== undefined) {
    return existing;
  }

  const size = 128;
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const context = canvas.getContext("2d");

  if (context === null) {
    throw new Error(`Cannot create radial glow texture for ${name} without a 2D context.`);
  }

  const glowColor = new THREE.Color(color);
  const center = size / 2;
  const gradient = context.createRadialGradient(center, center, 0, center, center, center);
  const rgb = `${Math.round(glowColor.r * 255)}, ${Math.round(glowColor.g * 255)}, ${Math.round(
    glowColor.b * 255
  )}`;
  gradient.addColorStop(0, `rgba(${rgb}, 1)`);
  gradient.addColorStop(0.18, `rgba(${rgb}, 0.64)`);
  gradient.addColorStop(0.48, `rgba(${rgb}, 0.18)`);
  gradient.addColorStop(1, `rgba(${rgb}, 0)`);
  context.fillStyle = gradient;
  context.fillRect(0, 0, size, size);

  const texture = new THREE.CanvasTexture(canvas);
  texture.name = `${name}-texture`;
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.needsUpdate = true;
  radialGlowTextures.set(cacheKey, texture);
  return texture;
}

function getSharpPointTexture(name: string, color: THREE.ColorRepresentation): THREE.CanvasTexture {
  const cacheKey = `${name}:${new THREE.Color(color).getHexString()}`;
  const existing = sharpPointTextures.get(cacheKey);

  if (existing !== undefined) {
    return existing;
  }

  const size = 64;
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const context = canvas.getContext("2d");

  if (context === null) {
    throw new Error(`Cannot create sharp point texture for ${name} without a 2D context.`);
  }

  const glowColor = new THREE.Color(color);
  const center = size / 2;
  const rgb = `${Math.round(glowColor.r * 255)}, ${Math.round(glowColor.g * 255)}, ${Math.round(
    glowColor.b * 255
  )}`;

  context.clearRect(0, 0, size, size);
  context.beginPath();
  context.arc(center, center, 9.5, 0, Math.PI * 2);
  context.fillStyle = `rgba(${rgb}, 0.96)`;
  context.fill();
  context.beginPath();
  context.arc(center, center, 4.2, 0, Math.PI * 2);
  context.fillStyle = "rgba(255, 255, 255, 0.98)";
  context.fill();

  const texture = new THREE.CanvasTexture(canvas);
  texture.name = `${name}-texture`;
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.magFilter = THREE.NearestFilter;
  texture.minFilter = THREE.NearestFilter;
  texture.generateMipmaps = false;
  texture.needsUpdate = true;
  sharpPointTextures.set(cacheKey, texture);
  return texture;
}

function getBokehPointTexture(name: string, color: THREE.ColorRepresentation): THREE.CanvasTexture {
  const cacheKey = `${name}:${new THREE.Color(color).getHexString()}`;
  const existing = bokehPointTextures.get(cacheKey);

  if (existing !== undefined) {
    return existing;
  }

  const size = 128;
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const context = canvas.getContext("2d");

  if (context === null) {
    throw new Error(`Cannot create bokeh point texture for ${name} without a 2D context.`);
  }

  const glowColor = new THREE.Color(color);
  const center = size / 2;
  const visibleRadius = size * 0.42;
  const image = context.createImageData(size, size);

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const pixelIndex = (y * size + x) * 4;
      const dx = (x + 0.5 - center) / visibleRadius;
      const dy = (y + 0.5 - center) / visibleRadius;
      const angle = Math.atan2(dy, dx);
      const sector = Math.PI / 4;
      const localAngle = Math.abs(positiveModulo(angle + sector / 2, sector) - sector / 2);
      const octagonRadius = Math.cos(sector / 2) / Math.max(0.12, Math.cos(localAngle));
      const distance = Math.hypot(dx, dy) / octagonRadius;
      const edge = 1 - smoothStep(0.72, 1, distance);
      const aperture = 1 - smoothStep(0.9, 1.08, distance);
      const broadFill = 0.64 + (1 - clamp(distance, 0, 1)) * 0.05;
      const alpha = clamp(broadFill * edge * aperture, 0, 0.68);

      image.data[pixelIndex] = Math.round(glowColor.r * 255);
      image.data[pixelIndex + 1] = Math.round(glowColor.g * 255);
      image.data[pixelIndex + 2] = Math.round(glowColor.b * 255);
      image.data[pixelIndex + 3] = Math.round(alpha * 255);
    }
  }

  context.putImageData(image, 0, 0);

  const texture = new THREE.CanvasTexture(canvas);
  texture.name = `${name}-texture`;
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.generateMipmaps = false;
  texture.needsUpdate = true;
  bokehPointTextures.set(cacheKey, texture);
  return texture;
}

let retinalFlashTexture: THREE.CanvasTexture | null = null;
let retinalPointGeometry: THREE.BufferGeometry | null = null;

function getRetinalPointGeometry(): THREE.BufferGeometry {
  if (retinalPointGeometry !== null) {
    return retinalPointGeometry;
  }

  retinalPointGeometry = new THREE.BufferGeometry();
  retinalPointGeometry.setAttribute("position", new THREE.Float32BufferAttribute([0, 0, 0], 3));
  return retinalPointGeometry;
}

function createRetinalFlashPoint(
  name: string,
  position: THREE.Vector3,
  color: THREE.ColorRepresentation,
  pixelSize: number,
  opacity: number,
  renderOrder: number,
  depthTest = false
): THREE.Points<THREE.BufferGeometry, THREE.PointsMaterial> {
  const material = new THREE.PointsMaterial({
    color,
    map: getRetinalFlashTexture(),
    size: pixelSize,
    sizeAttenuation: false,
    transparent: true,
    opacity,
    depthWrite: false,
    depthTest,
    blending: THREE.AdditiveBlending
  });
  material.toneMapped = false;

  const point = new THREE.Points(getRetinalPointGeometry(), material);
  point.name = name;
  point.position.copy(position);
  point.renderOrder = renderOrder;
  point.userData["usesSharedGeometry"] = true;
  return point;
}

function getRetinalFlashTexture(): THREE.CanvasTexture {
  if (retinalFlashTexture !== null) {
    return retinalFlashTexture;
  }

  const canvas = document.createElement("canvas");
  canvas.width = 192;
  canvas.height = 192;
  const context = canvas.getContext("2d");

  if (context === null) {
    throw new Error("Cannot create missile impact retinal flash texture without a 2D context.");
  }

  const center = canvas.width / 2;
  const gradient = context.createRadialGradient(center, center, 0, center, center, center);
  gradient.addColorStop(0, "rgba(255, 255, 255, 1)");
  gradient.addColorStop(0.1, "rgba(255, 255, 255, 0.94)");
  gradient.addColorStop(0.27, "rgba(222, 248, 255, 0.42)");
  gradient.addColorStop(0.58, "rgba(130, 208, 255, 0.12)");
  gradient.addColorStop(1, "rgba(0, 0, 0, 0)");
  context.fillStyle = gradient;
  context.fillRect(0, 0, canvas.width, canvas.height);

  retinalFlashTexture = new THREE.CanvasTexture(canvas);
  retinalFlashTexture.colorSpace = THREE.SRGBColorSpace;
  retinalFlashTexture.minFilter = THREE.LinearFilter;
  retinalFlashTexture.magFilter = THREE.LinearFilter;
  return retinalFlashTexture;
}

function createStarTexture(): THREE.CanvasTexture {
  const canvas = document.createElement("canvas");
  const size = 32;
  canvas.width = size;
  canvas.height = size;
  const context = canvas.getContext("2d");

  if (context === null) {
    throw new Error("Cannot create star texture without a 2D canvas context.");
  }

  const image = context.createImageData(size, size);
  const center = (size - 1) / 2;

  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const dx = x - center;
      const dy = y - center;
      const distance = Math.sqrt(dx * dx + dy * dy);
      const core = Math.exp(-distance * distance * 0.42);
      const glow = Math.exp(-distance * distance * 0.052) * 0.16;
      const alpha = clamp(core * 0.98 + glow, 0, 1);
      const index = (y * size + x) * 4;
      image.data[index] = 248;
      image.data[index + 1] = 251;
      image.data[index + 2] = 255;
      image.data[index + 3] = Math.round(alpha * 255);
    }
  }

  context.putImageData(image, 0, 0);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.generateMipmaps = false;
  return texture;
}
